                    name: '领取免费礼包',
                    execute: async () => {
                        const r = await executeGameCommand('card_claimreward', { cardId: 1 }, '领取免费礼包');
                        try { syncDailyStatusFromServer(r, 'default'); } catch (_) { }
                    }
