    // ==================== 爬塔功能  ====================

    // 获取爬塔信息
    async function getRealTowerInfo() {
        try {
            logMessage('获取爬塔信息...', 'info');

            // 方法1: 优先使用tower_getinfo专用命令获取
            try {
                const response = await executeGameCommand('tower_getinfo', {}, '获取塔信息');
                if (response?.code === 0) {
                    // 尝试多种可能的响应结构
                    let towerData = response._rawData || response.data || response;

                    if (towerData && (towerData.id !== undefined || towerData.energy !== undefined)) {
                        const currentLayer = towerData.id || 1;
                        const currentEnergy = towerData.energy || 0;
                        logMessage(`从tower_getinfo获取爬塔信息: 第${formatLayer(currentLayer + 1)}层, 体力: ${currentEnergy}`, 'success');
                        return {
                            success: true,
                            layer: currentLayer,
                            energy: currentEnergy,
                            source: 'towerCommand'
                        };
                    }
                }
            } catch (error) {
                logMessage(`tower_getinfo命令失败: ${error.message}`, 'warning');
            }

            // 方法2: 尝试从游戏全局变量获取（备用）
            const gameApp = window.gameApp || unsafeWindow?.gameApp;
            if (gameApp && gameApp.iso && gameApp.iso.role) {
                const role = gameApp.iso.role;
                if (role.tower) {
                    const currentLayer = role.tower.id || 1;
                    const currentEnergy = role.tower.energy || 0;
                    logMessage(`从游戏全局变量获取爬塔信息: 第${formatLayer(currentLayer + 1)}层, 体力: ${currentEnergy}`, 'success');
                    return {
                        success: true,
                        layer: currentLayer,
                        energy: currentEnergy,
                        source: 'global'
                    };
                }
            }

            // 方法3: 尝试从角色信息中获取（最后备选）
            const roleInfo = await getRoleInfo();
            if (roleInfo.success && roleInfo.roleData && roleInfo.roleData.tower) {
                const currentLayer = roleInfo.roleData.tower.id || 1;
                const currentEnergy = roleInfo.roleData.tower.energy || 0;
                logMessage(`从角色信息获取爬塔信息: 第${formatLayer(currentLayer + 1)}层, 体力: ${currentEnergy}`, 'success');
                return {
                    success: true,
                    layer: currentLayer,
                    energy: currentEnergy,
                    source: 'roleInfo'
                };
            }

            // 所有方法都失败
            throw new Error('无法获取爬塔信息');

        } catch (error) {
            logMessage(`获取爬塔信息失败: ${error.message}`, 'error');
            return {
                success: false,
                layer: 1,
                energy: 0,
                source: 'fallback'
            };
        }
    }

    // 强制刷新爬塔信息
    async function forceRefreshTowerInfo() {
        try {
            logMessage('强制刷新爬塔信息...', 'info');

            // 强制调用tower_getinfo命令
            const response = await executeGameCommand('tower_getinfo', {}, '强制获取塔信息');

            if (response?.code === 0) {
                // 等待数据同步
                await delay(1000);

                // 再次尝试获取信息
                return await getRealTowerInfo();
            } else {
                throw new Error(`强制刷新失败，响应码: ${response?.code}`);
            }
        } catch (error) {
            logMessage(`强制刷新爬塔信息失败: ${error.message}`, 'error');
            return await getRealTowerInfo();
        }
    }

    // 爬塔状态显示
    async function updateTowerStatusDisplay() {
        try {
            const towerInfo = await getRealTowerInfo();

            // 全局状态（保存原始层数）
            globalState.tower.currentLayer = towerInfo.layer;
            globalState.tower.currentEnergy = towerInfo.energy;

            // UI显示（显示当前要挑战的层数，即原始层数+1）
            const currentLayerElement = document.getElementById('current-layer-tower');
            const currentEnergyElement = document.getElementById('current-energy-tower');

            if (currentLayerElement) {
                currentLayerElement.textContent = `第${formatLayer(towerInfo.layer + 1)}层`;
            }
            if (currentEnergyElement) {
                currentEnergyElement.textContent = towerInfo.energy;
            }

            return towerInfo;
        } catch (error) {
            logMessage(`更新爬塔状态显示失败: ${error.message}`, 'error');
            return null;
        }
    }

    // 启动爬塔倒计时
    function startTowerCountdown() {
        // 清除现有的倒计时
        if (globalState.tower.countdown.intervalId) {
            clearInterval(globalState.tower.countdown.intervalId);
        }

        // 从本地存储加载下次执行时间
        const savedNextExecution = localStorage.getItem('tower_next_execution');
        if (savedNextExecution) {
            globalState.tower.countdown.nextExecution = parseInt(savedNextExecution);
        } else {
            // 如果没有保存的时间，设置为当前时间+间隔
            globalState.tower.countdown.nextExecution = Date.now() + globalState.tower.interval;
            localStorage.setItem('tower_next_execution', globalState.tower.countdown.nextExecution.toString());
        }

        // 启动倒计时更新
        globalState.tower.countdown.intervalId = setInterval(() => {
            updateTowerCountdown();
        }, 1000);

        // 立即更新一次
        updateTowerCountdown();
    }

    // 更新爬塔倒计时显示
    function updateTowerCountdown() {
        const timeElement = document.getElementById('remaining-time-tower');
        if (!timeElement) return;

        const now = Date.now();
        const nextExecution = globalState.tower.countdown.nextExecution;

        if (nextExecution > now) {
            const remaining = nextExecution - now;
            const hours = Math.floor(remaining / (1000 * 60 * 60));
            const minutes = Math.floor((remaining % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((remaining % (1000 * 60)) / 1000);

            const timeString = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
            timeElement.textContent = timeString;
        } else {
            timeElement.textContent = '00:00:00';

            // 如果倒计时结束且正在运行中，执行爬塔任务
            if (globalState.tower.isRunning && !globalState.tower.isPaused) {
                // 重置下次执行时间
                globalState.tower.countdown.nextExecution = now + globalState.tower.interval;
                localStorage.setItem('tower_next_execution', globalState.tower.countdown.nextExecution.toString());

                // 执行爬塔任务
                executeTowerTask();
            }
        }
    }

    // 停止爬塔倒计时
    function stopTowerCountdown() {
        if (globalState.tower.countdown.intervalId) {
            clearInterval(globalState.tower.countdown.intervalId);
            globalState.tower.countdown.intervalId = null;
        }

        // 清除本地存储
        localStorage.removeItem('tower_next_execution');

        const timeElement = document.getElementById('remaining-time-tower');
        if (timeElement) {
            timeElement.textContent = '--:--:--';
        }
    }

    // 领取爬塔章节奖励函数
    async function claimReward(chapter) {
        let retryCount = 0;
        const maxRetries = 2;

        // 尝试两种rewardId格式：章节号(1,2,3...)和层数(10,20,30...)
        const rewardIdFormats = [chapter, chapter * 10];

        for (const rewardId of rewardIdFormats) {
            try {
                logMessage(`尝试领取第${chapter}章奖励 (rewardId=${rewardId})...`, 'info');

                await delay(500);

                const response = await executeGameCommand('tower_claimreward',
                    { rewardId: rewardId },
                    `领取第${chapter}章奖励`
                );

                // 详细记录响应
                logMessage(`tower_claimreward响应: ${JSON.stringify(response).substring(0, 200)}`, 'info');

                if (response) {
                    // 检查多种成功标志
                    const code = response?.code ?? response?._rawData?.code ?? -1;
                    const hasReward = response?._rawData?.reward || response?.reward;

                    if (code === 0 || hasReward) {
                        logMessage(`✅ 第${chapter}章奖励领取成功 (rewardId=${rewardId})`, 'success');
                        return true;
                    }

                    // 检查是否已领取
                    if (code === 11900007 || code === 11800002 || code === 11700001) {
                        logMessage(`第${chapter}章奖励已领取过`, 'info');
                        return true;
                    }

                    logMessage(`rewardId=${rewardId} 失败，响应码: ${code}`, 'warning');
                }
            } catch (error) {
                // 如果报错但包含“已领取”相关信息，视为成功
                const errMsg = error.message || '';
                if (errMsg.includes('11900007') || errMsg.includes('11800002') || errMsg.includes('11700001')) {
                    logMessage(`第${chapter}章奖励已领取过`, 'info');
                    return true;
                }
                logMessage(`rewardId=${rewardId} 异常: ${errMsg}`, 'warning');
            }
        }

        logMessage(`第${chapter}章奖励领取失败，继续爬塔`, 'warning');
        return false;
    }

    // 咸将塔自动爬塔 - 使用本地计算减少服务器请求
    async function executeTowerTask() {
        if (globalState.tower.isRunning) {
            showTip('爬塔任务正在运行中', 'warning');
            return;
        }

        globalState.tower.isRunning = true;
        globalState.tower.isPaused = false;
        globalState.tower.lastRunTime = Date.now();

        logMessage('🏯 ===== 开始爬塔流程 =====', 'success');

        // 本地更新UI显示函数（显示当前要挑战的层数，即原始层数+1）
        function updateLocalTowerUI(layer, energy) {
            const currentLayerElement = document.getElementById('current-layer-tower');
            const currentEnergyElement = document.getElementById('current-energy-tower');
            if (currentLayerElement) {
                currentLayerElement.textContent = `第${formatLayer(layer + 1)}层`;
            }
            if (currentEnergyElement) {
                currentEnergyElement.textContent = energy;
            }
            globalState.tower.currentLayer = layer;
            globalState.tower.currentEnergy = energy;
        }

        try {
            const towerFormation = parseInt(document.getElementById('towerFormationSelect')?.value) || globalState.tower.towerFormation;
            globalState.tower.towerFormation = towerFormation;
            updateTowerButtonStates();

            // 切换到爬塔阵容
            logMessage('检查并切换到爬塔阵容...', 'info');
            const formationSwitched = await switchToFormationIfNeeded(towerFormation, '爬塔阵容');

            if (!formationSwitched) {
                logMessage('阵容切换可能失败，但继续执行流程', 'warning');
            }

            // 只在开始时获取一次塔信息
            let towerInfo = await updateTowerStatusDisplay();
            if (!towerInfo || !towerInfo.success) {
                logMessage('无法获取爬塔信息', 'error');
                return;
            }

            let currentEnergy = towerInfo.energy;
            let currentLayer = towerInfo.layer;

            logMessage(`开始爬塔: 当前第${formatLayer(currentLayer + 1)}层, 体力: ${currentEnergy}`, 'info');

            // 检查是否需要领取上一章奖励（当layer为X-1格式，如121=12-1，说明刚通关了12-10但未领取奖励）
            if (currentLayer % 10 === 1 && currentLayer > 10) {
                const lastChapter = Math.floor(currentLayer / 10);
                logMessage(`🎁 检测到第${lastChapter}章已通关（${formatLayer(currentLayer - 1)}），尝试领取奖励...`, 'info');
                try {
                    const rewardSuccess = await claimReward(lastChapter);
                    if (rewardSuccess) {
                        logMessage(`✅ 第${lastChapter}章奖励领取成功`, 'success');
                        // 刷新体力信息
                        await delay(300);
                        const updatedInfo = await updateTowerStatusDisplay();
                        if (updatedInfo && updatedInfo.success) {
                            currentEnergy = updatedInfo.energy;
                            currentLayer = updatedInfo.layer;
                        }
                    }
                } catch (e) {
                    logMessage(`领取第${lastChapter}章奖励异常: ${e.message}`, 'warning');
                }
            }

            // 检查是否已达到4500层
            if (currentLayer >= 4500) {
                logMessage('已达到4500层，停止爬塔', 'success');
                return;
            }

            // 检查体力
            if (currentEnergy <= 0) {
                logMessage('体力不足，无法挑战', 'warning');
                showTip('体力不足', 'warning');
                return;
            }

            let totalWins = 0;
            let totalLosses = 0;

            // 循环挑战 - 使用本地计算体力和层数
            while (currentEnergy > 0 && currentLayer < 4500 && globalState.tower.isRunning) {
                logMessage(`准备挑战第 ${formatLayer(currentLayer + 1)} 层...`, 'info');

                try {
                    // 执行战斗
                    const fightResponse = await executeGameCommand('fight_starttower', {}, '塔战斗');

                    if (!fightResponse) {
                        logMessage('战斗响应异常', 'error');
                        totalLosses++;
                        break;
                    }

                    // 通过战斗响应判断胜负
                    // fightResponse.data.isWin 或 fightResponse.data.result 判断
                    const isWin = fightResponse?.data?.isWin === true ||
                        fightResponse?.data?.isWin === 1 ||
                        fightResponse?.data?.result === 1 ||
                        fightResponse?.data?.win === true ||
                        fightResponse?.data?.win === 1;

                    if (isWin) {
                        // 胜利：本地层数+1
                        totalWins++;
                        currentLayer++;
                        updateLocalTowerUI(currentLayer, currentEnergy);
                        logMessage(`✅ 第 ${formatLayer(currentLayer)} 层通关！剩余体力: ${currentEnergy}`, 'success');

                        // 检查是否为章节通关层（每章第10层，即layer整陖10的倍数）
                        // layer=10对应1-10, layer=20对应2-10, layer=290对应29-10
                        if (currentLayer % 10 === 0) {
                            // rewardId为章节号，即layer/10
                            const chapter = currentLayer / 10;
                            logMessage(`🎁 恭喜通关第${chapter}章（${formatLayer(currentLayer)}），准备领取奖励...`, 'info');

                            try {
                                // 尝试领取奖励，使用章节号作为rewardId
                                const rewardSuccess = await claimReward(chapter);
                                if (rewardSuccess) {
                                    // 领取奖励后需要获取最新体力（奖励可能增加体力）
                                    await delay(300);
                                    const updatedInfo = await updateTowerStatusDisplay();
                                    if (updatedInfo && updatedInfo.success) {
                                        const energyGain = updatedInfo.energy - currentEnergy;
                                        if (energyGain > 0) {
                                            logMessage(`✅ 成功领取第${chapter}章奖励，体力+${energyGain}`, 'success');
                                        } else {
                                            logMessage(`✅ 成功领取第${chapter}章奖励`, 'success');
                                        }
                                        // 同步服务器返回的真实数据
                                        currentEnergy = updatedInfo.energy;
                                        currentLayer = updatedInfo.layer;
                                    }
                                } else {
                                    logMessage(`第${chapter}章奖励领取失败，可能已领取过，继续爬塔`, 'warning');
                                }
                            } catch (rewardErr) {
                                logMessage(`领取第${chapter}章奖励异常: ${rewardErr.message}`, 'warning');
                            }
                        }
                    } else {
                        // 失败：本地体力-1
                        totalLosses++;
                        currentEnergy--;
                        updateLocalTowerUI(currentLayer, currentEnergy);
                        logMessage(`❌ 第 ${formatLayer(currentLayer + 1)} 层失败，剩余体力: ${currentEnergy}`, 'warning');
                    }

                    // 检查体力
                    if (currentEnergy <= 0) {
                        logMessage('体力已用完', 'warning');
                        break;
                    }

                    // 检查层数上限
                    if (currentLayer >= 4500) {
                        logMessage('已达到4500层', 'success');
                        break;
                    }

                    // 简短延迟后继续下一次战斗
                    await delay(300);

                } catch (error) {
                    logMessage(`挑战异常: ${error.message}`, 'error');
                    totalLosses++;
                    // 异常时从服务器同步一次数据
                    await delay(500);
                    towerInfo = await updateTowerStatusDisplay();
                    if (towerInfo && towerInfo.success) {
                        currentEnergy = towerInfo.energy;
                        currentLayer = towerInfo.layer;
                    }
                    break;
                }
            }

            // 最终同步一次服务器数据
            const finalInfo = await updateTowerStatusDisplay();
            if (finalInfo && finalInfo.success) {
                currentLayer = finalInfo.layer;
                currentEnergy = finalInfo.energy;

                // 检查爬塔结束时是否需要领取奖励（当最终layer为X-1格式）
                if (currentLayer % 10 === 1 && currentLayer > 10) {
                    const lastChapter = Math.floor(currentLayer / 10);
                    logMessage(`🎁 爬塔结束，检测到第${lastChapter}章已通关，尝试领取奖励...`, 'info');
                    try {
                        await claimReward(lastChapter);
                    } catch (e) {
                        logMessage(`领取第${lastChapter}章奖励异常: ${e.message}`, 'warning');
                    }
                }
            }

            const totalBattles = totalWins + totalLosses;
            logMessage(`🏯 爬塔完成，共进行 ${totalBattles} 次挑战，胜利 ${totalWins} 次，失败 ${totalLosses} 次`, 'success');
            logMessage(`最终层数: 第${formatLayer(currentLayer + 1)}层, 剩余体力: ${currentEnergy}`, 'info');
            showTip(`爬塔完成 (胜${totalWins}/负${totalLosses})`, 'success');

        } catch (error) {
            const errorMsg = error.message || '未知错误';
            logMessage(`❌ ===== 爬塔失败: ${errorMsg} =====`, 'error');
            showTip(`爬塔失败: ${errorMsg}`, 'error');
        } finally {
            globalState.tower.isRunning = false;
            globalState.tower.isPaused = false;
            updateTowerButtonStates();
        }
    }

    function stopTower() {
        if (!globalState.tower.isRunning) {
            showTip('爬塔未运行', 'warning');
            return;
        }

        globalState.tower.isRunning = false;
        globalState.tower.isPaused = false;
        stopTowerCountdown();
        showTip('爬塔已停止', 'info');
        updateTowerButtonStates();
    }

    function startTowerLoop() {
        if (globalState.tower.isRunning) {
            showTip('爬塔循环已在运行中', 'warning');
            return;
        }

        globalState.tower.isRunning = true;
        globalState.tower.isPaused = false;

        // 启动倒计时
        startTowerCountdown();
        updateTowerButtonStates();

        showTip('自动爬塔循环已启动', 'success');
        logMessage('自动爬塔循环已启动', 'info');
    }

    function updateTowerButtonStates() {
        const startLoopBtn = document.getElementById('startTowerLoopBtn');
        const stopLoopBtn = document.getElementById('stopTowerLoopBtn');
        const executeBtn = document.getElementById('executeTowerBtn');

        if (startLoopBtn) {
            startLoopBtn.disabled = globalState.tower.isRunning;
        }

        if (stopLoopBtn) {
            stopLoopBtn.disabled = !globalState.tower.isRunning;
        }

        if (executeBtn) {
            executeBtn.disabled = globalState.tower.isRunning;
        }
    }

