    // 答题任务函数
    async function answerTask() {
        if (globalState.quiz.isRunning) {
            showTip('答题任务正在运行中', 'warning');
            return;
        }

        globalState.quiz.isRunning = true;
        updateQuizButtonStates();

        try {
            logMessage('📚 ===== 开始答题任务 =====', 'success');

            let data;
            const gameWS = window.ws || unsafeWindow?.ws;
            const gameApp = window.gameApp || unsafeWindow?.gameApp;

            // 尝试两种方式启动答题游戏
            if (gameApp && gameApp.iso && gameApp.iso.StudyService) {
                data = await gameApp.iso.StudyService.startGame({});
            } else {
                const msg = window.g_utils?.bon?.encode
                    ? {
                        ack: 0,
                        body: window.g_utils.bon.encode({}),
                        cmd: 'study_startgame',
                        seq: Date.now(),
                        time: Date.now()
                    }
                    : {
                        ack: 0,
                        cmd: 'study_startgame',
                        params: {},
                        seq: Date.now(),
                        time: Date.now()
                    };
                data = await gameWS.sendAsync(msg);
            }

            const gameData = data.getData ? data.getData() : data._rawData;
            const questionList = gameData.questionList;

            globalState.quiz.totalQuestions = questionList.length;
            globalState.quiz.progress = 0;

            logMessage(`开始答题，共${questionList.length}题`, 'info');

            for (let idx = 0; idx < questionList.length; idx++) {
                if (!globalState.quiz.isRunning) break;

                const question = questionList[idx];
                globalState.quiz.progress = idx + 1;
                updateQuizProgress();

                let answer = tiku[question.question];
                if (!answer) {
                    answer = Math.floor(2 * Math.random()) + 1;
                    logMessage(`题库未找到答案，随机选择: ${answer}`, 'warning');
                }

                logMessage(`问题 ${idx + 1}/${questionList.length}: ${question.question} -> 答案: ${answer}`, 'info');

                if (gameApp && gameApp.iso && gameApp.iso.StudyService) {
                    await gameApp.iso.StudyService.answer({
                        id: gameData.role.study.id,
                        option: [answer],
                        questionId: [question.id]
                    });
                } else {
                    const answerMsg = window.g_utils?.bon?.encode
                        ? {
                            ack: 0,
                            body: window.g_utils.bon.encode({
                                id: gameData.role.study.id,
                                option: [answer],
                                questionId: [question.id]
                            }),
                            cmd: 'study_answer',
                            seq: Date.now(),
                            time: Date.now()
                        }
                        : {
                            ack: 0,
                            cmd: 'study_answer',
                            params: {
                                id: gameData.role.study.id,
                                option: [answer],
                                questionId: [question.id]
                            },
                            seq: Date.now(),
                            time: Date.now()
                        };
                    await gameWS.sendAsync(answerMsg);
                }

                if (idx < questionList.length - 1) await delay(100);
            }

            if (globalState.quiz.isRunning) {
                logMessage(`所有答案已发送`, 'success');

                // 领取奖励
                for (let rewardId = 1; rewardId <= 10; rewardId++) {
                    if (!globalState.quiz.isRunning) break;

                    if (gameApp && gameApp.iso && gameApp.iso.StudyService) {
                        await gameApp.iso.StudyService.claimReward({ rewardId: rewardId });
                    } else {
                        const rewardMsg = window.g_utils?.bon?.encode
                            ? {
                                ack: 0,
                                body: window.g_utils.bon.encode({ rewardId }),
                                cmd: 'study_claimreward',
                                seq: Date.now(),
                                time: Date.now()
                            }
                            : {
                                ack: 0,
                                cmd: 'study_claimreward',
                                params: { rewardId },
                                seq: Date.now(),
                                time: Date.now()
                            };
                        await gameWS.sendAsync(rewardMsg);
                    }

                    logMessage(`领取奖励 ${rewardId}/10`, 'info');
                    if (rewardId < 10) await delay(50);
                }

                logMessage(`所有奖励已领取`, 'success');
                logMessage(`答题任务完成，共${questionList.length}题`, 'success');
                showTip('答题任务完成', 'success');
            }

        } catch (error) {
            logMessage(`答题任务失败: ${error.message}`, 'error');
            showTip(`答题任务失败: ${error.message}`, 'error');
        } finally {
            globalState.quiz.isRunning = false;
            updateQuizButtonStates();
            updateQuizProgress();
        }
    }

    function stopQuiz() {
        if (!globalState.quiz.isRunning) {
            showTip('答题未运行', 'warning');
            return;
        }

        globalState.quiz.isRunning = false;
        showTip('答题已停止', 'info');
        updateQuizButtonStates();
    }

    function updateQuizButtonStates() {
        const startBtn = document.getElementById('executeQuizBtn');
        const stopBtn = document.getElementById('stopQuizBtn');

        if (startBtn) {
            startBtn.disabled = globalState.quiz.isRunning;
        }

        if (stopBtn) {
            stopBtn.disabled = !globalState.quiz.isRunning;
        }
    }

    function updateQuizProgress() {
        const progressElement = document.getElementById('quizProgress');
        if (progressElement) {
            if (globalState.quiz.isRunning && globalState.quiz.totalQuestions > 0) {
                progressElement.textContent = `${globalState.quiz.progress}/${globalState.quiz.totalQuestions}`;
            } else {
                progressElement.textContent = '--/--';
            }
        }
    }

