    // 检查梦境开放时间（周三/周四/周日/周一）
    function isDungeonOpen() {
        const now = new Date();
        const day = now.getDay(); // 0=周日, 1=周一, 2=周二, 3=周三, 4=周四, 5=周五, 6=周六
        return day === 0 || day === 1 || day === 3 || day === 4; // 周日、周一、周三、周四
    }

    // 安全的梦境日志函数
    function dreamLogMessage(content, type = 'info') {
        try {
            logMessage(content, type);
        } catch (error) {
            // 如果日志系统出现问题，降级到控制台输出
            console.log(`[梦境-${type}] ${content}`);
        }
    }

    // 提取默认队伍信息
    function extractDefaultInfoFromResponse(response) {
        try {
            if (!response) {
                return false;
            }
            let extracted = false;
            if (response._rawData && response._rawData.role && response._rawData.role.battleTeam) {
                globalState.dream.battle.defaultTeam = response._rawData.role.battleTeam;

                // 提取英雄信息用于显示
                globalState.dream.battle.currentTeamHeroes = [];
                for (let i = 0; i < 5; i++) {
                    const heroKey = i.toString();
                    if (globalState.dream.battle.defaultTeam[heroKey]) {
                        const heroInfo = globalState.dream.battle.defaultTeam[heroKey];
                        const heroId = heroInfo.heroId || heroInfo;
                        if (heroId !== 0 && heroData[heroId]) {
                            globalState.dream.battle.currentTeamHeroes.push({
                                id: heroId,
                                name: heroData[heroId].name,
                                type: heroData[heroId].type,
                                quality: heroData[heroId].quality,
                                position: i
                            });
                        }
                    }
                }
                dreamLogMessage('✅ 提取到默认队伍信息', 'success');
                extracted = true;
            }
            if (extracted) {
                globalState.dream.battle.hasDefaultInfo = true;
            }
            return extracted;
        } catch (error) {
            dreamLogMessage(`❌ 提取默认信息出错: ${error.message}`, 'error');
            return false;
        }
    }

    // 显示阵容选择弹窗
    function showFormationSelectionModal() {
        return new Promise((resolve) => {
            const modal = document.createElement('div');
            modal.className = 'formation-modal';
            modal.innerHTML = `
                <div class="formation-modal-content">
                    <div class="formation-modal-title">选择阵容</div>
                    <div class="formation-options">
                        <div class="formation-option" data-formation="1">阵容1</div>
                        <div class="formation-option" data-formation="2">阵容2</div>
                        <div class="formation-option" data-formation="3">阵容3</div>
                        <div class="formation-option" data-formation="4">阵容4</div>
                        <div class="formation-option" data-formation="5">阵容5</div>
                        <div class="formation-option" data-formation="6">阵容6</div>
                    </div>
                    <div class="formation-modal-buttons">
                        <button class="formation-cancel-btn">取消</button>
                        <button class="formation-confirm-btn">确认选择</button>
                    </div>
                </div>
            `;
            document.body.appendChild(modal);
            let selectedFormation = null;
            const options = modal.querySelectorAll('.formation-option');
            const confirmBtn = modal.querySelector('.formation-confirm-btn');
            const cancelBtn = modal.querySelector('.formation-cancel-btn');

            // 选择阵容
            options.forEach(option => {
                option.addEventListener('click', () => {
                    options.forEach(opt => opt.classList.remove('selected'));
                    option.classList.add('selected');
                    selectedFormation = parseInt(option.getAttribute('data-formation'));
                });
            });

            // 确认选择
            confirmBtn.addEventListener('click', () => {
                if (selectedFormation) {
                    modal.remove();
                    resolve(selectedFormation);
                } else {
                    showTip('请先选择一个阵容', 'warning');
                }
            });

            // 取消选择
            cancelBtn.addEventListener('click', () => {
                modal.remove();
                resolve(null);
            });

            // 点击模态框外部关闭
            modal.addEventListener('click', (e) => {
                if (e.target === modal) {
                    modal.remove();
                    resolve(null);
                }
            });
        });
    }

    // 切换到指定阵容 
    async function switchToDreamFormation(formationId) {
        try {
            dreamLogMessage(`正在切换到阵容${formationId}...`, 'info');

            const switchSuccess = await switchToFormationIfNeeded(formationId, '梦境阵容');

            if (switchSuccess) {
                dreamLogMessage(`✅ 成功切换到阵容${formationId}`, 'success');

                dreamLogMessage(`🔄 强制刷新角色信息获取最新阵容数据...`, 'info');
                const roleInfoResponse = await executeGameCommand('role_getroleinfo', {}, '刷新角色信息');
                if (roleInfoResponse) {
                    const extracted = extractDefaultInfoFromResponse(roleInfoResponse);
                    if (extracted) {
                        dreamLogMessage(`✅ 成功获取阵容${formationId}的最新数据`, 'success');
                        return true;
                    } else {
                        dreamLogMessage(`⚠️ 切换到阵容${formationId}但无法提取最新阵容数据`, 'warning');
                        return true;
                    }
                }
                return true;
            } else {
                throw new Error('切换阵容失败');
            }
        } catch (error) {
            dreamLogMessage(`❌ 切换阵容失败: ${error.message}`, 'error');

            dreamLogMessage(`🔄 强制刷新角色信息获取最新阵容数据...`, 'info');
            try {
                const roleInfoResponse = await executeGameCommand('role_getroleinfo', {}, '刷新角色信息');
                if (roleInfoResponse) {
                    const extracted = extractDefaultInfoFromResponse(roleInfoResponse);
                    if (extracted) {
                        dreamLogMessage(`✅ 成功获取阵容${formationId}的最新数据`, 'success');
                        return true;
                    } else {
                        dreamLogMessage(`❌ 获取队伍信息出错：切换阵容失败`, 'error');
                        return false;
                    }
                } else {
                    dreamLogMessage(`❌ 获取队伍信息出错：切换阵容失败`, 'error');
                    return false;
                }
            } catch (refreshError) {
                dreamLogMessage(`❌ 刷新角色信息失败: ${refreshError.message}`, 'error');
                return false;
            }
        }
    }

    // 获取默认队伍信息
    async function getDefaultTeamInfo() {
        if (globalState.dream.battle.isLoading) {
            showTip('操作正在进行中', 'warning');
            return false;
        }
        if (!isDungeonOpen()) {
            showTip('当前不是梦境开放时间（周三/周四/周日/周一）', 'error');
            dreamLogMessage('❌ 当前不是梦境开放时间', 'error');
            return false;
        }

        // 显示阵容选择弹窗
        const selectedFormation = await showFormationSelectionModal();
        if (!selectedFormation) {
            dreamLogMessage('❌ 用户取消了阵容选择', 'info');
            return false;
        }
        globalState.dream.battle.isLoading = true;
        updateDreamButtonStates();
        dreamLogMessage(`获取阵容${selectedFormation}的队伍信息...`, 'info');
        showTip(`正在获取阵容${selectedFormation}的队伍信息...`, 'info');
        try {
            // 先切换到选择的阵容
            const switchSuccess = await switchToDreamFormation(selectedFormation);
            if (!switchSuccess) {
                throw new Error('切换阵容失败');
            }

            // 等待阵容切换生效
            await delay(1000);

            // 获取角色信息 - 确保变量正确声明
            const roleInfoResponse = await executeGameCommand('role_getroleinfo', {}, '获取角色信息');
            if (roleInfoResponse) {
                const extracted = extractDefaultInfoFromResponse(roleInfoResponse);
                if (extracted) {
                    dreamLogMessage(`✅ 阵容${selectedFormation}队伍信息获取成功`, 'success');
                    showTip(`阵容${selectedFormation}队伍信息获取成功`, 'success');
                    updateDreamTeamDisplay();
                    updateDreamQuickActionButtons();
                    return true;
                } else {
                    dreamLogMessage('❌ 无法提取队伍数据', 'error');
                    showTip('获取队伍信息失败', 'error');
                    return false;
                }
            } else {
                dreamLogMessage('❌ 获取角色信息失败', 'error');
                showTip('获取角色信息失败', 'error');
                return false;
            }
        } catch (error) {
            // 使用安全的方式记录错误
            const errorMessage = error.message || '未知错误';
            dreamLogMessage(`❌ 获取队伍信息出错: ${errorMessage}`, 'error');
            showTip('获取队伍信息失败', 'error');
            return false;
        } finally {
            globalState.dream.battle.isLoading = false;
            updateDreamButtonStates();
        }
    }

    // 选择梦境阵容 - 实现真正的自由选择阵容
    async function selectDreamTeam() {
        if (globalState.dream.battle.isLoading) {
            showTip('操作正在进行中', 'warning');
            return;
        }
        if (!isDungeonOpen()) {
            showTip('当前不是梦境开放时间（周三/周四/周日/周一）', 'error');
            dreamLogMessage('❌ 当前不是梦境开放时间', 'error');
            return;
        }
        if (!globalState.dream.battle.hasDefaultInfo) {
            const success = await getDefaultTeamInfo();
            if (!success) {
                showTip('请先获取默认队伍', 'warning');
                return;
            }
        }
        globalState.dream.battle.isLoading = true;
        updateDreamButtonStates();
        dreamLogMessage('选择梦境阵容...', 'info');
        showTip('正在选择梦境阵容...', 'info');
        try {
            const battleTeam = {};
            let hasHero = false;
            for (let i = 0; i < 5; i++) {
                if (globalState.dream.battle.defaultTeam && globalState.dream.battle.defaultTeam[i.toString()]) {
                    const heroInfo = globalState.dream.battle.defaultTeam[i.toString()];
                    const heroId = heroInfo.heroId || heroInfo;
                    battleTeam[i.toString()] = heroId;
                    if (heroId !== 0) {
                        hasHero = true;
                    }
                } else {
                    battleTeam[i.toString()] = 0;
                }
            }
            if (!hasHero) {
                dreamLogMessage('⚠️ 默认队伍中没有英雄', 'warning');
                showTip('队伍中没有英雄', 'warning');
                return;
            }
            const response = await executeGameCommand('dungeon_selecthero', {
                battleTeam: battleTeam
            }, '选择梦境阵容');
            if (response) {
                dreamLogMessage(`✅ 梦境阵容选择成功`, 'success');
                showTip('梦境阵容选择成功', 'success');

                // 解析奖励数据
                const rawData = response._rawData;
                if (rawData && rawData.reward) {
                    const rewards = Array.isArray(rawData.reward) ? rawData.reward : [rawData.reward];
                    rewards.forEach(reward => {
                        if (reward.type === 3) { // 物品类型
                            dreamLogMessage(`🎁 获得物品: ID=${reward.itemId}, 数量=${reward.value}`, 'success');
                        } else if (reward.type === 12) {
                            dreamLogMessage(`📦 获得特殊物品: ID=${reward.itemId}, 数量=${reward.value}`, 'success');
                        }
                    });
                }
            } else {
                throw new Error('选择梦境阵容失败');
            }
        } catch (error) {
            const errorMessage = error.message || '未知错误';
            dreamLogMessage(`❌ 选择梦境阵容出错: ${errorMessage}`, 'error');
            showTip('选择阵容失败', 'error');
        } finally {
            globalState.dream.battle.isLoading = false;
            updateDreamButtonStates();
        }
    }

    // 单个英雄战斗
    async function startSingleBattle(heroId) {
        const heroName = heroData[heroId] ? heroData[heroId].name : `ID:${heroId}`;
        dreamLogMessage(`⚔️ 开始战斗: ${heroName}`, 'info');
        try {
            const response = await executeGameCommand('fight_startdungeon', {
                heroId: parseInt(heroId)
            }, '开始梦境战斗');
            if (response) {
                // 解析战斗结果
                const rawData = response._rawData;
                if (rawData) {
                    if (rawData.isWin) {
                        dreamLogMessage(`🎉 ${heroName} 战斗胜利!`, 'success');
                    } else {
                        dreamLogMessage(`💔 ${heroName} 战斗失败`, 'warning');
                    }

                    // 解析奖励
                    if (rawData.reward) {
                        const rewards = Array.isArray(rawData.reward) ? rawData.reward : [rawData.reward];
                        rewards.forEach(reward => {
                            if (reward.type === 3) {
                                dreamLogMessage(`🎁 ${heroName} 战斗获得物品: ID=${reward.itemId}, 数量=${reward.value}`, 'success');
                            }
                        });
                    }
                }
                return true;
            } else {
                throw new Error('开始战斗失败');
            }
        } catch (error) {
            // 检查是否是2600080或2600050错误码
            if (error.message.includes('2600080') || error.message.includes('2600050')) {
                const errorCode = error.message.includes('2600080') ? '2600080' : '2600050';
                dreamLogMessage(`⏹️ ${heroName} 连续战斗已停止 (错误码: ${errorCode})`, 'warning');
                return 'stop'; // 返回特殊值表示需要停止
            } else {
                dreamLogMessage(`❌ ${heroName} 开始战斗出错: ${error.message}`, 'error');
                return false;
            }
        }
    }

    // 连续战斗功能
    async function startContinuousBattle(heroId) {
        const heroName = heroData[heroId] ? heroData[heroId].name : `ID:${heroId}`;

        // 如果已经在连续战斗中，先停止
        if (globalState.dream.battle.continuousBattles[heroId]) {
            stopContinuousBattle(heroId);
            return;
        }

        // 设置连续战斗状态
        globalState.dream.battle.continuousBattles[heroId] = true;
        updateDreamQuickActionButtons();
        updateDreamTeamDisplay();
        dreamLogMessage(`🔄 ${heroName} 开始连续战斗`, 'info');
        showTip(`${heroName}开始连续战斗`, 'info');

        // 连续战斗循环
        const battleLoop = async () => {
            while (globalState.dream.battle.continuousBattles[heroId]) {
                const result = await startSingleBattle(heroId);

                // 如果返回stop，表示遇到2600080或2600050错误，停止战斗
                if (result === 'stop') {
                    stopContinuousBattle(heroId);
                    break;
                }

                // 等待0.1秒再进行下一次战斗
                if (globalState.dream.battle.continuousBattles[heroId]) {
                    await delay(100);
                }
            }
        };
        battleLoop();
    }

    function stopContinuousBattle(heroId) {
        const heroName = heroData[heroId] ? heroData[heroId].name : `ID:${heroId}`;
        if (globalState.dream.battle.continuousBattles[heroId]) {
            globalState.dream.battle.continuousBattles[heroId] = false;
            updateDreamQuickActionButtons();
            updateDreamTeamDisplay();
            dreamLogMessage(`⏹️ ${heroName} 连续战斗已停止`, 'info');
            showTip(`${heroName}连续战斗已停止`, 'info');
        }
    }

    function stopAllContinuousBattles() {
        let stoppedAny = false;
        for (const heroId in globalState.dream.battle.continuousBattles) {
            if (globalState.dream.battle.continuousBattles[heroId]) {
                stopContinuousBattle(heroId);
                stoppedAny = true;
            }
        }
        if (stoppedAny) {
            dreamLogMessage('⏹️ 所有连续战斗已停止', 'info');
            showTip('所有连续战斗已停止', 'info');
        } else {
            showTip('没有正在进行的连续战斗', 'warning');
        }
    }

    // 获取商品显示名称
    function getItemName(merchantId, index) {
        const merchant = merchantConfig[merchantId];
        if (merchant && merchant.items[index] !== undefined) {
            return merchant.items[index];
        }
        return `未知商品(${index})`;
    }

    // 获取商品颜色类
    function getItemColorClass(merchantId, index) {
        const itemName = getItemName(merchantId, index);

        // 黄金鱼竿特殊颜色
        if (itemName.includes('黄金鱼竿')) {
            return 'fishing';
        }

        // 金币商品颜色
        if (isGoldItem(parseInt(merchantId), index)) {
            return 'gold';
        }

        // 其他商品颜色
        return 'other';
    }

    // 检查是否为金币商品
    function isGoldItem(merchantId, index) {
        return goldItemsConfig[merchantId] && goldItemsConfig[merchantId].includes(index);
    }

    // 批量购买选中的商品
    async function batchBuySelected() {
        if (globalState.dream.buy.selectedItems.size === 0) {
            dreamLogMessage('请先选择要购买的商品', 'warning');
            return;
        }
        if (!isDungeonOpen()) {
            dreamLogMessage('当前不是梦境开放时间（周三/周四/周日/周一）', 'error');
            return;
        }
        if (globalState.dream.buy.levelId < 4000) {
            dreamLogMessage('关卡数小于4000，无法购买金币商品', 'error');
            return;
        }
        globalState.dream.buy.isRunning = true;
        updateDreamButtonStates();
        const items = Array.from(globalState.dream.buy.selectedItems);
        let successCount = 0;
        let failCount = 0;
        dreamLogMessage(`开始批量购买 ${items.length} 件商品...`, 'info');

        // 按商人ID和位置排序，从大到小购买
        items.sort((a, b) => {
            const [aMerchant, aIndex, aPos] = a.split('-').map(Number);
            const [bMerchant, bIndex, bPos] = b.split('-').map(Number);
            if (aMerchant !== bMerchant) return bMerchant - aMerchant;
            return bPos - aPos;
        });
        for (const itemKey of items) {
            const [merchantId, index, pos] = itemKey.split('-').map(Number);
            try {
                await executeGameCommand('dungeon_buymerchant', {
                    id: merchantId,
                    index: index,
                    pos: pos
                }, '购买商品');
                globalState.dream.buy.selectedItems.delete(itemKey);
                successCount++;
                dreamLogMessage(`成功购买: ${merchantConfig[merchantId].name} - ${getItemName(merchantId, index)}`, 'success');
            } catch (error) {
                failCount++;
                dreamLogMessage(`购买失败: ${merchantConfig[merchantId].name} - ${getItemName(merchantId, index)} - ${error.message}`, 'error');
            }

            // 延迟避免请求过快
            await delay(500);
        }

        // 重新获取商品列表更新界面
        await refreshDreamMerchantList();
        dreamLogMessage(`批量购买完成: 成功 ${successCount} 件, 失败 ${failCount} 件`,
            failCount === 0 ? 'success' : 'warning');
        globalState.dream.buy.isRunning = false;
        updateDreamButtonStates();
    }

    // 一键购买所有金币商品
    async function buyAllGoldItems() {
        if (!isDungeonOpen()) {
            dreamLogMessage('当前不是梦境开放时间（周三/周四/周日/周一）', 'error');
            return;
        }
        if (globalState.dream.buy.levelId < 4000) {
            dreamLogMessage('关卡数小于4000，无法购买金币商品', 'error');
            return;
        }
        globalState.dream.buy.isRunning = true;
        updateDreamButtonStates();
        let successCount = 0;
        let failCount = 0;
        dreamLogMessage('开始一键购买所有金币商品...', 'info');

        // 遍历所有商人的商品
        for (const merchantId in globalState.dream.buy.merchantData) {
            const items = globalState.dream.buy.merchantData[merchantId];
            const numId = parseInt(merchantId);

            // 从后往前购买（pos从大到小）
            for (let pos = items.length - 1; pos >= 0; pos--) {
                const index = items[pos];
                if (isGoldItem(numId, index)) {
                    try {
                        await executeGameCommand('dungeon_buymerchant', {
                            id: numId,
                            index: index,
                            pos: pos
                        }, '购买商品');
                        successCount++;
                        dreamLogMessage(`成功购买: ${merchantConfig[numId].name} - ${getItemName(numId, index)}`, 'success');
                    } catch (error) {
                        failCount++;
                        dreamLogMessage(`购买失败: ${merchantConfig[numId].name} - ${getItemName(numId, index)} - ${error.message}`, 'error');
                    }

                    // 延迟避免请求过快
                    await delay(500);
                }
            }
        }

        // 重新获取商品列表更新界面
        await refreshDreamMerchantList();
        dreamLogMessage(`一键购买完成: 成功 ${successCount} 件, 失败 ${failCount} 件`,
            failCount === 0 ? 'success' : 'warning');
        globalState.dream.buy.isRunning = false;
        updateDreamButtonStates();
    }

    // 获取商品列表
    async function refreshDreamMerchantList() {
        if (!isDungeonOpen()) {
            dreamLogMessage('当前不是梦境开放时间（周三/周四/周日/周一）', 'error');
            return;
        }
        try {
            dreamLogMessage('开始自动获取商品列表流程...', 'info');

            // 获取商品列表
            dreamLogMessage('获取商品列表...', 'info');
            const roleInfoResponse = await executeGameCommand('role_getroleinfo', {}, '获取角色信息');
            if (roleInfoResponse) {
                // 获取商品列表
                const merchantData = roleInfoResponse?._rawData?.role?.dungeon?.merchant;
                if (merchantData) {
                    globalState.dream.buy.merchantData = merchantData;
                }

                // 获取关卡ID
                const levelId = roleInfoResponse?._rawData?.role?.levelId;
                if (levelId !== undefined) {
                    globalState.dream.buy.levelId = levelId;
                }
                renderDreamMerchantItems();
                updateDreamSelectionDisplay();
                dreamLogMessage('✅ 商品列表获取完成', 'success');
            } else {
                throw new Error('获取角色信息失败');
            }
        } catch (error) {
            const errorMessage = error.message || '未知错误';
            dreamLogMessage(`❌ 获取商品列表失败: ${errorMessage}`, 'error');
        }
    }

    // 渲染商人商品
    function renderDreamMerchantItems() {
        const container = document.getElementById('dreamMerchantItemsContainer');
        if (!container) return;
        container.innerHTML = '';

        // 创建三列容器
        const columnsContainer = document.createElement('div');
        columnsContainer.className = 'dream-merchant-container';

        // 为每个商人创建一列
        for (const merchantId in merchantConfig) {
            const merchant = merchantConfig[merchantId];
            const items = globalState.dream.buy.merchantData[merchantId] || [];
            const column = document.createElement('div');
            column.className = 'dream-merchant-column';

            // 商人标题
            const title = document.createElement('div');
            title.className = 'dream-merchant-title';
            title.textContent = merchant.name;
            column.appendChild(title);

            // 商品列表
            if (items.length === 0) {
                const emptyMsg = document.createElement('div');
                emptyMsg.style.cssText = `
                    color: var(--text-secondary);
                    font-size: 8px;
                    text-align: center;
                    padding: 8px 0;
                `;
                emptyMsg.textContent = '无商品';
                column.appendChild(emptyMsg);
            } else {
                items.forEach((index, pos) => {
                    const itemKey = `${merchantId}-${index}-${pos}`;
                    const isSelected = globalState.dream.buy.selectedItems.has(itemKey);
                    const itemColorClass = getItemColorClass(parseInt(merchantId), index);
                    const itemDiv = document.createElement('div');
                    itemDiv.className = `dream-merchant-item ${isSelected ? 'selected' : ''}`;
                    const checkbox = document.createElement('input');
                    checkbox.type = 'checkbox';
                    checkbox.className = 'dream-merchant-checkbox';
                    checkbox.checked = isSelected;
                    checkbox.addEventListener('change', () => {
                        if (checkbox.checked) {
                            globalState.dream.buy.selectedItems.add(itemKey);
                        } else {
                            globalState.dream.buy.selectedItems.delete(itemKey);
                        }
                        updateDreamSelectionDisplay();
                        renderDreamMerchantItems();
                    });
                    const label = document.createElement('span');
                    label.className = `dream-merchant-label ${itemColorClass}`;
                    label.textContent = getItemName(parseInt(merchantId), index);
                    itemDiv.appendChild(checkbox);
                    itemDiv.appendChild(label);
                    column.appendChild(itemDiv);
                });
            }
            columnsContainer.appendChild(column);
        }
        container.appendChild(columnsContainer);
    }

    // 更新选择显示
    function updateDreamSelectionDisplay() {
        const batchBtn = document.getElementById('dreamBatchBuyBtn');
        if (batchBtn) {
            batchBtn.textContent = `批量购买(${globalState.dream.buy.selectedItems.size})`;
            batchBtn.disabled = globalState.dream.buy.selectedItems.size === 0 || globalState.dream.buy.isRunning;
        }
    }

    // 队伍显示
    function updateDreamTeamDisplay() {
        const teamContainer = document.getElementById('dreamTeamContainer');
        if (!teamContainer) return;
        teamContainer.innerHTML = '';
        if (globalState.dream.battle.currentTeamHeroes.length === 0) {
            teamContainer.innerHTML = '<div style="color: var(--text-secondary); text-align: center; padding: 10px;">暂无队伍信息</div>';
            return;
        }
        globalState.dream.battle.currentTeamHeroes.forEach(hero => {
            const heroElement = document.createElement('div');
            heroElement.className = `dream-hero-item ${hero.quality}`;
            const isBattling = globalState.dream.battle.continuousBattles[hero.id] || false;
            const buttonText = isBattling ? '停止战斗' : '连续战斗';
            const buttonClass = isBattling ? 'dream-battle-btn stop' : 'dream-battle-btn';
            heroElement.innerHTML = `
                <div class="dream-hero-info">
                    <div class="dream-hero-name ${`hero-${hero.quality}`}">${hero.name}</div>
                    <div class="dream-hero-details">${hero.type} | 位置: ${hero.position + 1}</div>
                </div>
                <button class="${buttonClass}" data-hero="${hero.id}">${buttonText}</button>
            `;
            teamContainer.appendChild(heroElement);
        });

        // 添加单个英雄连续战斗事件
        document.querySelectorAll('.dream-battle-btn').forEach(btn => {
            btn.addEventListener('click', function () {
                const heroId = this.getAttribute('data-hero');
                startContinuousBattle(heroId);
            });
        });
    }

    // 更新快速操作按钮 
    function updateDreamQuickActionButtons() {
        const quickActionContainer = document.getElementById('dreamQuickActionContainer');
        if (!quickActionContainer) return;
        quickActionContainer.innerHTML = '';
        if (globalState.dream.battle.currentTeamHeroes.length === 0) {
            quickActionContainer.innerHTML = '<div style="color: var(--text-secondary); text-align: center; padding: 10px; font-size: 11px;">获取默认阵容后显示</div>';
            return;
        }

        // 只显示前6个英雄作为快速操作
        const heroesToShow = globalState.dream.battle.currentTeamHeroes.slice(0, 6);
        heroesToShow.forEach(hero => {
            const isBattling = globalState.dream.battle.continuousBattles[hero.id] || false;
            const buttonText = isBattling ? `停止${hero.name}` : hero.name;
            const buttonClass = isBattling ? `dream-quick-btn stop ${hero.quality}` : `dream-quick-btn ${hero.quality}`;
            const button = document.createElement('button');
            button.className = buttonClass;
            button.setAttribute('data-hero', hero.id);
            button.textContent = buttonText;
            button.addEventListener('click', function () {
                const heroId = this.getAttribute('data-hero');
                startContinuousBattle(heroId);
            });
            quickActionContainer.appendChild(button);
        });
    }

    // 更新梦境按钮状态
    function updateDreamButtonStates() {
        const buttons = [
            'dreamGetTeam', 'dreamSelectTeam', 'dreamStopAllBattles',
            'dreamGetListBtn', 'dreamGoldBuyBtn', 'dreamBatchBuyBtn'
        ];
        buttons.forEach(btnId => {
            const button = document.getElementById(btnId);
            if (button) {
                const isBattleLoading = globalState.dream.battle.isLoading;
                const isBuyRunning = globalState.dream.buy.isRunning;

                if (btnId.startsWith('dream') && (btnId.includes('GetTeam') || btnId.includes('SelectTeam') || btnId.includes('StopAll'))) {
                    button.disabled = isBattleLoading;
                    button.style.opacity = isBattleLoading ? '0.6' : '1';
                } else if (btnId.startsWith('dream')) {
                    button.disabled = isBuyRunning;
                    button.style.opacity = isBuyRunning ? '0.6' : '1';
                }
            }
        });
    }

    // 切换梦境选项卡
    function switchDreamTab(tabName) {
        globalState.dream.currentTab = tabName;

        const battleTab = document.getElementById('dreamBattleTab');
        const buyTab = document.getElementById('dreamBuyTab');
        const battleContent = document.getElementById('dreamBattleContent');
        const buyContent = document.getElementById('dreamBuyContent');
        if (battleTab && buyTab && battleContent && buyContent) {
            if (tabName === 'battle') {
                battleTab.classList.add('active');
                buyTab.classList.remove('active');
                battleContent.style.display = 'block';
                buyContent.style.display = 'none';
            } else {
                battleTab.classList.remove('active');
                buyTab.classList.add('active');
                battleContent.style.display = 'none';
                buyContent.style.display = 'block';
            }
        }
    }

    // ==================== 兑换码功能 ====================

    // 兑换单个兑换码
    async function redeemCode(code) {
        if (!code || !code.trim()) {
            logMessage(`兑换码为空，跳过`, 'warning');
            return false;
        }

        try {
            logMessage(`尝试兑换兑换码: ${code}`, 'info');

            const response = await executeGameCommand('system_claimcdkreward', {
                key: code.trim(),
                platformType: 'h5web'
            });

            if (response?.code === 0) {
                logMessage(`兑换码 ${code} 兑换成功`, 'success');
                return true;
            } else {
                logMessage(`兑换码 ${code} 兑换失败`, 'error');
                return false;
            }
        } catch (error) {
            logMessage(`兑换码 ${code} 兑换出错: ${error.message}`, 'error');
            return false;
        }
    }

    // 执行所有兑换码兑换
    async function executeAllRedeemCodes() {
        if (globalState.redeem.isRunning) {
            showTip('兑换码兑换正在运行中', 'warning');
            return;
        }

        globalState.redeem.isRunning = true;
        updateRedeemButtonStates();

        logMessage('🎟️ ===== 开始自动兑换所有兑换码 =====', 'success');
        showTip('开始自动兑换所有兑换码', 'info');

        let successCount = 0;
        let totalCount = 0;

        // 获取选中的默认兑换码
        const selectedDefaultCodes = [];
        globalState.redeem.defaultCodes.forEach((code, index) => {
            const checkbox = document.getElementById(`default-code-${index}`);
            if (checkbox && checkbox.checked) {
                selectedDefaultCodes.push(code);
            }
        });

        // 兑换选中的默认兑换码
        for (const code of selectedDefaultCodes) {
            if (code && code.trim()) {
                totalCount++;
                const success = await redeemCode(code);
                if (success) successCount++;
                await delay(500); // 延迟防止请求过快
            }
        }

        // 兑换自定义兑换码
        for (const code of globalState.redeem.customCodes) {
            if (code && code.trim()) {
                totalCount++;
                const success = await redeemCode(code);
                if (success) successCount++;
                await delay(500); // 延迟防止请求过快
            }
        }

        logMessage(`兑换码兑换完成: ${successCount}/${totalCount} 成功`, 'success');
        showTip(`兑换码兑换完成: ${successCount}/${totalCount} 成功`, 'success');

        globalState.redeem.isRunning = false;
        updateRedeemButtonStates();

        return successCount;
    }

    // 添加默认兑换码
    function addDefaultCode() {
        const newCode = prompt('请输入新的兑换码:');
        if (newCode && newCode.trim()) {
            globalState.redeem.defaultCodes.push(newCode.trim());
            updateDefaultCodesUI();
            logMessage(`添加默认兑换码: ${newCode.trim()}`, 'success');
        }
    }

    // 删除单个默认兑换码
    function deleteDefaultCode(index) {
        const code = globalState.redeem.defaultCodes[index];
        if (confirm(`确定要删除兑换码 "${code}" 吗？`)) {
            globalState.redeem.defaultCodes.splice(index, 1);
            updateDefaultCodesUI();
            logMessage(`删除默认兑换码: ${code}`, 'success');
        }
    }

    // 批量删除选中的默认兑换码
    function batchDeleteDefaultCodes() {
        const selectedIndices = [];
        globalState.redeem.defaultCodes.forEach((code, index) => {
            const checkbox = document.getElementById(`default-code-${index}`);
            if (checkbox && checkbox.checked) {
                selectedIndices.push(index);
            }
        });

        if (selectedIndices.length === 0) {
            showTip('请先选择要删除的兑换码', 'warning');
            return;
        }

        if (confirm(`确定要删除选中的 ${selectedIndices.length} 个兑换码吗？`)) {
            // 从后往前删除，避免索引变化
            selectedIndices.sort((a, b) => b - a).forEach(index => {
                const code = globalState.redeem.defaultCodes[index];
                globalState.redeem.defaultCodes.splice(index, 1);
                logMessage(`批量删除兑换码: ${code}`, 'success');
            });

            updateDefaultCodesUI();
            showTip(`已删除 ${selectedIndices.length} 个兑换码`, 'success');
        }
    }

    // 删除自定义兑换码
    function deleteCustomCode(index) {
        const code = globalState.redeem.customCodes[index];
        if (code && code.trim()) {
            if (confirm(`确定要删除自定义兑换码 "${code}" 吗？`)) {
                globalState.redeem.customCodes[index] = "";
                const input = document.getElementById(`custom-code-${index}`);
                if (input) {
                    input.value = "";
                }
                logMessage(`删除自定义兑换码: ${code}`, 'success');
            }
        } else {
            showTip('自定义兑换码为空，无需删除', 'warning');
        }
    }

    // 更新默认兑换码UI
    function updateDefaultCodesUI() {
        const container = document.getElementById('defaultCodesContainer');
        if (!container) return;

        container.innerHTML = globalState.redeem.defaultCodes.map((code, index) => `
            <div class="redeem-code-item">
                <input type="checkbox" class="redeem-code-checkbox" id="default-code-${index}" checked>
                <label class="redeem-code-label" for="default-code-${index}">${code}</label>
                <button class="redeem-delete-btn" onclick="deleteDefaultCode(${index})">删除</button>
            </div>
        `).join('');
    }

    // 更新兑换码按钮状态
    function updateRedeemButtonStates() {
        const executeBtn = document.getElementById('executeRedeemBtn');
        if (executeBtn) {
            executeBtn.disabled = globalState.redeem.isRunning;
            executeBtn.style.opacity = globalState.redeem.isRunning ? '0.6' : '1';
        }
    }

    // ==================== 自动推关功能 ====================

    // 通过role_getroleinfo同步关卡
    async function syncCurrentLevelByRoleInfo() {
        try {
            logMessage('通过角色信息同步当前关卡数据...', 'info');

            const response = await executeGameCommand('role_getroleinfo', {});

            if (response) {
                // 将响应转换为字符串进行搜索
                const responseStr = JSON.stringify(response);

                // 搜索 "levelId": 格式
                const levelIdMatch = responseStr.match(/"levelId":\s*(\d+)/);

                if (levelIdMatch && levelIdMatch[1]) {
                    const levelId = parseInt(levelIdMatch[1]);
                    globalState.autoPush.currentLevel = levelId;
                    updateAutoPushUI();
                    logMessage(`角色信息同步成功: 当前关卡 ${globalState.autoPush.currentLevel}`, 'success');
                    return globalState.autoPush.currentLevel;
                } else {
                    logMessage('角色信息同步失败: 无法从响应中找到levelId字段', 'warning');
                    return null;
                }
            } else {
                logMessage('角色信息同步失败: 角色信息响应为空', 'error');
                return null;
            }
        } catch (error) {
            logMessage(`角色信息同步关卡数据出错: ${error.message}`, 'error');
            return null;
        }
    }

    // 首次进入页面时获取当前关卡
    async function initializeCurrentLevel() {
        if (globalState.autoPush.hasInitialized) {
            return;
        }

        logMessage('首次加载，正在获取当前关卡...', 'info');
        const result = await syncCurrentLevelByRoleInfo();
        if (!result) {
            logMessage('首次关卡同步失败', 'warning');
        }

        globalState.autoPush.hasInitialized = true;
        logMessage('首次关卡同步完成', 'success');
    }

    // 手动同步当前关卡
    async function manualSyncCurrentLevel() {
        logMessage('手动同步当前关卡...', 'info');
        // 使用role_getroleinfo获取当前关卡
        const result = await syncCurrentLevelByRoleInfo();
        if (!result) {
            logMessage('手动同步关卡失败', 'warning');
        }
    }

    // 手动推关功能
    async function manualPushLevel() {
        if (globalState.autoPush.isRunning) {
            showTip('自动推关正在运行中', 'warning');
            return;
        }

        const nextLevel = globalState.autoPush.currentLevel + 1;
        if (nextLevel > 1000) {
            showTip('已达到最大关卡', 'warning');
            return;
        }

        logMessage(`开始手动推关: 关卡 ${nextLevel}`, 'info');
        showTip(`手动推关中: 关卡 ${nextLevel}`, 'info');

        const success = await pushLevel(nextLevel);
        if (success) {
            logMessage(`手动推关成功: 关卡 ${nextLevel}`, 'success');
            showTip(`手动推关成功: 关卡 ${nextLevel}`, 'success');
        } else {
            logMessage(`手动推关失败: 关卡 ${nextLevel}`, 'error');
            showTip(`手动推关失败: 关卡 ${nextLevel}`, 'error');
        }
    }

    async function pushLevel(levelId) {
        try {
            // 先发送fight_startlevel开始关卡
            const startResponse = await executeGameCommand('fight_startlevel', { levelId: levelId });

            if (startResponse?.code === 0) {
                logMessage(`开始关卡: ${levelId}`, 'success');

                // 等待一段时间后发送结束关卡命令
                await delay(1000);

                const body = {
                    autoTapTimes: [
                        [0, 4, 25],
                        [0, 4, 32],
                        [0, 4, 35],
                        [0, 4, 40],
                        [0, 4, 26],
                        [0, 4, 64],
                        [0, 4, 17]
                    ],
                    battleTime: 1462,
                    levelId: levelId,
                    log: "",
                    outputCode: "d21aff9123be8627d0c801ad006b30ea",
                    tapTimes: [[], [], [], [], [], [], []]
                };

                logMessage(`结束关卡: ${levelId}`, 'info');

                const endResponse = await executeGameCommand('fight_endlevel', body);

                if (endResponse?.code === 0) {
                    // 关卡成功推进，更新当前关卡
                    globalState.autoPush.currentLevel = levelId;
                    updateAutoPushUI();
                    logMessage(`关卡 ${levelId} 推送成功`, 'success');
                    showTip(`关卡 ${levelId} 成功`, 'success');
                    return true;
                } else {
                    logMessage(`关卡 ${levelId} 推送失败`, 'error');
                    return false;
                }
            } else {
                logMessage(`开始关卡 ${levelId} 失败`, 'error');
                return false;
            }
        } catch (error) {
            logMessage(`推送关卡 ${levelId} 出错: ${error.message}`, 'error');
            return false;
        }
    }

    // 自动推关函数 - 连续推关直到目标关卡
    async function startAutoPush() {
        if (globalState.autoPush.autoPushRunning) {
            showTip('自动推关已在运行中', 'warning');
            return;
        }

        globalState.autoPush.autoPushRunning = true;
        globalState.autoPush.isRunning = true;
        updateAutoPushUI();

        showTip('开始自动推关', 'success');
        logMessage(`开始自动推关: 从 ${globalState.autoPush.currentLevel} 到 ${globalState.autoPush.targetLevel}`, 'info');

        // 开始连续推关流程
        await startContinuousPush();
    }

    // 连续推关函数
    async function startContinuousPush() {
        if (!globalState.autoPush.autoPushRunning) return;

        const nextLevel = globalState.autoPush.currentLevel + 1;

        if (nextLevel > globalState.autoPush.targetLevel) {
            logMessage(`已达到目标关卡 ${globalState.autoPush.targetLevel}，自动推关完成`, 'success');
            showTip('自动推关完成', 'success');
            stopAutoPush();

            // 自动兑换所有兑换码
            logMessage('开始自动兑换所有兑换码...', 'info');
            await executeAllRedeemCodes();
            return;
        }

        logMessage(`自动推关: 推送关卡 ${nextLevel}`, 'info');

        const success = await pushLevel(nextLevel);

        if (!success) {
            logMessage(`关卡 ${nextLevel} 推送失败，停止自动推关`, 'error');
            stopAutoPush();
            return;
        }

        // 继续推送下一关
        if (globalState.autoPush.autoPushRunning) {
            setTimeout(() => {
                startContinuousPush();
            }, globalState.autoPush.pushDelay);
        }
    }

    function stopAutoPush() {
        globalState.autoPush.autoPushRunning = false;
        globalState.autoPush.isRunning = false;
        updateAutoPushUI();

        showTip('停止自动推关', 'warning');
        logMessage('自动推关已停止', 'warning');
    }

    function updateAutoPushUI() {
        const currentLevelDisplay = document.getElementById('autoPushCurrentLevel');
        const targetLevelInput = document.getElementById('autoPushTargetLevel');
        const startBtn = document.getElementById('autoPushStartBtn');
        const stopBtn = document.getElementById('autoPushStopBtn');
        const manualPushBtn = document.getElementById('autoPushManualBtn');
        const syncBtn = document.getElementById('autoPushSyncBtn');

        if (currentLevelDisplay) {
            currentLevelDisplay.textContent = globalState.autoPush.currentLevel;
        }

        if (targetLevelInput) {
            targetLevelInput.value = globalState.autoPush.targetLevel;
        }

        if (startBtn) {
            startBtn.disabled = globalState.autoPush.autoPushRunning;
            startBtn.style.opacity = globalState.autoPush.autoPushRunning ? '0.5' : '1';
        }

        if (stopBtn) {
            stopBtn.disabled = !globalState.autoPush.autoPushRunning;
            stopBtn.style.opacity = globalState.autoPush.autoPushRunning ? '1' : '0.5';
        }

        if (manualPushBtn) {
            manualPushBtn.disabled = globalState.autoPush.autoPushRunning;
            manualPushBtn.style.opacity = globalState.autoPush.autoPushRunning ? '0.5' : '1';
        }

        if (syncBtn) {
            syncBtn.disabled = globalState.autoPush.autoPushRunning;
            syncBtn.style.opacity = globalState.autoPush.autoPushRunning ? '0.5' : '1';
        }
    }

    // ==================== 擂台功能模块 ====================

    // 擂台数据存储（本地持久化）
    function loadArenaData() {
        try {
            const savedArenaData = localStorage.getItem('anniversaryArenaData');
            if (savedArenaData) {
                const data = JSON.parse(savedArenaData);
                if (data.towerType !== undefined) globalState.activity.arena.towerType = data.towerType;
                if (data.loopCount !== undefined) globalState.activity.arena.loopCount = data.loopCount;
            }
        } catch (e) {
            console.log('加载擂台设置失败:', e);
        }
    }

    function saveArenaData() {
        try {
            localStorage.setItem('anniversaryArenaData', JSON.stringify({
                towerType: globalState.activity.arena.towerType,
                loopCount: globalState.activity.arena.loopCount
            }));
        } catch (e) {
            console.log('保存擂台设置失败:', e);
        }
    }

    // 擂台核心战斗逻辑
    async function executeArenaChallenge() {
        if (globalState.activity.arena.isRunning) {
            showTip('擂台挑战已在执行中', 'warning');
            return;
        }

        globalState.activity.arena.isRunning = true;
        globalState.activity.arena.isStopped = false;

        try {
            logMessage(`开始擂台挑战: 类型 ${globalState.activity.arena.towerType}, 循环 ${globalState.activity.arena.loopCount} 次`, 'info');

            if (!checkWsConnection()) {
                logMessage('擂台挑战失败: WebSocket连接不可用', 'error');
                return 0;
            }

            let totalSuccessCount = 0;
            let totalAttempts = 0;

            for (let i = 0; i < globalState.activity.arena.loopCount; i++) {
                if (globalState.activity.arena.isStopped) {
                    logMessage('擂台挑战已停止', 'warning');
                    break;
                }

                showTip(`擂台挑战中: 第 ${i + 1}/${globalState.activity.arena.loopCount} 次`, 'info');

                if (!checkWsConnection()) {
                    logMessage('擂台挑战中断: WebSocket连接已断开', 'error');
                    break;
                }

                // 启动擂台
                const startResponse = await executeGameCommand('towers_start', { towerType: globalState.activity.arena.towerType });
                if (startResponse?.code === 0) {
                    logMessage(`第 ${i + 1} 次擂台挑战开始成功`, 'success');

                    // 战斗规则：第1次循环8场，后续循环每场1场
                    const fightCount = i === 0 ? 8 : 1;
                    let fightSuccessCount = 0;

                    logMessage(`第 ${i + 1} 次循环执行 ${fightCount} 次战斗`, 'info');

                    for (let j = 0; j < fightCount; j++) {
                        if (globalState.activity.arena.isStopped) {
                            logMessage('擂台挑战已停止', 'warning');
                            break;
                        }

                        if (!checkWsConnection()) {
                            logMessage('擂台挑战中断: WebSocket连接断开', 'error');
                            break;
                        }

                        // 执行战斗
                        const fightResponse = await executeGameCommand('towers_fight', { towerType: globalState.activity.arena.towerType });
                        if (fightResponse?.code === 0) {
                            fightSuccessCount++;
                            totalSuccessCount++;
                            logMessage(`第 ${i + 1} 次循环第 ${j + 1}/${fightCount} 场战斗成功`, 'success');
                        } else {
                            logMessage(`第 ${i + 1} 次循环第 ${j + 1}/${fightCount} 场战斗失败`, 'error');
                        }

                        totalAttempts++;
                        if (j < fightCount - 1) await delay(200);
                    }

                    logMessage(`第 ${i + 1} 次循环完成: ${fightSuccessCount}/${fightCount} 场成功`, fightSuccessCount === fightCount ? 'success' : 'warning');
                } else {
                    logMessage(`第 ${i + 1} 次擂台启动失败`, 'error');
                }

                if (i < globalState.activity.arena.loopCount - 1) await delay(300);
            }

            // 结果统计
            const successRate = totalAttempts > 0 ? (totalSuccessCount / totalAttempts * 100).toFixed(1) : 0;
            showTip(`擂台挑战完成: ${totalSuccessCount}/${totalAttempts} 场成功 (${successRate}%)`, 'success');
            logMessage(`挑战结束: 成功 ${totalSuccessCount}/${totalAttempts} 场 (成功率 ${successRate}%)`, 'success');
            return totalSuccessCount;
        } catch (error) {
            logMessage(`擂台挑战异常: ${error.message}`, 'error');
            return 0;
        } finally {
            globalState.activity.arena.isRunning = false;
            updateArenaButtonStates();
        }
    }

    function stopArenaChallenge() {
        globalState.activity.arena.isStopped = true;
        logMessage('已触发停止指令，等待当前战斗结束', 'warning');
        showTip('将停止后续挑战', 'warning');
    }

    function updateArenaButtonStates() {
        const startBtn = document.getElementById('arenaStartBtn');
        const stopBtn = document.getElementById('arenaStopBtn');

        if (startBtn) {
            startBtn.disabled = globalState.activity.arena.isRunning;
            startBtn.style.opacity = globalState.activity.arena.isRunning ? '0.5' : '1';
        }

        if (stopBtn) {
            stopBtn.disabled = !globalState.activity.arena.isRunning;
            stopBtn.style.opacity = globalState.activity.arena.isRunning ? '1' : '0.5';
        }
    }

    // 创建擂台模块UI
    function createArenaModule() {
        const container = document.createElement('div');
        container.className = 'control-group-glass';

        // 模块标题
        const title = document.createElement('div');
        title.className = 'group-title-glass';
        title.innerHTML = '⚔️ 擂台挑战';
        container.appendChild(title);

        // 擂台设置区域
        const arenaSetting = document.createElement('div');
        arenaSetting.style.cssText = `
            background: rgba(0, 0, 0, 0.03);
            padding: 10px;
            border-radius: 6px;
            margin-bottom: 10px;
            border: 1px solid var(--item-border);
        `;

        // 攻打对象选择（全部显示，单选互斥）
        const towerGroup = document.createElement('div');
        towerGroup.style.cssText = 'margin-bottom: 10px;';

        const towerLabel = document.createElement('div');
        towerLabel.style.cssText = `
            font-size: 11px;
            color: var(--text-secondary);
            margin-bottom: 6px;
            font-weight: 500;
        `;
        towerLabel.textContent = '选择攻打对象：';
        towerGroup.appendChild(towerLabel);

        // 攻打对象单选框容器（2行3列排版，美观紧凑）
        const radioContainer = document.createElement('div');
        radioContainer.style.cssText = 'display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;';

        // 循环生成所有攻打对象单选框
        towerList.forEach(tower => {
            const radioItem = document.createElement('div');
            radioItem.style.cssText = 'display: flex; align-items: center; gap: 4px;';

            const radio = document.createElement('input');
            radio.type = 'radio';
            radio.name = 'towerRadioGroup'; // 同name实现互斥单选
            radio.value = tower.value;
            radio.checked = tower.value === globalState.activity.arena.towerType;
            radio.style.cssText = `
                width: 12px;
                height: 12px;
                accent-color: var(--highlight);
                cursor: pointer;
                margin: 0;
            `;

            const label = document.createElement('span');
            label.textContent = tower.name;
            label.style.cssText = `
                font-size: 10px;
                color: var(--text-primary);
                cursor: pointer;
            `;

            radio.addEventListener('change', (e) => {
                globalState.activity.arena.towerType = parseInt(e.target.value);
                saveArenaData();
            });

            radioItem.appendChild(radio);
            radioItem.appendChild(label);
            radioContainer.appendChild(radioItem);
        });
        towerGroup.appendChild(radioContainer);
        arenaSetting.appendChild(towerGroup);

        // 循环次数设置
        const loopGroup = document.createElement('div');
        loopGroup.style.cssText = 'display: flex; align-items: center; gap: 8px; margin-bottom: 8px;';
        const loopLabel = document.createElement('div');
        loopLabel.textContent = '循环次数:';
        loopLabel.style.cssText = `
            font-size: 11px;
            color: var(--text-secondary);
            width: 60px;
            flex-shrink: 0;
        `;
        const loopInput = document.createElement('input');
        loopInput.type = 'number';
        loopInput.className = 'text-input-glass';
        loopInput.value = globalState.activity.arena.loopCount;
        loopInput.min = '1';
        loopInput.max = '100';
        loopInput.style.cssText = 'flex: 1;';
        loopInput.addEventListener('change', (e) => {
            globalState.activity.arena.loopCount = parseInt(e.target.value) || 1;
            saveArenaData();
        });
        loopGroup.appendChild(loopLabel);
        loopGroup.appendChild(loopInput);
        arenaSetting.appendChild(loopGroup);

        // 战斗规则说明
        const ruleTip = document.createElement('div');
        ruleTip.style.cssText = `
            font-size: 10px;
            color: var(--text-secondary);
            padding: 6px;
            background: rgba(0, 0, 0, 0.05);
            border-radius: 4px;
            line-height: 1.4;
            border-left: 3px solid var(--highlight);
        `;
        ruleTip.textContent = '战斗规则：第1次循环执行8场战斗，后续每次循环执行1场战斗，自动保持WebSocket连接检测';
        arenaSetting.appendChild(ruleTip);
        container.appendChild(arenaSetting);

        // 功能按钮（执行+停止）
        const btnGroup = document.createElement('div');
        btnGroup.style.cssText = 'display: flex; gap: 8px; margin-bottom: 8px;';

        // 执行挑战按钮
        const startBtn = document.createElement('button');
        startBtn.id = 'arenaStartBtn';
        startBtn.className = 'btn-glass btn-primary-glass';
        startBtn.textContent = '启动擂台挑战';
        startBtn.style.cssText = 'flex: 1;';
        startBtn.addEventListener('click', async () => {
            if (globalState.activity.arena.isRunning) {
                showTip('挑战已在执行中', 'warning');
                return;
            }
            if (globalState.activity.arena.loopCount < 1) {
                showTip('请设置有效循环次数', 'error');
                return;
            }
            await executeArenaChallenge();
        });

        // 停止挑战按钮
        const stopBtn = document.createElement('button');
        stopBtn.id = 'arenaStopBtn';
        stopBtn.className = 'btn-glass btn-danger-glass';
        stopBtn.textContent = '停止擂台挑战';
        stopBtn.style.cssText = 'flex: 1;';
        stopBtn.addEventListener('click', () => {
            stopArenaChallenge();
        });

        btnGroup.appendChild(startBtn);
        btnGroup.appendChild(stopBtn);
        container.appendChild(btnGroup);

        // 加载本地保存的配置
        loadArenaData();

        return container;
    }

