    // 检查任务状态
    async function checkTaskState(taskName) {
        while (globalState.activity.consume.isPaused && !globalState.activity.consume.isStopped) {
            await new Promise(resolve => setTimeout(resolve, 500));
        }
        if (globalState.activity.consume.isStopped) {
            throw new Error(`${taskName}已停止`);
        }
    }

    // 处理暂停
    function handlePause() {
        globalState.activity.consume.isPaused = !globalState.activity.consume.isPaused;
        const btn = activityUIElements.resourcePauseBtn;
        if (btn) {
            btn.textContent = globalState.activity.consume.isPaused ? '继续' : '暂停';
            btn.style.background = globalState.activity.consume.isPaused ? 'rgba(56, 161, 105, 0.1)' : 'rgba(0,0,0,0.05)';
            btn.style.borderColor = globalState.activity.consume.isPaused ? 'rgba(56, 161, 105, 0.2)' : 'rgba(0,0,0,0.1)';
            btn.style.color = globalState.activity.consume.isPaused ? 'var(--success)' : 'var(--text-secondary)';
        }
        showTip('资源任务已暂停', 'info');
    }

    // 处理停止
    function handleStop() {
        globalState.activity.consume.isStopped = true;
        globalState.activity.consume.isPaused = false;
        globalState.activity.consume.isRunning = false;
        if (activityUIElements.resourcePauseBtn) {
            activityUIElements.resourcePauseBtn.textContent = '暂停';
            activityUIElements.resourcePauseBtn.style.background = 'rgba(0,0,0,0.05)';
            activityUIElements.resourcePauseBtn.style.borderColor = 'rgba(0,0,0,0.1)';
            activityUIElements.resourcePauseBtn.style.color = 'var(--text-secondary)';
            activityUIElements.resourcePauseBtn.disabled = true;
        }
        if (activityUIElements.resourceStopBtn) {
            activityUIElements.resourceStopBtn.disabled = true;
        }
        if (activityUIElements.resourceExecBtn) {
            activityUIElements.resourceExecBtn.disabled = false;
            activityUIElements.resourceExecBtn.textContent = '同时开始所有资源任务';
            activityUIElements.resourceExecBtn.style.opacity = '1';
        }
        showTip('资源任务已停止', 'info');
    }

    // 通用任务执行函数 - 支持个位数执行
    async function executeGenericTask(moduleType, moduleName, typeId, quantity) {
        const taskCfg = taskCommands[moduleType][typeId];
        if (!taskCfg || quantity < 1) {
            throw new Error(`无效${moduleName}配置：请确保类型正确且消耗≥1`);
        }
        if (!checkWsConnection()) throw new Error('无WebSocket连接');

        // 支持任意数量，包括个位数
        let execCount, singleQty;
        if (quantity <= 10) {
            // 10个以下直接执行
            execCount = 1;
            singleQty = quantity;
        } else {
            // 10个以上分批执行，每批10个
            execCount = Math.floor(quantity / 10);
            singleQty = 10;
            const remainder = quantity % 10;

            // 如果有余数，增加一次执行
            if (remainder > 0) {
                execCount++;
            }
        }

        const totalQty = quantity;
        logMessage(`${taskCfg.name}：启动（${execCount}次·${totalQty}个）`, 'info');
        let success = 0;
        let processedQty = 0;
        try {
            for (let i = 1; i <= execCount; i++) {
                await checkTaskState(taskCfg.name);

                // 计算本次执行的数量
                let currentQty = singleQty;
                if (i === execCount && quantity % 10 > 0) {
                    currentQty = quantity % 10;
                }
                const progress = `${taskCfg.name} #${i}/${execCount} (${currentQty}个)`;
                try {
                    const params = taskCfg.params(currentQty);

                    // 使用executeGameCommand函数执行命令，包含完整的错误处理和WebSocket连接检查
                    const res = await executeGameCommand(taskCfg.cmd, params, `${taskCfg.name} (${currentQty}个)`);

                    const isSuccess = (res?.code === 0 || res?.ack === 0 || (!res?.code && !res?.ack)) && !res?.resp?.error;
                    if (isSuccess) {
                        logMessage(`${taskCfg.name}成功 (${currentQty}个)`, 'success');
                        success++;
                        processedQty += currentQty;
                    } else {
                        throw new Error(`码：${res?.code || res?.ack || '未知'}`);
                    }
                } catch (err) {
                    logMessage(`失败：${err.message}`, 'error');
                    continue;
                }
                if (i < execCount) await new Promise(resolve => setTimeout(resolve, consumeConfig.globalDelay));
            }
            const summary = `${taskCfg.name}：${success}/${execCount}次（${processedQty}/${totalQty}个）`;
            logMessage(summary, 'success');
            showTip(summary, 'success');
            return summary;
        } catch (err) {
            logMessage(`${taskCfg.name}中断：${err.message}`, 'error');
            throw err;
        }
    }

    // 执行特定模块类型的任务 - 支持个位数执行
    async function executeModuleTasks(moduleType, moduleName) {
        const tasksToExecute = [];

        // 根据模块类型收集任务 - 支持≥1的数量
        if (moduleType === 'chest') {
            Object.keys(consumeConfig.chestTypes).forEach(typeId => {
                const chestType = consumeConfig.chestTypes[typeId];
                if (chestType.quantity >= 1) {
                    tasksToExecute.push({
                        type: 'chest',
                        typeId: typeId,
                        quantity: chestType.quantity,
                        name: chestType.name
                    });
                }
            });
        } else if (moduleType === 'fishing') {
            Object.keys(consumeConfig.fishingTypes).forEach(typeId => {
                const fishingType = consumeConfig.fishingTypes[typeId];
                if (fishingType.quantity >= 1) {
                    tasksToExecute.push({
                        type: 'fishing',
                        typeId: typeId,
                        quantity: fishingType.quantity,
                        name: fishingType.name
                    });
                }
            });
        } else if (moduleType === 'recruit') {
            Object.keys(consumeConfig.recruitTypes).forEach(typeId => {
                const recruitType = consumeConfig.recruitTypes[typeId];
                if (recruitType.quantity >= 1) {
                    tasksToExecute.push({
                        type: 'recruit',
                        typeId: typeId,
                        quantity: recruitType.quantity,
                        name: recruitType.name
                    });
                }
            });
        } else if (moduleType === 'torch') {
            Object.keys(consumeConfig.torchTypes).forEach(typeId => {
                const torchType = consumeConfig.torchTypes[typeId];
                if (torchType.quantity >= 1) {
                    tasksToExecute.push({
                        type: 'torch',
                        typeId: typeId,
                        quantity: torchType.quantity,
                        name: torchType.name
                    });
                }
            });
        }
        if (tasksToExecute.length === 0) {
            showTip(`没有可执行的${moduleName}任务（消耗需≥1）`, 'error');
            return;
        }

        // 更新任务控制状态
        globalState.activity.consume.isPaused = false;
        globalState.activity.consume.isStopped = false;
        globalState.activity.consume.currentTasks = [];
        globalState.activity.consume.isRunning = true;

        // 禁用对应模块的执行按钮
        const execBtn = activityUIElements[`${moduleType}ExecBtn`];
        if (execBtn) {
            execBtn.disabled = true;
            execBtn.textContent = `${moduleName}执行中...`;
        }

        // 启用控制按钮
        if (activityUIElements.resourcePauseBtn) activityUIElements.resourcePauseBtn.disabled = false;
        if (activityUIElements.resourceStopBtn) activityUIElements.resourceStopBtn.disabled = false;
        try {
            showTip(`${moduleName}任务开始执行`, 'success');
            logMessage(`${moduleName}任务启动：${tasksToExecute.length}个任务`, 'info');
            const parallelTasks = [];
            tasksToExecute.forEach(task => {
                const taskPromise = executeGenericTask(task.type, task.name, task.typeId, task.quantity);
                parallelTasks.push(taskPromise);
                globalState.activity.consume.currentTasks.push(taskPromise);
            });
            await Promise.all(parallelTasks);
            globalState.activity.consume.currentTasks = globalState.activity.consume.currentTasks.filter(t => !parallelTasks.includes(t));
            if (globalState.activity.consume.currentTasks.length === 0) {
                globalState.activity.consume.isRunning = false;
                if (activityUIElements.resourcePauseBtn) activityUIElements.resourcePauseBtn.disabled = true;
                if (activityUIElements.resourceStopBtn) activityUIElements.resourceStopBtn.disabled = true;
            }
            showTip(`${moduleName}任务完成`, 'success');
            logMessage(`${moduleName}任务完成`, 'success');
        } catch (err) {
            showTip(`${moduleName}任务执行失败，查看日志`, 'error');
            logMessage(`${moduleName}任务异常：${err.message}`, 'error');
        } finally {
            if (!globalState.activity.consume.isStopped) {
                if (execBtn) {
                    execBtn.disabled = false;
                    execBtn.textContent = `批量${moduleName}`;
                }
                globalState.activity.consume.isRunning = false;
                if (activityUIElements.resourcePauseBtn) activityUIElements.resourcePauseBtn.disabled = true;
                if (activityUIElements.resourceStopBtn) activityUIElements.resourceStopBtn.disabled = true;
            }
        }
    }

    // 一键升星任务执行函数（数据驱动版：唤醒 → 精准升星 → 图鉴升星）
    async function executeUpgradeStarTask() {
        const delay = consumeConfig.upgradeStarDelay;

        // 英雄ID集合
        const HERO_IDS = [
            ...Array.from({ length: 21 }, (_, i) => 101 + i), // 101-121 红将
            ...Array.from({ length: 28 }, (_, i) => 201 + i), // 201-228 橙将
            ...Array.from({ length: 14 }, (_, i) => 301 + i)  // 301-314 紫将
        ];

        // 唤醒成本分类：紫将1、红将8、橙将4
        const PURPLE_IDS = new Set([215, 227, 228, 301, 302, 303, 304, 305, 306, 307, 308, 309, 310, 311, 312]);
        const RED_IDS = new Set(Array.from({ length: 21 }, (_, i) => 101 + i));

        // 升星碎片阶梯表
        const STAR_FRAGMENTS = [
            { min: 1, max: 5, cost: 8 },
            { min: 6, max: 10, cost: 40 },
            { min: 11, max: 15, cost: 80 },
            { min: 16, max: 20, cost: 200 },
            { min: 21, max: 30, cost: 400 }
        ];

        const getWakeupCost = (id) => PURPLE_IDS.has(id) ? 1 : (RED_IDS.has(id) ? 8 : 4);

        // 升 (currentStar → currentStar+1) 所需碎片；currentStar=-1 表示未唤醒
        const getStarCost = (id, currentStar) => {
            if (currentStar === -1) return getWakeupCost(id);
            const target = currentStar + 1;
            for (const r of STAR_FRAGMENTS) {
                if (target >= r.min && target <= r.max) return r.cost;
            }
            return 0;
        };

        // 基于碎片预算计算可升星次数（不含唤醒）
        const calcUpgradeTimes = (id, currentStar, fragments) => {
            let times = 0, star = currentStar, remaining = fragments;
            while (star < 30) {
                const cost = getStarCost(id, star);
                if (cost === 0 || remaining < cost) break;
                remaining -= cost;
                star++;
                times++;
            }
            return times;
        };

        const readFragments = (items, id) => {
            if (!items) return 0;
            const node = items[id] ?? items[String(id)];
            if (node == null) return 0;
            if (typeof node === 'number') return node;
            return Number(node.quantity ?? node.num ?? node.count ?? 0);
        };

        if (!checkWsConnection()) {
            showTip('❌ 当前页面无可用WebSocket连接，无法执行任务', 'error');
            logMessage('无WebSocket连接', 'error');
            return;
        }

        showConfirmModal(
            '一键升星',
            '📌 即将根据碎片预算执行：唤醒 → 升星 → 图鉴升星，是否继续？',
            async () => {
                globalState.activity.consume.isPaused = false;
                globalState.activity.consume.isStopped = false;
                globalState.activity.consume.isRunning = true;
                globalState.activity.consume.currentTasks = [];
                showTip('✅ 开始升星', 'success');
                logMessage(`📌 开始升星任务（延迟 ${delay}ms，按碎片预算精准执行）`, 'info');

                const starTask = (async () => {
                    let wakeupCount = 0, starUpCount = 0, bookCount = 0;
                    try {
                        // ===== 拉取角色数据 =====
                        await checkTaskState('升星(拉取数据)');
                        const roleResp = await executeGameCommandResult('role_getroleinfo', {}, 8000);
                        if (roleResp?.code !== 0) {
                            throw new Error(`获取角色信息失败 code=${roleResp?.code}`);
                        }
                        const role0 = roleResp?._rawData?.role || roleResp?._rawData || {};
                        let heroes = role0.heroes || {};
                        let items = role0.items || {};

                        // ===== 阶段1/3：唤醒未获得武将 =====
                        logMessage('🟢 阶段1/3：唤醒未获得武将', 'info');
                        for (const heroId of HERO_IDS) {
                            await checkTaskState(`唤醒(英雄${heroId})`);
                            const hero = heroes[heroId] ?? heroes[String(heroId)];
                            if (hero) continue;
                            const frag = readFragments(items, heroId);
                            const cost = getWakeupCost(heroId);
                            if (frag < cost) continue;
                            try {
                                const resp = await executeGameCommandResult('hero_synthetic', { itemId: Number(heroId) }, 8000);
                                if (resp?.code === 0) {
                                    wakeupCount++;
                                    logMessage(`✨ 英雄${heroId} 唤醒成功`, 'success');
                                } else {
                                    logMessage(`英雄${heroId} 唤醒失败 code=${resp?.code}`, 'warning');
                                }
                            } catch (err) {
                                logMessage(`英雄${heroId} 唤醒异常: ${err.message}`, 'warning');
                            }
                            await new Promise(r => setTimeout(r, delay));
                        }

                        // 唤醒后刷新一次，使升星预算准确
                        if (wakeupCount > 0) {
                            try {
                                const r2 = await executeGameCommandResult('role_getroleinfo', {}, 8000);
                                if (r2?.code === 0) {
                                    const role2 = r2?._rawData?.role || r2?._rawData || {};
                                    heroes = role2.heroes || heroes;
                                    items = role2.items || items;
                                }
                            } catch (_) {}
                        }

                        // ===== 阶段2/3：按碎片预算精准升星 =====
                        logMessage('🟢 阶段2/3：按碎片预算升星', 'info');
                        for (const heroId of HERO_IDS) {
                            await checkTaskState(`升星(英雄${heroId})`);
                            const hero = heroes[heroId] ?? heroes[String(heroId)];
                            if (!hero) continue;
                            let currentStar = Number(hero.star || 0);
                            const fragments = readFragments(items, heroId);
                            const times = calcUpgradeTimes(heroId, currentStar, fragments);
                            if (times <= 0) continue;

                            for (let i = 1; i <= times; i++) {
                                await checkTaskState(`升星(英雄${heroId})`);
                                try {
                                    const resp = await executeGameCommandResult('hero_heroupgradestar', { heroId: Number(heroId) }, 8000);
                                    if (resp?.code === 0) {
                                        currentStar++;
                                        starUpCount++;
                                        logMessage(`英雄${heroId} #${i}/${times} → ${currentStar}星`, 'success');
                                    } else {
                                        logMessage(`英雄${heroId} #${i} 失败 code=${resp?.code}`, 'warning');
                                        break;
                                    }
                                } catch (err) {
                                    logMessage(`英雄${heroId} #${i} 异常: ${err.message}`, 'error');
                                    break;
                                }
                                if (i < times) await new Promise(r => setTimeout(r, delay));
                            }
                        }
                        logMessage(`✅ 升星阶段完成，共升 ${starUpCount} 次`, 'success');

                        // ===== 阶段3/3：武将图鉴升级（用 book_upgrade，按 hero.bookStar 与 currentStar 差值精确循环）=====
                        // 升级条件：hero.bookStar < hero.star，每升一次 bookStar+1
                        logMessage('🟢 阶段3/3：武将图鉴升级', 'info');
                        // 拉一次最新角色信息以获取最新 hero.star（前面升星阶段已变更）
                        try {
                            const r3 = await executeGameCommandResult('role_getroleinfo', {}, 8000);
                            if (r3?.code === 0) {
                                const role3 = r3?._rawData?.role || r3?._rawData || {};
                                heroes = role3.heroes || heroes;
                            }
                        } catch (_) {}
                        for (const heroId of HERO_IDS) {
                            await checkTaskState(`图鉴升级(英雄${heroId})`);
                            const hero = heroes[heroId] ?? heroes[String(heroId)];
                            if (!hero) continue;
                            const currentStar = Number(hero.star || 0);
                            let bookStar = Number(hero.bookStar || 0);
                            if (bookStar >= currentStar) continue;
                            const need = currentStar - bookStar;
                            for (let i = 1; i <= need; i++) {
                                await checkTaskState(`图鉴升级(英雄${heroId})`);
                                try {
                                    const resp = await executeGameCommandResult('book_upgrade', { heroId: Number(heroId) }, 8000);
                                    if (resp?.code === 0) {
                                        bookStar++;
                                        bookCount++;
                                        logMessage(`英雄${heroId}图鉴 #${i}/${need} → bookStar=${bookStar}`, 'success');
                                    } else {
                                        logMessage(`英雄${heroId}图鉴 #${i} 失败 code=${resp?.code}`, 'warning');
                                        break;
                                    }
                                } catch (err) {
                                    logMessage(`英雄${heroId}图鉴 #${i} 异常: ${err.message}`, 'warning');
                                    break;
                                }
                                await new Promise(r => setTimeout(r, delay));
                            }
                        }
                        logMessage(`✅ 武将图鉴升级完成，共 ${bookCount} 次`, 'success');

                        showTip(`完成：唤醒${wakeupCount} + 升星${starUpCount} + 武将图鉴${bookCount}`, 'success');
                        logMessage(`🎉 英雄升星全部完成：唤醒${wakeupCount} / 升星${starUpCount} / 武将图鉴${bookCount}`, 'success');
                    } catch (err) {
                        logMessage(`升星任务执行失败: ${err.message}`, 'error');
                        showTip('升星任务执行失败', 'error');
                    } finally {
                        globalState.activity.consume.isRunning = false;
                        if (activityUIElements.resourceStartBtn) {
                            activityUIElements.resourceStartBtn.disabled = false;
                            activityUIElements.resourceStartBtn.textContent = '开始';
                        }
                        if (activityUIElements.resourcePauseBtn) activityUIElements.resourcePauseBtn.disabled = true;
                        if (activityUIElements.resourceStopBtn) activityUIElements.resourceStopBtn.disabled = true;
                    }
                })();

                globalState.activity.consume.currentTasks.push(starTask);
            }
        );

        return;
    }

    // ==================== 藏品升星任务 ====================
    // 与"一键升星"完全分离：调用 collection_* 系列接口（珍宝阁/藏品图鉴）
    // 流程：collection_getinfo → 遍历 collectMap/heroSeries/themeSeries/suitSeries 调 collection_activate
    //       → 按 seriesId 去重调 collection_claimseries → collection_claimtotal → 30 次 collection_activate(1001) 升级
    async function executeCollectionUpgradeTask() {
        const delay = consumeConfig.upgradeStarDelay || 1200;

        if (!checkWsConnection()) {
            showTip('❌ 当前页面无可用WebSocket连接，无法执行任务', 'error');
            logMessage('无WebSocket连接', 'error');
            return;
        }

        showConfirmModal(
            '藏品升星',
            '📌 即将执行藏品图鉴：激活全部 → 领取系列奖励 → 总览奖励 → 30 次升级，是否继续？',
            async () => {
                globalState.activity.consume.isPaused = false;
                globalState.activity.consume.isStopped = false;
                globalState.activity.consume.isRunning = true;
                globalState.activity.consume.currentTasks = [];
                showTip('✅ 开始藏品升星', 'success');
                logMessage(`📌 开始藏品升星任务（延迟 ${delay}ms）`, 'info');

                const task = (async () => {
                    let activateOk = 0, activateFail = 0, seriesOk = 0, totalOk = 0, upgradeOk = 0;
                    try {
                        // ===== 1. 拉取藏品图鉴数据 =====
                        await checkTaskState('藏品(拉取数据)');
                        const infoResp = await executeGameCommandResult('collection_getinfo', {}, 10000);
                        if (infoResp?.code !== 0) {
                            throw new Error(`collection_getinfo 失败 code=${infoResp?.code}`);
                        }
                        const collection = infoResp?._rawData?.collection
                            || infoResp?.body?.collection
                            || infoResp?.collection
                            || {};

                        // ===== 2. 解析全部图鉴项目（去重）=====
                        const requests = [];
                        const seen = new Set();
                        const addReq = (seriesId, id, poolType) => {
                            const key = `${seriesId}_${id}_${poolType}`;
                            if (id !== 0 && !seen.has(key)) {
                                requests.push({ seriesId, id, poolType });
                                seen.add(key);
                            }
                        };

                        // 2.1 collectMap (收藏系列, poolType=1)
                        if (collection.collectMap) {
                            for (const sid in collection.collectMap) {
                                const series = collection.collectMap[sid];
                                if (series?.collectMap) {
                                    for (const itemId in series.collectMap) {
                                        addReq(parseInt(sid), parseInt(itemId), 1);
                                    }
                                }
                            }
                        }
                        // 2.2 heroSeries (武将系列, poolType=2)
                        if (collection.heroSeries) {
                            for (const sid in collection.heroSeries) {
                                const series = collection.heroSeries[sid];
                                if (series?.collectMap) {
                                    for (const itemId in series.collectMap) {
                                        addReq(parseInt(sid), parseInt(itemId), 2);
                                    }
                                }
                            }
                        }
                        // 2.3 themeSeries (主题系列, poolType=3)
                        if (collection.themeSeries) {
                            for (const sid in collection.themeSeries) {
                                const series = collection.themeSeries[sid];
                                if (series?.collectMap) {
                                    for (const itemId in series.collectMap) {
                                        addReq(parseInt(sid), parseInt(itemId), 3);
                                    }
                                }
                            }
                        }
                        // 2.4 suitSeries (套装系列, poolType=4) —— collectMap key 为复合 key，实际 id 在 item.id
                        if (collection.suitSeries) {
                            for (const sid in collection.suitSeries) {
                                const series = collection.suitSeries[sid];
                                if (series?.collectMap) {
                                    for (const compKey in series.collectMap) {
                                        const item = series.collectMap[compKey];
                                        if (item?.id) {
                                            addReq(parseInt(sid), Number(item.id), Number(item.type) || 4);
                                        }
                                    }
                                }
                            }
                        }

                        // 排序：seriesId → id → poolType
                        requests.sort((a, b) => (a.seriesId - b.seriesId) || (a.id - b.id) || (a.poolType - b.poolType));

                        if (requests.length === 0) {
                            logMessage('⚠️ 藏品数据为空，可能未开放或返回结构异常', 'warning');
                            showTip('藏品数据为空', 'warning');
                            return;
                        }
                        logMessage(`🟢 阶段1/4：解析到 ${requests.length} 个藏品项目`, 'info');

                        // ===== 3. 阶段2/4：批量激活 collection_activate =====
                        logMessage('🟢 阶段2/4：批量激活藏品', 'info');
                        for (let i = 0; i < requests.length; i++) {
                            await checkTaskState('藏品激活');
                            const r = requests[i];
                            try {
                                const resp = await executeGameCommandResult('collection_activate', {
                                    id: r.id,
                                    isAll: false,
                                    poolType: r.poolType,
                                    seriesId: r.seriesId
                                }, 8000);
                                if (resp?.code === 0) activateOk++;
                                else activateFail++;
                            } catch (_) {
                                activateFail++;
                            }
                            // 100ms 间隔
                            await new Promise(rs => setTimeout(rs, 100));
                        }
                        logMessage(`✅ 激活完成：成功 ${activateOk} / 失败 ${activateFail}`, 'success');

                        // ===== 4. 阶段3/4：按 seriesId 去重领取系列奖励 =====
                        logMessage('🟢 阶段3/4：领取系列奖励', 'info');
                        const seriesMap = new Map();
                        for (const r of requests) {
                            if (!seriesMap.has(r.seriesId)) seriesMap.set(r.seriesId, r.poolType);
                        }
                        for (const [sid, poolType] of seriesMap.entries()) {
                            await checkTaskState(`系列奖励(${sid})`);
                            try {
                                const resp = await executeGameCommandResult('collection_claimseries', {
                                    seriesId: sid, isAll: true, poolType
                                }, 8000);
                                if (resp?.code === 0) seriesOk++;
                            } catch (_) {}
                            await new Promise(rs => setTimeout(rs, 100));
                        }
                        logMessage(`✅ 系列奖励领取 ${seriesOk} / ${seriesMap.size}`, 'success');

                        // ===== 5. 总览奖励 collection_claimtotal =====
                        await checkTaskState('总览奖励');
                        try {
                            const resp = await executeGameCommandResult('collection_claimtotal', {}, 8000);
                            if (resp?.code === 0) totalOk = 1;
                        } catch (_) {}
                        if (totalOk) logMessage('🎁 总览奖励领取成功', 'success');

                        // ===== 6. 阶段4/4：30 次升级（id=1001, poolType=1, seriesId=3）=====
                        logMessage('🟢 阶段4/4：执行 30 次升级', 'info');
                        for (let i = 1; i <= 30; i++) {
                            await checkTaskState(`藏品升级 ${i}/30`);
                            try {
                                const resp = await executeGameCommandResult('collection_activate', {
                                    id: 1001, isAll: false, poolType: 1, seriesId: 3
                                }, 8000);
                                if (resp?.code === 0) upgradeOk++;
                            } catch (_) {}
                            await new Promise(rs => setTimeout(rs, 50));
                        }
                        logMessage(`✅ 升级完成 ${upgradeOk}/30`, 'success');

                        showTip(`藏品升星完成：激活${activateOk} 系列${seriesOk} 总览${totalOk} 升级${upgradeOk}`, 'success');
                        logMessage(`🎉 藏品升星全部完成：激活${activateOk}（失败${activateFail}）/ 系列${seriesOk} / 总览${totalOk} / 升级${upgradeOk}`, 'success');
                    } catch (err) {
                        logMessage(`藏品升星执行失败: ${err.message}`, 'error');
                        showTip('藏品升星执行失败', 'error');
                    } finally {
                        globalState.activity.consume.isRunning = false;
                        if (activityUIElements.resourcePauseBtn) activityUIElements.resourcePauseBtn.disabled = true;
                        if (activityUIElements.resourceStopBtn) activityUIElements.resourceStopBtn.disabled = true;
                    }
                })();

                globalState.activity.consume.currentTasks.push(task);
            }
        );

        return;
    }

    // ==================== 物品数量获取工具函数 ====================

    // 获取物品数量的通用函数
    function getItemCount(items, id) {
        if (!items) return null;

        // 数组结构：[{id/ itemId, num/count/quantity}, ...]
        if (Array.isArray(items)) {
            const found = items.find(it =>
                Number(it.id ?? it.itemId) === id
            );
            if (!found) return 0;
            return Number(
                found.num ??
                found.count ??
                found.quantity ??
                0
            );
        }

        // 对象结构：{ '1011': 3 } 或 { '1011': { num:3 } }
        const node = items[String(id)] ?? items[id];

        if (node == null) {
            // 兼容值对象中含有 itemId/quantity 的结构
            const match = Object.values(items).find(
                (v) => Number(v?.itemId ?? v?.id) === id
            );
            if (match) return Number(
                match.num ??
                match.count ??
                match.quantity ??
                0
            );
            return 0;
        }

        if (typeof node === "number") return Number(node);
        if (typeof node === "object") return Number(
            node.num ??
            node.count ??
            node.quantity ??
            0
        );
        return Number(node) || 0;
    }

    // 获取特定物品数量
    function getSpecificItemCount(items, itemId) {
        // 特殊处理的物品
        if (itemId === 3001 || itemId === 3002) {
            return getItemCount(items, itemId);
        }

        // 通用物品
        return getItemCount(items, itemId);
    }

    // 数字格式化函数（用于显示）
    function formatNumber(num) {
        const n = Number(num || 0);
        const yi = 100_000_000;
        const wan = 10_000;
        if (n >= yi) return (n / yi).toFixed(1) + "亿";
        if (n >= wan) return (n / wan).toFixed(1) + "万";
        return n.toLocaleString();
    }

    // 显示函数：null/undefined显示为"-"，数字格式化
    function displayItemCount(n) {
        return (n == null ? "-" : formatNumber(Number(n)));
    }

    // 获取所有物品数量的对象（方便调用）
    function getAllItemCounts(roleData) {
        const role = roleData;
        const items = role?.items || role?.itemList || role?.bag?.items || role?.inventory || null;

        return {
            // 宝箱
            chest_2001: getItemCount(items, 2001) || 0,
            chest_2002: getItemCount(items, 2002) || 0,
            chest_2003: getItemCount(items, 2003) || 0,
            chest_2004: getItemCount(items, 2004) || 0,
            chest_2005: getItemCount(items, 2005) || 0,

            // 鱼竿
            fishing_1: getItemCount(items, 1011) || 0,
            fishing_2: getItemCount(items, 1012) || 0,

            // 招募令
            recruit_1: getItemCount(items, 1001) || 0,

            // 免费招募次数（从recruit对象获取）
            recruit_3: role?.recruit?.freeRecruitNum || 0,

            // 火把
            torch_1008: getItemCount(items, 1008) || 0,
            torch_1009: getItemCount(items, 1009) || 0,
            torch_1010: getItemCount(items, 1010) || 0,

            // 原始数据（用于调试）
            rawItems: items,
            rawRole: role
        };
    }

    // 获取资源数量函数
    async function fetchResourceQuantities() {
        try {
            console.log('开始获取角色资源数量...');

            // 获取角色信息
            const roleInfoResponse = await executeGameCommand('role_getroleinfo', {}, '获取角色资源信息');

            if (!roleInfoResponse) {
                throw new Error('获取角色信息失败');
            }

            let roleData = null;

            // 尝试从多个路径获取角色数据
            if (roleInfoResponse._rawData?.role) {
                roleData = roleInfoResponse._rawData.role;
            } else if (roleInfoResponse.data?.role) {
                roleData = roleInfoResponse.data.role;
            } else if (roleInfoResponse.role) {
                roleData = roleInfoResponse.role;
            }

            if (!roleData) {
                throw new Error('无法从响应中获取角色数据');
            }

            // 使用新的getAllItemCounts函数获取物品数量
            const resourceQuantities = getAllItemCounts(roleData);

            // 更新全局状态
            globalState.activity.consume.resourceQuantities = resourceQuantities;

            // 不输出详细日志到日志面板，只输出到控制台
            console.log('资源数量获取完成:', resourceQuantities);

            return resourceQuantities;

        } catch (error) {
            console.log(`获取资源数量失败: ${error.message}`);

            // 返回默认值
            const defaultQuantities = {
                'chest_2001': 0, 'chest_2002': 0, 'chest_2003': 0, 'chest_2004': 0, 'chest_2005': 0,
                'fishing_1': 0, 'fishing_2': 0,
                'recruit_1': 0, 'recruit_3': 0,
                'torch_1008': 0, 'torch_1009': 0, 'torch_1010': 0
            };

            globalState.activity.consume.resourceQuantities = defaultQuantities;
            return defaultQuantities;
        }
    }

