    // ==================== 洗炼模块 QuenchModule ====================

    const QuenchModule = {
        // 常量定义
        ATTR_MAP: {
            "1": "攻击", "2": "血量", "3": "防御", "4": "速度",
            "5": "破甲", "6": "破甲抵抗", "7": "精准", "8": "格挡",
            "9": "减伤", "10": "暴击", "11": "暴击抵抗", "12": "爆伤",
            "13": "爆伤抵抗", "14": "技能伤害", "15": "免控",
            "16": "眩晕免疫", "17": "冰冻免疫", "18": "沉默免疫",
            "19": "流血免疫", "20": "中毒免疫", "21": "灼烧免疫"
        },
        COLOR_MAP: {
            "1": "#8e8e93", "2": "#34c759", "3": "#007aff",
            "4": "#af52de", "5": "#ff9500", "6": "#ff3b30"
        },
        PART_MAP: {
            "1": "武器", "2": "铠甲", "3": "头冠", "4": "坐骑"
        },
        ATTR_MAX_MAP: {
            "1": 10, "2": 10, "3": 10, "4": 10, "5": 20,
            "6": 35, "7": 20, "8": 20, "9": 15, "10": 20,
            "11": 20, "12": 20, "13": 20, "14": 20, "15": 20,
            "16": 40, "17": 40, "18": 40, "19": 40, "20": 40, "21": 40
        },
        // 槽位解锁阈值配置 - 根据洗炼次数解锁槽位
        // 槽位1: 0次, 槽位2: 10次, 槽位3: 100次, 槽位4: 1000次, 槽位5: 10000次
        UNLOCK_THRESHOLDS: {
            "1": [0, 10, 100, 1000, 10000],   // 武器
            "2": [0, 10, 100, 1000, 10000],   // 铠甲
            "3": [0, 10, 100, 1000, 10000],   // 头冠
            "4": [0, 10, 100, 1000, 10000]    // 坐骑
        },
        // 武将数据：从游戏 Configs.HeroConf 动态获取（替代硬编码表）
        HERO_DATA: window.__xc_heroDataProxy,

        // 状态管理
        state: {
            selectedHeroId: null,
            selectedPart: null,
            heroes: {},
            slots: [],
            rawQuenches: {},  // 存储原始服务器quenches数据，用于洗炼请求
            lockedSlots: [],
            targets: [],
            isRunning: false,
            isContinuous: false,
            isAuto: false,
            isTimes: false,
            skipOrange: false,
            skipRed: false,
            quenchCount: 0,
            timesTarget: 0,
            timesCurrent: 0,
            whiteJadeCount: 0,
            colorJadeCount: 0,
            passwordValidated: false,  // 二级密码是否已验证
            cachedPassword: ''         // 缓存的二级密码
        },

        // 辅助方法
        getAttrName(attrId) {
            return this.ATTR_MAP[String(attrId)] || `属性${attrId}`;
        },
        getColorValue(colorId) {
            return this.COLOR_MAP[String(colorId)] || "#8e8e93";
        },
        getPartName(part) {
            return this.PART_MAP[String(part)] || `部位${part}`;
        },
        getAttrMax(attrId) {
            return this.ATTR_MAX_MAP[String(attrId)] || 20;
        },
        getHeroInfo(heroId) {
            return this.HERO_DATA[String(heroId)] || { name: `英雄${heroId}`, type: "未知", quality: "unknown" };
        },

        // 占位方法 - 后续任务实现
        async refreshHeroes() {
            try {
                showTip('正在刷新英雄列表...', 'info');
                const response = await executeGameCommand('role_getroleinfo', {}, '获取角色信息');
                
                if (!response || !response._rawData) {
                    showTip('获取英雄数据失败', 'error');
                    return;
                }

                const role = response._rawData.role || response._rawData;
                const heroes = role.heroes || {};
                const items = role.items || {};

                // 处理英雄装备数据：纳入玩家拥有的全部武将（含未装备者），
                // 以便阵营 tab 能展示对应阵营的所有武将
                const heroesData = {};
                for (const [heroId, heroData] of Object.entries(heroes)) {
                    if (!heroData) continue;
                    const equipment = heroData.equipment || {};
                    const equipLevels = Object.values(equipment).map(e => e?.level || 0);
                    const maxLevel = equipLevels.length ? Math.max(...equipLevels) : 0;
                    const heroInfo = this.getHeroInfo(heroId);
                    heroesData[heroId] = {
                        heroId: Number(heroId),
                        name: heroInfo.name,
                        type: heroInfo.type,
                        quality: heroInfo.quality,
                        maxLevel: maxLevel,
                        hasEquipment: Object.keys(equipment).length > 0,
                        equipment: equipment
                    };
                }

                this.state.heroes = heroesData;
                this.state.whiteJadeCount = items['1022']?.quantity ?? items[1022]?.quantity ?? 0;
                this.state.colorJadeCount = items['1023']?.quantity ?? items[1023]?.quantity ?? 0;

                this.renderHeroList();
                this.updateJadeDisplay();
                showTip(`已加载 ${Object.keys(heroesData).length} 个英雄`, 'success');
            } catch (error) {
                console.error('[洗炼] 刷新英雄列表失败:', error);
                showTip('刷新英雄列表失败: ' + error.message, 'error');
            }
        },

        renderHeroList() {
            const container = document.getElementById('quenchHeroList');
            if (!container) return;

            const heroes = Object.values(this.state.heroes || {});
            if (heroes.length === 0) {
                container.innerHTML = '<div class="quench-empty-state">点击刷新按钮加载英雄列表</div>';
                return;
            }

            // 排序：已装备 > 未装备；同组按品质（红 > 橙 > 紫），同品质按等级降序
            const qualityOrder = { red: 0, orange: 1, purple: 2, unknown: 3 };
            heroes.sort((a, b) => {
                const ga = a.hasEquipment ? 0 : 1;
                const gb = b.hasEquipment ? 0 : 1;
                if (ga !== gb) return ga - gb;
                const qa = qualityOrder[a.quality] ?? 3;
                const qb = qualityOrder[b.quality] ?? 3;
                if (qa !== qb) return qa - qb;
                return (b.maxLevel || 0) - (a.maxLevel || 0);
            });

            container.innerHTML = heroes.map(hero => {
                const stateClass = hero.hasEquipment ? '' : 'no-equip';
                const levelText = hero.hasEquipment ? `Lv.${hero.maxLevel || 0}` : '未装备';
                const titleText = hero.hasEquipment ? '' : '该武将未装备装备';
                return `
                <div class="quench-hero-item quality-${hero.quality} ${this.state.selectedHeroId === hero.heroId ? 'active' : ''} ${stateClass}"
                     onclick="QuenchModule.selectHero(${hero.heroId})"
                     title="${titleText}">
                    <div class="hero-name">${hero.name}</div>
                    <div class="hero-level">${levelText}</div>
                </div>`;
            }).join('');
        },
        selectHero(heroId) {
            this.state.selectedHeroId = heroId;
            this.state.selectedPart = null;
            this.state.slots = [];
            this.state.rawQuenches = {};
            this.state.lockedSlots = [];
            this.state.quenchCount = 0;

            // 更新英雄列表UI
            document.querySelectorAll('#quenchHeroList .quench-hero-item').forEach(item => {
                item.classList.remove('active');
            });
            const selectedItem = document.querySelector(`#quenchHeroList .quench-hero-item[onclick*="${heroId}"]`);
            if (selectedItem) selectedItem.classList.add('active');

            // 更新部位等级显示
            const hero = this.state.heroes[heroId];
            if (hero && hero.equipment) {
                for (let part = 1; part <= 4; part++) {
                    const levelEl = document.getElementById(`quenchPartLevel${part}`);
                    if (levelEl) {
                        const eq = hero.equipment[String(part)];
                        levelEl.textContent = eq ? `Lv.${eq.level || 0}` : '--';
                    }
                }
            }

            // 重置部位选中状态
            document.querySelectorAll('#quenchPartTabs .quench-part-tab').forEach(tab => {
                tab.classList.remove('active');
            });

            // 清空槽位显示
            const slotList = document.getElementById('quenchSlotList');
            if (slotList) {
                slotList.innerHTML = '<div class="quench-empty-state">选择部位后显示洗炼属性</div>';
            }

            // 更新洗炼次数显示
            const countDisplay = document.getElementById('quenchCountDisplay');
            if (countDisplay) countDisplay.textContent = '0';

            this.updateButtonStates();
            logMessage(`[洗炼] 选择英雄: ${hero?.name || heroId}`, 'info');
        },
        async selectPart(part) {
            if (!this.state.selectedHeroId) {
                showTip('请先选择英雄', 'warning');
                return;
            }

            this.state.selectedPart = part;
            this.state.rawQuenches = {};
            this.state.lockedSlots = [];
            this.state.quenchCount = 0;

            // 更新部位选中状态
            document.querySelectorAll('#quenchPartTabs .quench-part-tab').forEach(tab => {
                tab.classList.remove('active');
            });
            const selectedTab = document.querySelector(`#quenchPartTabs .quench-part-tab[data-part="${part}"]`);
            if (selectedTab) selectedTab.classList.add('active');

            // 获取洗炼数据
            try {
                const hero = this.state.heroes[this.state.selectedHeroId];
                if (!hero || !hero.equipment || !hero.equipment[String(part)]) {
                    showTip('该部位没有装备数据', 'warning');
                    return;
                }

                const equipment = hero.equipment[String(part)];
                const quenchTimes = equipment.quenchTimes || 0;
                const quenches = equipment.quenches || {};
                
                // 存储原始quenches数据，用于洗炼请求
                this.state.rawQuenches = JSON.parse(JSON.stringify(quenches));

                // 计算解锁槽位数 - 所有部位解锁阈值相同
                const unlockThresholds = [0, 10, 100, 1000, 10000];
                let unlockedSlotCount = 0;
                for (let i = 0; i < unlockThresholds.length; i++) {
                    if (quenchTimes >= unlockThresholds[i]) {
                        unlockedSlotCount = i + 1;
                    } else {
                        break;
                    }
                }

                // 构建槽位数据
                const slots = [];
                const serverLockedSlots = []; // 从服务器获取的锁定槽位
                for (let slotId = 1; slotId <= unlockedSlotCount; slotId++) {
                    const slotData = quenches[String(slotId)] || quenches[slotId];
                    if (slotData) {
                        const attrIdNum = Number(slotData.attrId) || 0;
                        const attrNumVal = Number(slotData.attrNum) || 0;
                        const colorIdNum = Number(slotData.colorId) || 0;
                        const attrMax = this.getAttrMax(attrIdNum);
                        const realPercent = (attrMax * (attrNumVal / 100)).toFixed(1);
                        // 从服务器数据读取锁定状态
                        const isLocked = Boolean(slotData.isLocked || slotData.locked);
                        if (isLocked) {
                            serverLockedSlots.push(slotId);
                        }
                        slots.push({
                            slotId,
                            attrId: attrIdNum,
                            attrName: this.getAttrName(attrIdNum),
                            attrNum: attrNumVal,
                            attrMax,
                            realPercent,
                            colorId: colorIdNum,
                            colorValue: this.getColorValue(colorIdNum),
                            isLocked: isLocked
                        });
                    } else {
                        slots.push({
                            slotId,
                            attrId: 0,
                            attrName: '',
                            attrNum: 0,
                            attrMax: 0,
                            realPercent: '0.0',
                            colorId: 0,
                            colorValue: '#8e8e93',
                            isLocked: false
                        });
                    }
                }

                this.state.slots = slots;
                // 同步服务器的锁定状态到lockedSlots数组
                this.state.lockedSlots = serverLockedSlots;

                // 更新统计显示
                const statsEl = document.getElementById('quenchEquipStats');
                if (statsEl) {
                    const statKey = part === 1 ? 'quenchAttackExt' :
                        part === 3 ? 'quenchDefenseExt' : 'quenchHpExt';
                    const statLabel = part === 1 ? '攻击' : part === 3 ? '防御' : '血量';
                    statsEl.innerHTML = `
                        <span class="quench-stat-item">${statLabel}加成: <strong>+${equipment[statKey] || 0}</strong></span>
                        <span class="quench-stat-item">次数: <strong>${quenchTimes}</strong></span>
                    `;
                }

                // 显示解锁信息
                const unlockInfo = document.getElementById('quenchUnlockInfo');
                if (unlockInfo && unlockedSlotCount < 5) {
                    const nextThreshold = unlockThresholds[unlockedSlotCount];
                    const nextSlotId = unlockedSlotCount + 1;
                    const remainingTimes = nextThreshold - quenchTimes;
                    unlockInfo.style.display = 'block';
                    unlockInfo.innerHTML = `洗炼 <strong>${remainingTimes}</strong> 次后解锁槽位 <strong>${nextSlotId}</strong>`;
                } else if (unlockInfo) {
                    unlockInfo.style.display = 'none';
                }

                this.renderSlots();
                this.updateButtonStates();
                logMessage(`[洗炼] 选择部位: ${this.getPartName(part)}`, 'info');
            } catch (error) {
                console.error('[洗炼] 获取洗炼数据失败:', error);
                showTip('获取洗炼数据失败', 'error');
            }
        },
        renderSlots() {
            const slotList = document.getElementById('quenchSlotList');
            if (!slotList) return;

            const slots = this.state.slots;

            // 处理空状态
            if (!slots || slots.length === 0) {
                slotList.innerHTML = '<div class="quench-empty-state">选择英雄和部位后显示洗炼属性</div>';
                return;
            }

            // 渲染槽位列表 - 开关在右边，百分比颜色与属性颜色一致
            slotList.innerHTML = slots.map(slot => {
                const isLocked = this.state.lockedSlots.includes(slot.slotId);
                const lockedClass = isLocked ? 'locked' : '';
                
                // 处理空槽位（未洗炼过的槽位）
                if (!slot.attrId || slot.attrId === 0) {
                    return `
                        <div class="quench-slot-item ${lockedClass}" data-slot-id="${slot.slotId}">
                            <span class="quench-slot-label">${slot.slotId}</span>
                            <span class="quench-slot-empty">未洗炼</span>
                            <label class="quench-slot-switch">
                                <input type="checkbox" ${isLocked ? 'checked' : ''} 
                                       onchange="QuenchModule.toggleLock(${slot.slotId})">
                                <span class="switch-slider">
                                    <span class="switch-text">${isLocked ? '锁' : ''}</span>
                                </span>
                            </label>
                        </div>
                    `;
                }

                // 渲染有属性的槽位 - 开关在右边，百分比颜色与属性颜色一致
                return `
                    <div class="quench-slot-item ${lockedClass}" data-slot-id="${slot.slotId}">
                        <span class="quench-slot-label">${slot.slotId}</span>
                        <div class="quench-slot-attr" style="color: ${slot.colorValue};">
                            <span class="attr-name">${slot.attrName}</span>
                            <span class="attr-real-percent">+${slot.realPercent}%</span>
                            <span class="attr-slot-percent" style="color: ${slot.colorValue};">${slot.attrNum}%</span>
                        </div>
                        <label class="quench-slot-switch">
                            <input type="checkbox" ${isLocked ? 'checked' : ''} 
                                   onchange="QuenchModule.toggleLock(${slot.slotId})">
                            <span class="switch-slider">
                                <span class="switch-text">${isLocked ? '锁' : ''}</span>
                            </span>
                        </label>
                    </div>
                `;
            }).join('');

            // 更新洗炼次数显示
            const countDisplay = document.getElementById('quenchCountDisplay');
            if (countDisplay) {
                countDisplay.textContent = String(this.state.quenchCount);
            }
        },
        async toggleLock(slotId) {
            const slot = this.state.slots.find(s => s.slotId === slotId);
            if (!slot) {
                logMessage(`[洗炼] 槽位 ${slotId} 不存在`, 'warning');
                return;
            }

            const newLockState = !slot.isLocked;
            const params = {
                heroId: Number(this.state.selectedHeroId),
                part: Number(this.state.selectedPart),
                slot: slotId,
                isLocked: newLockState
            };

            try {
                // 使用sendEquipmentCommand：BON编码body，与xingchi完全一致
                const result = await this.sendEquipmentCommand('equipment_updatequenchlock', params);

                if (result.code === 200020 || result.code === 7500140) {
                    logMessage('[洗炼] 槽位锁定需要二级密码验证', 'warning');
                    await this.handlePasswordRequired();
                    return this.toggleLock(slotId);
                }

                if (result.code !== 0) {
                    showTip(`锁定状态更新失败 [Code: ${result.code}]`, 'error');
                    this.restoreCheckbox(slotId, slot.isLocked);
                    return;
                }

                // 服务器确认后更新本地状态
                slot.isLocked = newLockState;
                if (newLockState) {
                    if (!this.state.lockedSlots.includes(slotId)) {
                        this.state.lockedSlots.push(slotId);
                    }
                } else {
                    const idx = this.state.lockedSlots.indexOf(slotId);
                    if (idx !== -1) this.state.lockedSlots.splice(idx, 1);
                }

                // 更新UI
                const slotElement = document.querySelector(`.quench-slot-item[data-slot-id="${slotId}"]`);
                if (slotElement) {
                    if (newLockState) {
                        slotElement.classList.add('locked');
                    } else {
                        slotElement.classList.remove('locked');
                    }
                    const switchText = slotElement.querySelector('.switch-text');
                    if (switchText) {
                        switchText.textContent = newLockState ? '锁' : '';
                    }
                }

                logMessage(`[洗炼] 槽位 ${slotId} 已${newLockState ? '锁定' : '解锁'}`, 'info');
            } catch (error) {
                logMessage(`[洗炼] 槽位锁定操作失败: ${error.message}`, 'error');
                this.restoreCheckbox(slotId, slot.isLocked);
            }
        },
        restoreCheckbox(slotId, isLocked) {
            const slotElement = document.querySelector(`.quench-slot-item[data-slot-id="${slotId}"]`);
            if (slotElement) {
                const checkbox = slotElement.querySelector('input[type="checkbox"]');
                if (checkbox) checkbox.checked = isLocked;
                const switchText = slotElement.querySelector('.switch-text');
                if (switchText) switchText.textContent = isLocked ? '锁' : '';
            }
        },

        // 命令默认body映射（与xingchi MessageUtils.COMMAND_DEFAULT_BODIES完全一致）
        COMMAND_DEFAULT_BODIES: {
            'equipment_confirm': {
                heroId: 0,
                part: 0,
                quenchId: 0,
                quenches: {}
            },
            'equipment_quench': {
                heroId: 0,
                part: 0,
                quenchId: 0,
                quenches: {},
                seed: 0,
                skipOrange: false
            },
            'equipment_updatequenchlock': {
                heroId: 0,
                part: 0,
                slot: 0,
                isLocked: false
            }
        },

        /**
         * 发送洗炼相关命令（与xingchi MessageUtils.buildCommandMessage + executeCommand完全一致）
         * 关键：使用 window.g_utils.bon.encode 对 params 进行 BON 编码后放入 body 字段
         * 响应使用 _rawData 或 getData() 获取解码后的 body 数据
         */
        async sendEquipmentCommand(cmd, params = {}, timeout = 15000) {
            const windowRef = (typeof unsafeWindow !== 'undefined' && unsafeWindow) ? unsafeWindow : window;
            const gameWS = windowRef.ws;
            if (!gameWS || typeof gameWS.sendAsync !== 'function') {
                throw new Error('WebSocket连接不可用');
            }

            // 与xingchi MessageUtils.buildCommandMessage一致：先合并默认body和params，再BON编码
            const defaultBody = this.COMMAND_DEFAULT_BODIES[cmd] || {};
            const mergedParams = { ...defaultBody, ...params };

            let message;
            // 优先使用游戏内置的BON编码器（与xyzw_web_helper CommandRegistry.register一致）
            if (windowRef.g_utils?.bon?.encode) {
                message = {
                    ack: 0,
                    body: windowRef.g_utils.bon.encode(mergedParams),
                    cmd: cmd,
                    seq: Date.now(),
                    time: Date.now()
                };
            } else {
                // 降级：直接传params（可能不适用于所有命令）
                message = {
                    ack: 0,
                    cmd: cmd,
                    params: mergedParams,
                    seq: Date.now(),
                    time: Date.now()
                };
                console.warn('[洗炼] g_utils.bon.encode 不可用，使用params降级模式');
            }

            const response = await gameWS.sendAsync(message);

            // 解析响应（与xingchi connectionManager.executeCommand一致）
            // sendAsync返回的response: { code, _rawData, getData(), ... }
            const code = response?.code ?? -1;
            const data = response?.getData ? response.getData() : (response?._rawData || response || {});

            return { code, data, raw: response };
        },

        async doQuenchOnce(retryCount = 0) {
            // 1. 检查前置条件
            if (!this.state.selectedHeroId) {
                showTip('请先选择英雄', 'warning');
                return { success: false, error: '未选择英雄' };
            }
            if (!this.state.selectedPart) {
                showTip('请先选择装备部位', 'warning');
                return { success: false, error: '未选择部位' };
            }

            // 2. 检查是否正在运行（仅首次调用检查）
            if (retryCount === 0 && this.state.isRunning) {
                showTip('洗炼正在进行中', 'warning');
                return { success: false, error: '洗炼正在进行中' };
            }

            // 设置运行状态
            if (retryCount === 0) {
                this.state.isRunning = true;
                this.updateButtonStates();
            }

            try {
                const heroId = Number(this.state.selectedHeroId);
                const part = Number(this.state.selectedPart);
                
                // === 第1步：获取装备数据（与xingchi doQuench一致） ===
                const hero = this.state.heroes[heroId];
                const equipment = hero?.equipment?.[String(part)];
                
                if (!equipment || !equipment.quenches || Object.keys(equipment.quenches).length === 0) {
                    return { success: false, error: '未获取到装备孔位信息，请确认装备已解锁洗炼' };
                }
                
                // 不做任何字段过滤或类型转换，保持与服务器返回的数据完全一致
                const rawQuenches = equipment.quenches;

                // === 第2步：检查是否需要equipment_confirm获取seed（与xingchi doQuench一致） ===
                const hasHighAttrSlot = Object.values(rawQuenches).some(s =>
                    Number(s.attrNum) > 50 && !s.isLocked
                );
                let seed = 0;

                if (hasHighAttrSlot) {
                    const confirmParams = {
                        heroId: heroId,
                        part: part,
                        quenchId: 0,
                        quenches: rawQuenches
                    };

                    logMessage(`[洗炼] 调用equipment_confirm获取seed...`, 'info');
                    // 使用sendEquipmentCommand：BON编码body，与xingchi完全一致
                    const confirmResult = await this.sendEquipmentCommand('equipment_confirm', confirmParams);
                    
                    if (confirmResult.code === 0) {
                        // confirmResult.data 已经是解码后的body数据（与xingchi executeCommand一致）
                        const cData = confirmResult.data || {};
                        // 格式1: role.heroes[heroId].equipment[part].seed
                        if (cData?.role?.heroes) {
                            const cHero = cData.role.heroes[String(heroId)];
                            if (cHero?.equipment?.[String(part)]?.seed) {
                                seed = cHero.equipment[String(part)].seed;
                            }
                        }
                        // 格式2: seed直接在body中
                        if (!seed && cData?.seed) {
                            seed = cData.seed;
                        }
                        // 格式3: equipment.seed
                        if (!seed && cData?.equipment?.seed) {
                            seed = cData.equipment.seed;
                        }
                        logMessage(`[洗炼] 获取到seed: ${seed}`, 'info');
                    } else {
                        // 与xingchi一致：confirm失败直接返回失败
                        return { success: false, error: `洗炼验证失败 [Code: ${confirmResult.code}]` };
                    }
                }

                // === 第3步：执行洗炼（与xingchi doQuench一致） ===
                const quenchParams = {
                    heroId: heroId,
                    part: part,
                    quenchId: 0,
                    quenches: rawQuenches,
                    seed: seed,
                    skipOrange: false
                };

                logMessage(`[洗炼] 执行洗炼...`, 'info');
                // 使用sendEquipmentCommand：BON编码body，与xingchi完全一致
                const quenchResult = await this.sendEquipmentCommand('equipment_quench', quenchParams);

                if (quenchResult.code !== 0) {
                    const errorCode = quenchResult.code;
                    
                    // 与xingchi一致：仅200400重试一次
                    if (retryCount < 1 && errorCode === 200400) {
                        logMessage('[洗炼] 操作太快(200400)，1秒后重试...', 'warning');
                        await new Promise(resolve => setTimeout(resolve, 1000));
                        return this.doQuenchOnce(retryCount + 1);
                    }
                    
                    // 其他错误码直接返回失败（与xingchi一致）
                    return { success: false, error: `洗炼失败 [Code: ${errorCode}]` };
                }

                // === 第4步：解析洗炼结果（与xingchi doQuench一致） ===
                // quenchResult.data 已经是解码后的body数据
                const rData = quenchResult.data || {};

                // 格式1: role.heroes[heroId].equipment[part]（完整角色数据）
                let updatedEquipment = rData?.role?.heroes?.[String(heroId)]?.equipment?.[String(part)];
                // 格式2: 直接返回 equipment
                if (!updatedEquipment && rData?.equipment) {
                    updatedEquipment = rData.equipment;
                }
                // 格式3: 直接返回 quenches
                if (!updatedEquipment && rData?.quenches) {
                    updatedEquipment = {
                        ...equipment,
                        quenches: rData.quenches,
                        quenchTimes: (equipment.quenchTimes || 0) + 1
                    };
                }
                
                const resultItems = rData?.role?.items || rData?.items || {};

                // === 第5步：构建槽位数据（与xingchi doQuench一致） ===
                const newSlots = [];
                if (updatedEquipment?.quenches) {
                    const unlockThresholds = [0, 10, 100, 1000, 10000];
                    const newQuenchTimes = updatedEquipment.quenchTimes || 0;
                    
                    let unlockedSlotCount = 0;
                    for (let i = 0; i < unlockThresholds.length; i++) {
                        if (newQuenchTimes >= unlockThresholds[i]) {
                            unlockedSlotCount = i + 1;
                        } else {
                            break;
                        }
                    }
                    
                    const quenchesData = updatedEquipment.quenches;
                    
                    // 更新英雄装备缓存（关键：下次循环读到最新数据）
                    if (hero && hero.equipment && hero.equipment[String(part)]) {
                        hero.equipment[String(part)] = updatedEquipment;
                    }
                    
                    for (let slotId = 1; slotId <= unlockedSlotCount; slotId++) {
                        const slotData = quenchesData[String(slotId)] || quenchesData[slotId];
                        if (slotData) {
                            const isLocked = Boolean(slotData.isLocked || slotData.locked);
                            const attrIdNum = Number(slotData.attrId) || 0;
                            const attrNumVal = Number(slotData.attrNum) || 0;
                            const colorIdNum = Number(slotData.colorId) || 0;
                            const attrMax = this.getAttrMax(attrIdNum);
                            const realPercent = (attrMax * (attrNumVal / 100)).toFixed(1);
                            newSlots.push({
                                slotId, attrId: attrIdNum, attrName: this.getAttrName(attrIdNum),
                                attrNum: attrNumVal, attrMax, realPercent,
                                colorId: colorIdNum, colorValue: this.getColorValue(colorIdNum),
                                isLocked
                            });
                        } else {
                            newSlots.push({
                                slotId, attrId: 0, attrName: '', attrNum: 0, attrMax: 0,
                                realPercent: '0.0', colorId: 0, colorValue: '#8e8e93', isLocked: false
                            });
                        }
                    }
                    newSlots.sort((a, b) => a.slotId - b.slotId);
                    
                    this.state.lockedSlots = newSlots.filter(s => s.isLocked).map(s => s.slotId);
                }

                // 更新UI状态
                if (newSlots.length > 0) {
                    this.state.slots = newSlots;
                }
                this.state.quenchCount++;

                // 更新白玉彩玉数量（与xingchi一致）
                const newWhiteJade = resultItems?.['1022']?.quantity ?? resultItems?.[1022]?.quantity;
                const newColorJade = resultItems?.['1023']?.quantity ?? resultItems?.[1023]?.quantity;
                if (newWhiteJade !== undefined) this.state.whiteJadeCount = newWhiteJade;
                if (newColorJade !== undefined) this.state.colorJadeCount = newColorJade;
                this.updateJadeDisplay();

                // 更新统计显示
                const statsEl = document.getElementById('quenchEquipStats');
                if (statsEl && updatedEquipment) {
                    const statKey = part === 1 ? 'quenchAttackExt' :
                        part === 3 ? 'quenchDefenseExt' : 'quenchHpExt';
                    const statLabel = part === 1 ? '攻击' : part === 3 ? '防御' : '血量';
                    statsEl.innerHTML = `
                        <span class="quench-stat-item">${statLabel}加成: <strong>+${updatedEquipment[statKey] || 0}</strong></span>
                        <span class="quench-stat-item">次数: <strong>${updatedEquipment.quenchTimes || 0}</strong></span>
                    `;
                }

                // 更新解锁提示
                const unlockInfo = document.getElementById('quenchUnlockInfo');
                if (unlockInfo && updatedEquipment) {
                    const newQuenchTimes = updatedEquipment.quenchTimes || 0;
                    const unlockThresholds = [0, 10, 100, 1000, 10000];
                    let currentUnlockedCount = 0;
                    for (let i = 0; i < unlockThresholds.length; i++) {
                        if (newQuenchTimes >= unlockThresholds[i]) {
                            currentUnlockedCount = i + 1;
                        } else {
                            break;
                        }
                    }
                    if (currentUnlockedCount < 5) {
                        const nextThreshold = unlockThresholds[currentUnlockedCount];
                        const remainingTimes = nextThreshold - newQuenchTimes;
                        unlockInfo.style.display = 'block';
                        unlockInfo.innerHTML = `洗炼 <strong>${remainingTimes}</strong> 次后解锁槽位 <strong>${currentUnlockedCount + 1}</strong>`;
                    } else {
                        unlockInfo.style.display = 'none';
                    }
                }

                this.renderSlots();

                const hasNewOrangeOrAbove = newSlots.some(s => !s.isLocked && s.colorId >= 5);
                const hasNewRed = newSlots.some(s => !s.isLocked && s.colorId >= 6);
                const hasNewOrange = newSlots.some(s => !s.isLocked && s.colorId === 5);

                logMessage(`[洗炼] 洗炼成功，第 ${this.state.quenchCount} 次`, 'success');

                return {
                    success: true,
                    slots: newSlots,
                    quenchCount: this.state.quenchCount,
                    hasOrangeOrAbove: hasNewOrangeOrAbove,
                    hasOrange: hasNewOrange,
                    hasRed: hasNewRed,
                    quenchTimes: updatedEquipment?.quenchTimes || 0
                };

            } catch (error) {
                console.error('[洗炼] 洗炼失败:', error);
                showTip('洗炼失败: ' + error.message, 'error');
                logMessage(`[洗炼] 洗炼失败: ${error.message}`, 'error');
                return { success: false, error: error.message };
            } finally {
                this.state.isRunning = false;
                this.updateButtonStates();
            }
        },
        async startContinuousQuench() {
            // 检查前置条件
            if (!this.state.selectedHeroId) {
                showTip('请先选择英雄', 'warning');
                return;
            }
            if (!this.state.selectedPart) {
                showTip('请先选择装备部位', 'warning');
                return;
            }
            if (this.state.isContinuous || this.state.isAuto || this.state.isTimes) {
                showTip('已有洗炼操作正在进行', 'warning');
                return;
            }

            // 设置连续洗炼标志
            this.state.isContinuous = true;
            this.updateButtonStates();
            logMessage('[洗炼] 开始连续洗炼...', 'info');
            showTip('开始连续洗炼', 'info');

            // 循环执行洗炼直到出现橙色/红色或被停止（与xingchi businessController一致）
            while (this.state.isContinuous) {
                try {
                    const result = await this.doQuenchOnce();
                    
                    if (!result.success) {
                        logMessage(`[洗炼] 连续洗炼中断: ${result.error}`, 'error');
                        showTip(`连续洗炼中断: ${result.error}`, 'error');
                        break;
                    }

                    // 检查未锁定槽位是否出现橙色或红色属性（与xingchi businessController一致：锁定的槽位不参与停止判断）
                    if (result.hasRed) {
                        if (!this.state.skipRed) {
                            logMessage(`[洗炼] 出现红色属性，连续洗炼停止 (第 ${result.quenchCount} 次)`, 'success');
                            showTip('出现红色属性，连续洗炼停止', 'success');
                            break;
                        } else {
                            logMessage(`[洗炼] 出现红色属性，跳过继续洗炼 (第 ${result.quenchCount} 次)`, 'info');
                        }
                    } else if (result.hasOrange) {
                        if (!this.state.skipOrange) {
                            logMessage(`[洗炼] 出现橙色属性，连续洗炼停止 (第 ${result.quenchCount} 次)`, 'success');
                            showTip('出现橙色属性，连续洗炼停止', 'success');
                            break;
                        } else {
                            logMessage(`[洗炼] 出现橙色属性，跳过继续洗炼 (第 ${result.quenchCount} 次)`, 'info');
                        }
                    }

                    // 添加随机延迟，避免请求过快（参考xingchi: 350 + random(0~150)ms）
                    const loopDelay = Math.floor(Math.random() * 150) + 350;
                    await new Promise(resolve => setTimeout(resolve, loopDelay));

                } catch (error) {
                    console.error('[洗炼] 连续洗炼出错:', error);
                    logMessage(`[洗炼] 连续洗炼出错: ${error.message}`, 'error');
                    showTip(`连续洗炼出错: ${error.message}`, 'error');
                    break;
                }
            }

            // 清除连续洗炼标志
            this.state.isContinuous = false;
            this.updateButtonStates();
            logMessage(`[洗炼] 连续洗炼结束，共洗炼 ${this.state.quenchCount} 次`, 'info');
        },
        stopContinuousQuench() {
            if (!this.state.isContinuous) {
                return;
            }
            
            // 清除连续洗炼标志
            this.state.isContinuous = false;
            this.updateButtonStates();
            logMessage('[洗炼] 连续洗炼已停止', 'info');
            showTip('连续洗炼已停止', 'info');
        },
        async startAutoQuench() {
            // 1. 检查前置条件
            if (!this.state.selectedHeroId) {
                showTip('请先选择英雄', 'warning');
                return;
            }
            if (!this.state.selectedPart) {
                showTip('请先选择装备部位', 'warning');
                return;
            }
            
            // 2. 检查是否有定义目标
            if (!this.state.targets || this.state.targets.length === 0) {
                showTip('请先添加目标属性', 'warning');
                logMessage('[洗炼] 自动洗炼需要先定义目标属性', 'warning');
                return;
            }
            
            // 3. 检查是否已有操作在进行
            if (this.state.isContinuous || this.state.isAuto || this.state.isTimes) {
                showTip('已有洗炼操作正在进行', 'warning');
                return;
            }

            // 4. 设置isAuto标志
            this.state.isAuto = true;
            this.updateButtonStates();
            logMessage('[洗炼] 开始自动洗炼...', 'info');
            showTip('开始自动洗炼', 'info');

            // 5. 循环执行洗炼并检查目标（与xingchi一致）
            while (this.state.isAuto) {
                try {
                    const result = await this.doQuenchOnce();
                    
                    if (!result.success) {
                        logMessage(`[洗炼] 自动洗炼中断: ${result.error}`, 'error');
                        showTip(`自动洗炼中断: ${result.error}`, 'error');
                        break;
                    }

                    // 6. 检查是否达到目标
                    if (this.checkTargetReached()) {
                        logMessage(`[洗炼] 达到目标属性，自动洗炼停止 (第 ${result.quenchCount} 次)`, 'success');
                        showTip('达到目标属性，自动洗炼停止', 'success');
                        break;
                    }

                    // 添加随机延迟，避免请求过快（参考xingchi: 350 + random(0~150)ms）
                    const loopDelay = Math.floor(Math.random() * 150) + 350;
                    await new Promise(resolve => setTimeout(resolve, loopDelay));

                } catch (error) {
                    console.error('[洗炼] 自动洗炼出错:', error);
                    logMessage(`[洗炼] 自动洗炼出错: ${error.message}`, 'error');
                    showTip(`自动洗炼出错: ${error.message}`, 'error');
                    break;
                }
            }

            // 清除isAuto标志
            this.state.isAuto = false;
            this.updateButtonStates();
            logMessage(`[洗炼] 自动洗炼结束，共洗炼 ${this.state.quenchCount} 次`, 'info');
        },
        stopAutoQuench() {
            if (!this.state.isAuto) {
                return;
            }
            
            // 清除isAuto标志
            this.state.isAuto = false;
            // 恢复UI按钮状态
            this.updateButtonStates();
            logMessage('[洗炼] 自动洗炼已停止', 'info');
            showTip('自动洗炼已停止', 'info');
        },
        async startTimesQuench() {
            // 1. 检查前置条件
            if (!this.state.selectedHeroId) {
                showTip('请先选择英雄', 'warning');
                return;
            }
            if (!this.state.selectedPart) {
                showTip('请先选择装备部位', 'warning');
                return;
            }
            
            // 2. 检查是否已有操作在进行
            if (this.state.isContinuous || this.state.isAuto || this.state.isTimes) {
                showTip('已有洗炼操作正在进行', 'warning');
                return;
            }

            // 3. 验证输入次数（10-10000）
            const inputEl = document.getElementById('quenchTimesInput');
            const inputValue = inputEl ? parseInt(inputEl.value, 10) : 0;
            
            if (isNaN(inputValue) || inputValue < 10 || inputValue > 10000) {
                showTip('洗炼次数必须在 10-10000 之间', 'warning');
                logMessage('[洗炼] 输入次数无效，必须在 10-10000 之间', 'warning');
                return;
            }

            // 4. 设置isTimes标志和目标次数
            this.state.isTimes = true;
            this.state.timesTarget = inputValue;
            this.state.timesCurrent = 0;
            this.updateButtonStates();
            
            // 更新进度显示
            const progressEl = document.getElementById('quenchTimesProgress');
            if (progressEl) {
                progressEl.textContent = `0/${inputValue}`;
            }
            
            logMessage(`[洗炼] 开始指定次数洗炼，目标: ${inputValue} 次`, 'info');
            showTip(`开始指定次数洗炼 (${inputValue}次)`, 'info');

            // 5. 循环执行指定次数洗炼（与xingchi一致）
            while (this.state.isTimes && this.state.timesCurrent < this.state.timesTarget) {
                try {
                    const result = await this.doQuenchOnce();
                    
                    if (!result.success) {
                        logMessage(`[洗炼] 指定次数洗炼中断: ${result.error}`, 'error');
                        showTip(`指定次数洗炼中断: ${result.error}`, 'error');
                        break;
                    }

                    // 更新当前进度
                    this.state.timesCurrent++;
                    
                    // 6. 显示进度
                    if (progressEl) {
                        progressEl.textContent = `${this.state.timesCurrent}/${this.state.timesTarget}`;
                    }

                    // 每100次输出一次日志
                    if (this.state.timesCurrent % 100 === 0) {
                        logMessage(`[洗炼] 指定次数洗炼进度: ${this.state.timesCurrent}/${this.state.timesTarget}`, 'info');
                    }

                    // 添加随机延迟，避免请求过快（参考xingchi: 350 + random(0~150)ms）
                    const loopDelay = Math.floor(Math.random() * 150) + 350;
                    await new Promise(resolve => setTimeout(resolve, loopDelay));

                } catch (error) {
                    console.error('[洗炼] 指定次数洗炼出错:', error);
                    logMessage(`[洗炼] 指定次数洗炼出错: ${error.message}`, 'error');
                    showTip(`指定次数洗炼出错: ${error.message}`, 'error');
                    break;
                }
            }

            // 检查是否完成了所有次数
            const completed = this.state.timesCurrent >= this.state.timesTarget;
            
            // 清除isTimes标志
            this.state.isTimes = false;
            this.updateButtonStates();
            
            if (completed) {
                logMessage(`[洗炼] 指定次数洗炼完成，共洗炼 ${this.state.timesCurrent} 次`, 'success');
                showTip(`指定次数洗炼完成 (${this.state.timesCurrent}次)`, 'success');
            } else {
                logMessage(`[洗炼] 指定次数洗炼结束，已洗炼 ${this.state.timesCurrent}/${this.state.timesTarget} 次`, 'info');
            }
        },
        stopTimesQuench() {
            if (!this.state.isTimes) {
                return;
            }
            
            // 清除isTimes标志
            this.state.isTimes = false;
            // 恢复UI按钮状态
            this.updateButtonStates();
            logMessage(`[洗炼] 指定次数洗炼已停止，已完成 ${this.state.timesCurrent}/${this.state.timesTarget} 次`, 'info');
            showTip('指定次数洗炼已停止', 'info');
        },
        addTarget() {
            // 添加新目标到targets数组
            const newTarget = {
                attrId: 1,  // 默认选择攻击属性
                value: 80   // 默认目标值80%
            };
            this.state.targets.push(newTarget);
            
            // 渲染目标列表UI
            this.renderTargets();
            
            logMessage(`[洗炼] 添加目标属性: ${this.getAttrName(newTarget.attrId)} >= ${newTarget.value}%`, 'info');
        },
        removeTarget(index) {
            // 验证索引有效性
            if (index < 0 || index >= this.state.targets.length) {
                logMessage(`[洗炼] 无效的目标索引: ${index}`, 'warning');
                return;
            }
            
            // 从targets数组移除指定目标
            const removed = this.state.targets.splice(index, 1)[0];
            
            // 更新目标列表UI
            this.renderTargets();
            
            logMessage(`[洗炼] 移除目标属性: ${this.getAttrName(removed.attrId)} >= ${removed.value}%`, 'info');
        },
        renderTargets() {
            const container = document.getElementById('quenchTargetList');
            if (!container) return;
            
            const targets = this.state.targets;
            
            // 处理空状态
            if (!targets || targets.length === 0) {
                container.innerHTML = '<div class="quench-target-empty">点击"添加目标"设置自动洗炼条件</div>';
                return;
            }
            
            // 渲染目标列表
            container.innerHTML = targets.map((target, index) => `
                <div class="quench-target-row" data-index="${index}">
                    <select class="quench-target-attr" onchange="QuenchModule.updateTargetAttr(${index}, this.value)">
                        ${Object.entries(this.ATTR_MAP).map(([id, name]) => 
                            `<option value="${id}" ${Number(target.attrId) === Number(id) ? 'selected' : ''}>${name}</option>`
                        ).join('')}
                    </select>
                    <span style="font-size: 10px; color: #6b7280;">≥</span>
                    <input type="number" class="quench-target-value" value="${target.value}" min="1" max="100" 
                           onchange="QuenchModule.updateTargetValue(${index}, this.value)">
                    <span style="font-size: 10px; color: #6b7280;">%</span>
                    <button class="quench-target-remove" onclick="QuenchModule.removeTarget(${index})">×</button>
                </div>
            `).join('');
        },
        updateTargetAttr(index, attrId) {
            // 更新目标属性ID
            if (index >= 0 && index < this.state.targets.length) {
                this.state.targets[index].attrId = Number(attrId);
                logMessage(`[洗炼] 更新目标 ${index + 1} 属性: ${this.getAttrName(attrId)}`, 'info');
            }
        },
        updateTargetValue(index, value) {
            // 更新目标数值
            if (index >= 0 && index < this.state.targets.length) {
                const numValue = Math.max(1, Math.min(100, Number(value) || 1));
                this.state.targets[index].value = numValue;
                logMessage(`[洗炼] 更新目标 ${index + 1} 数值: ${numValue}%`, 'info');
            }
        },
        updateButtonStates() {
            const hasHero = this.state.selectedHeroId !== null;
            const hasPart = this.state.selectedPart !== null;
            const isRunning = this.state.isRunning || this.state.isContinuous || this.state.isAuto || this.state.isTimes;
            const canOperate = hasHero && hasPart && !isRunning;

            // 单次洗炼按钮
            const quenchOnceBtn = document.getElementById('quenchOnceBtn');
            if (quenchOnceBtn) quenchOnceBtn.disabled = !canOperate;

            // 连续洗炼按钮
            const quenchContinuousBtn = document.getElementById('quenchContinuousBtn');
            const quenchStopBtn = document.getElementById('quenchStopBtn');
            if (quenchContinuousBtn) {
                quenchContinuousBtn.disabled = !canOperate;
                quenchContinuousBtn.style.display = this.state.isContinuous ? 'none' : '';
            }
            if (quenchStopBtn) {
                quenchStopBtn.style.display = this.state.isContinuous ? '' : 'none';
            }

            // 自动洗炼按钮
            const quenchAutoStartBtn = document.getElementById('quenchAutoStartBtn');
            const quenchAutoStopBtn = document.getElementById('quenchAutoStopBtn');
            if (quenchAutoStartBtn) {
                quenchAutoStartBtn.disabled = !canOperate;
                quenchAutoStartBtn.style.display = this.state.isAuto ? 'none' : '';
            }
            if (quenchAutoStopBtn) {
                quenchAutoStopBtn.style.display = this.state.isAuto ? '' : 'none';
            }

            // 指定次数洗炼按钮
            const quenchTimesStartBtn = document.getElementById('quenchTimesStartBtn');
            const quenchTimesStopBtn = document.getElementById('quenchTimesStopBtn');
            if (quenchTimesStartBtn) {
                quenchTimesStartBtn.disabled = !canOperate;
                quenchTimesStartBtn.style.display = this.state.isTimes ? 'none' : '';
            }
            if (quenchTimesStopBtn) {
                quenchTimesStopBtn.style.display = this.state.isTimes ? '' : 'none';
            }
        },
        updateJadeDisplay() {
            const whiteJadeEl = document.getElementById('quenchWhiteJadeCount');
            const colorJadeEl = document.getElementById('quenchColorJadeCount');
            if (whiteJadeEl) whiteJadeEl.textContent = String(this.state.whiteJadeCount);
            if (colorJadeEl) colorJadeEl.textContent = String(this.state.colorJadeCount);
        },
        async refreshEquipmentData(heroId, part) {
            // 刷新指定英雄指定部位的装备数据
            try {
                const response = await executeGameCommand('role_getroleinfo', {}, '获取角色信息');
                
                // 兼容多种响应格式
                const body = response?._rawData || response?.body || response?.data?.body || response?.data || response || {};
                const role = body?.role || body;
                
                if (!role || !role.heroes) {
                    logMessage('[洗炼] 刷新装备数据失败：无响应数据', 'error');
                    return false;
                }

                const heroes = role.heroes || {};
                const items = role.items || body.items || {};

                // 更新玉石数量
                this.state.whiteJadeCount = items['1022']?.quantity ?? items[1022]?.quantity ?? 0;
                this.state.colorJadeCount = items['1023']?.quantity ?? items[1023]?.quantity ?? 0;
                this.updateJadeDisplay();

                // 更新指定英雄的装备数据
                const heroData = heroes[String(heroId)];
                if (heroData && heroData.equipment) {
                    const equipment = heroData.equipment[String(part)];
                    if (equipment) {
                        // 更新缓存 - 确保heroes对象存在
                        if (!this.state.heroes[heroId]) {
                            // 如果英雄不在缓存中，创建一个基本的英雄对象
                            const heroInfo = this.getHeroInfo(heroId);
                            this.state.heroes[heroId] = {
                                heroId: Number(heroId),
                                name: heroInfo.name,
                                type: heroInfo.type,
                                quality: heroInfo.quality,
                                maxLevel: 0,
                                equipment: {}
                            };
                        }
                        this.state.heroes[heroId].equipment[String(part)] = equipment;

                        // 重新构建槽位数据
                        const quenchTimes = equipment.quenchTimes || 0;
                        const quenches = equipment.quenches || {};
                        
                        // 更新原始quenches数据
                        this.state.rawQuenches = JSON.parse(JSON.stringify(quenches));

                        // 计算解锁槽位数 - 所有部位解锁阈值相同
                        const unlockThresholds = [0, 10, 100, 1000, 10000];
                        let unlockedSlotCount = 0;
                        for (let i = 0; i < unlockThresholds.length; i++) {
                            if (quenchTimes >= unlockThresholds[i]) {
                                unlockedSlotCount = i + 1;
                            } else {
                                break;
                            }
                        }

                        // 构建槽位数据，从服务器数据读取锁定状态
                        const slots = [];
                        const serverLockedSlots = [];
                        for (let slotId = 1; slotId <= unlockedSlotCount; slotId++) {
                            const slotData = quenches[String(slotId)] || quenches[slotId];
                            if (slotData) {
                                const attrIdNum = Number(slotData.attrId) || 0;
                                const attrNumVal = Number(slotData.attrNum) || 0;
                                const colorIdNum = Number(slotData.colorId) || 0;
                                const attrMax = this.getAttrMax(attrIdNum);
                                const realPercent = (attrMax * (attrNumVal / 100)).toFixed(1);
                                // 从服务器数据读取锁定状态
                                const isLocked = Boolean(slotData.isLocked || slotData.locked);
                                if (isLocked) {
                                    serverLockedSlots.push(slotId);
                                }
                                slots.push({
                                    slotId,
                                    attrId: attrIdNum,
                                    attrName: this.getAttrName(attrIdNum),
                                    attrNum: attrNumVal,
                                    attrMax,
                                    realPercent,
                                    colorId: colorIdNum,
                                    colorValue: this.getColorValue(colorIdNum),
                                    isLocked: isLocked
                                });
                            } else {
                                slots.push({
                                    slotId,
                                    attrId: 0,
                                    attrName: '',
                                    attrNum: 0,
                                    attrMax: 0,
                                    realPercent: '0.0',
                                    colorId: 0,
                                    colorValue: '#8e8e93',
                                    isLocked: false
                                });
                            }
                        }

                        this.state.slots = slots;
                        // 同步服务器的锁定状态
                        this.state.lockedSlots = serverLockedSlots;
                        logMessage('[洗炼] 装备数据已刷新', 'info');
                        return true;
                    }
                }
                
                logMessage('[洗炼] 刷新装备数据失败：未找到装备', 'error');
                return false;
            } catch (error) {
                logMessage(`[洗炼] 刷新装备数据失败: ${error.message}`, 'error');
                return false;
            }
        },
        checkTargetReached() {
            // 检查是否有定义目标
            if (!this.state.targets || this.state.targets.length === 0) {
                return false;
            }
            
            // 检查是否有槽位数据
            if (!this.state.slots || this.state.slots.length === 0) {
                return false;
            }
            
            // 检查当前槽位是否满足任一目标条件
            for (const target of this.state.targets) {
                const targetAttrId = Number(target.attrId);
                const targetValue = Number(target.value);
                
                // 跳过无效目标
                if (!targetAttrId || targetValue <= 0) {
                    continue;
                }
                
                // 检查是否有槽位满足该目标
                for (const slot of this.state.slots) {
                    if (Number(slot.attrId) === targetAttrId && Number(slot.attrNum) >= targetValue) {
                        logMessage(`[洗炼] 目标达成: ${this.getAttrName(targetAttrId)} ${slot.attrNum}% >= ${targetValue}%`, 'success');
                        return true;
                    }
                }
            }
            
            return false;
        },
        // 二级密码验证 - 通过 WebSocket 发送 role_commitpassword 命令
        async verifyPassword(password) {
            try {
                const response = await executeGameCommandResult(
                    'role_commitpassword',
                    { password: password, passwordType: 1 },
                    8000
                );
                return { success: response?.code === 0, code: response?.code || -1 };
            } catch (error) {
                console.error('[洗炼] 密码验证异常:', error);
                return { success: false, code: -1 };
            }
        },
        // 二级密码输入弹窗 - 返回 Promise
        showPasswordDialog() {
            return new Promise((resolve) => {
                const overlay = document.createElement('div');
                overlay.style.cssText = `
                    position: fixed; inset: 0;
                    display: flex; align-items: center; justify-content: center;
                    z-index: ${globalConfig.ui.zIndex.modal};
                    pointer-events: auto; padding: 14px;
                    background: rgba(0, 0, 0, 0.3);
                `;

                const panel = document.createElement('div');
                panel.style.cssText = `
                    color: ${globalConfig.ui.colors.text};
                    border-radius: 12px; width: 360px; max-width: 92vw;
                    overflow: hidden; display: flex; flex-direction: column;
                    background: ${globalConfig.ui.colors.panelBg};
                    backdrop-filter: blur(10px);
                    border: 1px solid ${globalConfig.ui.colors.glassBorder};
                    box-shadow: 0 8px 32px rgba(0,0,0,0.1);
                    animation: modalSlideIn 0.25s ease-out;
                `;

                // 标题
                const header = document.createElement('div');
                header.style.cssText = `
                    display: flex; align-items: center; justify-content: center;
                    padding: 10px 14px; font-size: 15px; font-weight: 700;
                    border-bottom: 1px solid ${globalConfig.ui.colors.border};
                    background: rgba(255, 255, 255, 0.7);
                    color: ${globalConfig.ui.colors.dark};
                `;
                header.textContent = '🔒 二级密码验证';

                // 内容区
                const body = document.createElement('div');
                body.style.cssText = 'padding: 16px; display: flex; flex-direction: column; gap: 10px;';

                const hint = document.createElement('div');
                hint.style.cssText = 'font-size: 12px; color: #6b7280; text-align: center;';
                hint.textContent = '槽位解锁操作需要验证二级密码(五分钟内有效)';

                const input = document.createElement('input');
                input.type = 'password';
                input.placeholder = '请输入二级密码';
                input.style.cssText = `
                    width: 100%; padding: 8px 10px; border: 1px solid ${globalConfig.ui.colors.border};
                    border-radius: 8px; font-size: 13px; outline: none; box-sizing: border-box;
                    background: ${globalConfig.ui.colors.itemBg};
                    color: ${globalConfig.ui.colors.text};
                `;

                const errorEl = document.createElement('div');
                errorEl.style.cssText = 'font-size: 11px; color: #ef4444; text-align: center; display: none;';

                body.appendChild(hint);
                body.appendChild(input);
                body.appendChild(errorEl);

                // 按钮区
                const footer = document.createElement('div');
                footer.style.cssText = `
                    display: flex; gap: 10px; padding: 10px 16px;
                    border-top: 1px solid ${globalConfig.ui.colors.border};
                    background: rgba(255, 255, 255, 0.5);
                `;

                const cancelBtn = document.createElement('button');
                cancelBtn.textContent = '取消';
                cancelBtn.style.cssText = `
                    flex: 1; padding: 8px 12px; border: 1px solid ${globalConfig.ui.colors.border};
                    border-radius: 8px; background: ${globalConfig.ui.colors.itemBg};
                    color: ${globalConfig.ui.colors.text}; cursor: pointer; font-size: 12px; font-weight: 500;
                `;

                const confirmBtn = document.createElement('button');
                confirmBtn.textContent = '验证';
                confirmBtn.style.cssText = `
                    flex: 1; padding: 8px 12px; border: 1px solid ${globalConfig.ui.colors.success};
                    border-radius: 8px; color: ${globalConfig.ui.colors.success};
                    background: ${globalConfig.ui.colors.success}15; cursor: pointer;
                    font-size: 12px; font-weight: 600;
                `;

                footer.appendChild(cancelBtn);
                footer.appendChild(confirmBtn);

                panel.appendChild(header);
                panel.appendChild(body);
                panel.appendChild(footer);
                overlay.appendChild(panel);

                const cleanup = () => {
                    document.removeEventListener('keydown', keyHandler);
                    overlay.remove();
                };

                const doConfirm = async () => {
                    const pwd = input.value.trim();
                    if (!pwd) {
                        errorEl.textContent = '请输入密码';
                        errorEl.style.display = 'block';
                        return;
                    }
                    confirmBtn.disabled = true;
                    confirmBtn.textContent = '验证中...';
                    errorEl.style.display = 'none';

                    const result = await this.verifyPassword(pwd);
                    if (result.success) {
                        cleanup();
                        resolve({ confirmed: true, password: pwd });
                    } else {
                        errorEl.textContent = '密码验证失败，请重新输入';
                        errorEl.style.display = 'block';
                        confirmBtn.disabled = false;
                        confirmBtn.textContent = '验证';
                        input.value = '';
                        input.focus();
                    }
                };

                const doCancel = () => {
                    cleanup();
                    resolve({ confirmed: false, password: '' });
                };

                confirmBtn.onclick = doConfirm;
                cancelBtn.onclick = doCancel;
                overlay.addEventListener('click', (e) => { if (e.target === overlay) doCancel(); });

                const keyHandler = (e) => {
                    if (e.key === 'Enter') doConfirm();
                    if (e.key === 'Escape') doCancel();
                };
                document.addEventListener('keydown', keyHandler);

                document.body.appendChild(overlay);
                setTimeout(() => input.focus(), 100);
            });
        },
        // 处理二级密码验证需求
        async handlePasswordRequired() {
            // 1. 尝试使用缓存密码
            if (this.state.passwordValidated && this.state.cachedPassword) {
                const result = await this.verifyPassword(this.state.cachedPassword);
                if (result.success) return;
                // 缓存密码失效，重置
                this.state.passwordValidated = false;
                this.state.cachedPassword = '';
            }
            // 2. 弹出密码输入框
            const dialogResult = await this.showPasswordDialog();
            if (!dialogResult.confirmed) {
                throw new Error('用户取消了密码验证');
            }
            // 3. 更新缓存状态
            this.state.passwordValidated = true;
            this.state.cachedPassword = dialogResult.password;
            logMessage('[洗炼] 二级密码验证成功', 'success');
        }
    };

    window.QuenchModule = QuenchModule;
    if (typeof unsafeWindow !== 'undefined') {
        unsafeWindow.QuenchModule = QuenchModule;
    }

    // ==================== 武将配速模块 ====================

    const HeroSpeedModule = {
        state: {
            selectedId: null,
            running: false,
            shouldStop: false,
            mode: 'level', // 'level' | 'speed'
            selectedCamp: ''
        },

        // 统一日志：同时输出到顶部 Toast 与「执行日志」选项卡
        _log(msg, type = 'info') {
            if (typeof logMessage === 'function') logMessage(`[武将配速] ${msg}`, type);
            if (typeof showTip === 'function') showTip(msg, type);
        },

        // 武将阵营映射
        heroCampMap: {
            '101': '魏国', '102': '魏国', '103': '蜀国', '104': '蜀国', '105': '吴国',
            '106': '吴国', '107': '群雄', '108': '群雄', '109': '魏国', '110': '蜀国',
            '111': '吴国', '112': '群雄', '113': '魏国', '114': '蜀国', '115': '吴国',
            '116': '群雄', '117': '魏国', '118': '蜀国', '119': '吴国', '120': '群雄', '121': '吴国',
            '201': '魏国', '202': '魏国', '203': '魏国', '204': '蜀国', '205': '蜀国',
            '206': '蜀国', '207': '吴国', '208': '吴国', '209': '吴国', '210': '群雄',
            '211': '群雄', '212': '群雄', '213': '魏国', '214': '魏国', '215': '魏国',
            '216': '魏国', '217': '蜀国', '218': '蜀国', '219': '蜀国', '220': '蜀国',
            '221': '吴国', '222': '吴国', '223': '魏国', '224': '吴国', '225': '群雄',
            '226': '群雄', '227': '群雄', '228': '群雄',
            '301': '吴国', '302': '魏国', '303': '魏国', '304': '蜀国', '305': '蜀国',
            '306': '蜀国', '307': '吴国', '308': '吴国', '309': '吴国', '310': '群雄',
            '311': '群雄', '312': '群雄', '313': '蜀国', '314': '蜀国'
        },

        // 进阶等级配置表（升级到第 N order 所需的等级）
        LEVEL_ORDER_MAP: [
            { level: 100, order: 1 }, { level: 200, order: 2 }, { level: 300, order: 3 },
            { level: 500, order: 4 }, { level: 700, order: 5 }, { level: 900, order: 6 },
            { level: 1100, order: 7 }, { level: 1300, order: 8 }, { level: 1500, order: 9 },
            { level: 1800, order: 10 }, { level: 2100, order: 11 }, { level: 2400, order: 12 },
            { level: 2800, order: 13 }, { level: 3200, order: 14 }, { level: 3600, order: 15 },
            { level: 4000, order: 16 }, { level: 4500, order: 17 }, { level: 5000, order: 18 },
            { level: 5500, order: 19 }
        ],

        // 获取武将品质颜色
        getHeroQualityColor(heroId) {
            const id = parseInt(heroId);
            if (id >= 101 && id <= 121) return '#e53e3e'; // 红
            if (id === 215 || id === 227 || id === 228 || (id >= 301 && id <= 312)) return '#9f7aea'; // 紫
            if ((id >= 201 && id <= 214) || (id >= 216 && id <= 226) || id === 313 || id === 314) return '#ed8936'; // 橙
            return 'inherit';
        },

        // 获取武将名
        getHeroName(heroId) {
            try {
                const proxy = window.__xc_heroDataProxy;
                if (proxy && proxy[heroId] && proxy[heroId].name) return proxy[heroId].name;
            } catch (_) {}
            try {
                const w = (typeof unsafeWindow !== 'undefined') ? unsafeWindow : window;
                const hero = w.ROLE && typeof w.ROLE.getHeroById === 'function' && w.ROLE.getHeroById(heroId);
                if (hero && hero.realSkinName) return hero.realSkinName;
            } catch (_) {}
            return `武将${heroId}`;
        },

        // 通过 ROLE 接口获取已拥有武将
        getOwnedHero(heroId) {
            try {
                const w = (typeof unsafeWindow !== 'undefined') ? unsafeWindow : window;
                if (!w.ROLE) return null;
                if (typeof w.ROLE.getHeroById === 'function') {
                    return w.ROLE.getHeroById(heroId) || null;
                }
                if (w.ROLE.heroes) {
                    if (typeof w.ROLE.heroes.get === 'function') return w.ROLE.heroes.get(heroId) || null;
                    return w.ROLE.heroes[heroId] || w.ROLE.heroes[String(heroId)] || null;
                }
            } catch (_) {}
            return null;
        },

        // 列出所有已拥有武将
        listOwnedHeroes(filterCamp) {
            const result = [];
            const ALL_IDS = [
                ...Array.from({ length: 21 }, (_, i) => 101 + i),
                ...Array.from({ length: 28 }, (_, i) => 201 + i),
                ...Array.from({ length: 14 }, (_, i) => 301 + i)
            ];
            for (const heroId of ALL_IDS) {
                const hero = this.getOwnedHero(heroId);
                if (!hero || !hero.level) continue;
                const camp = this.heroCampMap[heroId] || '';
                if (filterCamp && camp !== filterCamp) continue;
                result.push({
                    heroId,
                    name: this.getHeroName(heroId),
                    level: hero.level,
                    speed: hero.speed || 0,
                    camp
                });
            }
            const getQualityOrder = (id) => {
                const n = parseInt(id);
                if (n >= 101 && n <= 121) return 1;
                if ((n >= 201 && n <= 214) || (n >= 216 && n <= 226) || n === 313 || n === 314) return 2;
                return 3;
            };
            result.sort((a, b) => {
                const oa = getQualityOrder(a.heroId);
                const ob = getQualityOrder(b.heroId);
                if (oa !== ob) return oa - ob;
                return b.level - a.level;
            });
            return result;
        },

        init() {
            const dropdownEl = document.getElementById('heroSpeedDropdown');
            const optionsEl = document.getElementById('heroSpeedOptions');
            const campBtns = document.getElementById('heroSpeedCampBtns');
            const modeLevel = document.getElementById('heroSpeedModeLevel');
            const modeSpeed = document.getElementById('heroSpeedModeSpeed');
            const autoBtn = document.getElementById('heroSpeedAutoBtn');
            const stopBtn = document.getElementById('heroSpeedStopBtn');
            const rebirthBtn = document.getElementById('heroSpeedRebirthBtn');

            // 自定义下拉框展开/收起
            if (dropdownEl && optionsEl) {
                if (optionsEl.parentNode !== document.body) {
                    document.body.appendChild(optionsEl);
                }
                const selectedEl = dropdownEl.querySelector('.dropdown-selected');
                if (selectedEl && !selectedEl._heroSpeedBound) {
                    selectedEl._heroSpeedBound = true;
                    selectedEl.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const isOpen = optionsEl.style.display === 'block';
                        if (!isOpen) {
                            const rect = selectedEl.getBoundingClientRect();
                            optionsEl.style.top = (rect.bottom + 2) + 'px';
                            optionsEl.style.left = rect.left + 'px';
                            optionsEl.style.width = rect.width + 'px';
                        }
                        optionsEl.style.display = isOpen ? 'none' : 'block';
                    });
                    document.addEventListener('click', () => {
                        optionsEl.style.display = 'none';
                    });
                }
            }
            if (campBtns) {
                campBtns.querySelectorAll('.hero-speed-camp-btn').forEach(btn => {
                    btn.addEventListener('click', () => {
                        campBtns.querySelectorAll('.hero-speed-camp-btn').forEach(b => {
                            b.classList.remove('active');
                            b.style.borderColor = 'transparent';
                        });
                        btn.classList.add('active');
                        btn.style.borderColor = 'var(--highlight)';
                        this.state.selectedCamp = btn.dataset.camp || '';
                        this.refreshHeroList();
                    });
                });
            }
            if (modeLevel) modeLevel.addEventListener('click', () => this.switchMode('level'));
            if (modeSpeed) modeSpeed.addEventListener('click', () => this.switchMode('speed'));
            if (autoBtn) autoBtn.addEventListener('click', () => this.startAutoUpgrade());
            if (stopBtn) stopBtn.addEventListener('click', () => this.stopUpgrade());
            if (rebirthBtn) rebirthBtn.addEventListener('click', () => this.doRebirth());
        },

        refreshHeroList() {
            const optionsEl = document.getElementById('heroSpeedOptions');
            const selectedTextEl = document.getElementById('heroSpeedSelectedText');
            const tip = document.getElementById('heroSpeedTip');
            if (!optionsEl) return;
            const heroes = this.listOwnedHeroes(this.state.selectedCamp);
            if (heroes.length === 0) {
                optionsEl.innerHTML = '<div class="hero-speed-dropdown-option" data-value="" style="padding:6px 10px;font-size:12px;cursor:pointer;color:#999;">-- 暂无可用武将 --</div>';
                if (tip) tip.textContent = '⚠️ 未获取到武将数据，请确认游戏已加载并重试';
                return;
            }
            // 生成选项
            optionsEl.innerHTML = '<div class="hero-speed-dropdown-option" data-value="" style="padding:6px 10px;font-size:12px;cursor:pointer;">-- 请选择武将 --</div>' +
                heroes.map(h => {
                    const color = this.getHeroQualityColor(h.heroId);
                    return `<div class="hero-speed-dropdown-option" data-value="${h.heroId}" style="padding:6px 10px;font-size:12px;cursor:pointer;color:${color};">${h.name} (${h.level}/6000)</div>`;
                }).join('');
            // 绑定选项点击
            optionsEl.querySelectorAll('.hero-speed-dropdown-option').forEach(opt => {
                opt.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const value = opt.dataset.value;
                    const text = opt.textContent;
                    const color = opt.style.color || 'inherit';
                    if (selectedTextEl) {
                        selectedTextEl.textContent = text;
                        selectedTextEl.style.color = color;
                    }
                    optionsEl.style.display = 'none';
                    optionsEl.querySelectorAll('.hero-speed-dropdown-option').forEach(o => o.classList.remove('selected'));
                    opt.classList.add('selected');
                    this.selectHero(value ? parseInt(value) : null);
                });
            });
            if (tip) tip.textContent = `已加载 ${heroes.length} 个武将，请选择后开始升级`;
            this._log(`已加载 ${heroes.length} 个武将`, 'success');
        },

        selectHero(heroId) {
            const lvEl = document.getElementById('heroSpeedLevel');
            const atEl = document.getElementById('heroSpeedAttack');
            const spEl = document.getElementById('heroSpeedSpeedVal');
            if (!heroId) {
                this.state.selectedId = null;
                if (lvEl) lvEl.textContent = '-';
                if (atEl) atEl.textContent = '-';
                if (spEl) spEl.textContent = '-';
                return;
            }
            this.state.selectedId = heroId;
            const hero = this.getOwnedHero(heroId);
            if (!hero) {
                this._log('未找到武将数据', 'warning');
                return;
            }
            this.updateDisplay(heroId, hero);
        },

        updateDisplay(heroId, hero) {
            const lvEl = document.getElementById('heroSpeedLevel');
            const atEl = document.getElementById('heroSpeedAttack');
            const spEl = document.getElementById('heroSpeedSpeedVal');
            if (lvEl) lvEl.textContent = `${hero.level || 0}/6000`;
            if (atEl) atEl.textContent = hero.attack || 0;
            if (spEl) spEl.textContent = hero.speed || 0;
            this.updateOrderTip(hero);
        },

        updateOrderTip(hero) {
            const tip = document.getElementById('heroSpeedTip');
            if (!tip || !hero) return;
            const level = hero.level || 0;
            const order = hero.order || 0;
            if (level >= 6000) {
                tip.textContent = '武将已满级';
                tip.style.color = '#16a34a';
                return;
            }
            const canOrder = this.canOrderUpgrade(level, order);
            if (canOrder) {
                tip.textContent = `已达到进阶条件，当前 ${level} 级可进阶`;
                tip.style.color = '#f59e0b';
            } else {
                const next = this.LEVEL_ORDER_MAP.find(it => it.order > order);
                tip.textContent = next ? `下一进阶等级: ${next.level} 级` : '已达到最高进阶';
                tip.style.color = 'var(--text-secondary)';
            }
        },

        judgeLevelUpgrade(level, upgradeNum, order) {
            for (const item of this.LEVEL_ORDER_MAP) {
                if (order !== item.order && level <= item.level && item.level < (level + upgradeNum)) {
                    return item.level;
                }
            }
            return false;
        },

        canOrderUpgrade(level, order) {
            return this.judgeLevelUpgrade(level, 1, order) === level;
        },

        switchMode(mode) {
            this.state.mode = mode;
            const target = document.getElementById('heroSpeedTarget');
            const lvBtn = document.getElementById('heroSpeedModeLevel');
            const spBtn = document.getElementById('heroSpeedModeSpeed');
            const isLv = mode === 'level';
            if (target) {
                target.placeholder = isLv ? '请输入目标等级' : '请输入目标速度';
                target.value = '';
                if (isLv) target.max = '6000'; else target.removeAttribute('max');
            }
            if (lvBtn) {
                lvBtn.classList.toggle('btn-primary-glass', isLv);
                lvBtn.classList.toggle('active', isLv);
            }
            if (spBtn) {
                spBtn.classList.toggle('btn-primary-glass', !isLv);
                spBtn.classList.toggle('active', !isLv);
            }
        },

        updateRunningUI(running) {
            const autoBtn = document.getElementById('heroSpeedAutoBtn');
            const stopBtn = document.getElementById('heroSpeedStopBtn');
            const rebirthBtn = document.getElementById('heroSpeedRebirthBtn');
            if (autoBtn) autoBtn.style.display = running ? 'none' : 'flex';
            if (stopBtn) stopBtn.style.display = running ? 'flex' : 'none';
            if (rebirthBtn) rebirthBtn.disabled = running;
        },

        async sendCmd(cmd, params) {
            // 与星驰统一调用：executeGameCommandResult(cmd, params, timeout)
            if (typeof executeGameCommandResult !== 'function') {
                throw new Error('executeGameCommandResult 不可用');
            }
            const resp = await executeGameCommandResult(cmd, params || {}, 8000);
            return resp;
        },

        // 检查响应是否成功（星驰约定 code===0 成功）
        isOk(resp) {
            return resp && (resp.code === 0 || resp.code === undefined && !resp.error && !resp.errCode);
        },

        getErrMsg(resp) {
            if (!resp) return '无响应';
            return resp.msg || resp.errMsg || resp.error || resp.message || `code=${resp.code}`;
        },

        async startAutoUpgrade() {
            if (this.state.mode === 'speed') {
                await this.autoUpgradeToSpeed();
            } else {
                await this.autoUpgradeToLevel();
            }
        },

        stopUpgrade() {
            this.state.shouldStop = true;
            this._log('正在停止升级...', 'info');
        },

        async autoUpgradeToLevel() {
            const heroId = this.state.selectedId;
            const targetEl = document.getElementById('heroSpeedTarget');
            const targetLevel = parseInt(targetEl?.value, 10);
            if (!heroId) { this._log('请先选择武将', 'warning'); return; }
            const hero0 = this.getOwnedHero(heroId);
            if (!hero0) { this._log('未找到武将数据', 'warning'); return; }
            const curLevel0 = hero0.level || 0;
            if (!targetLevel || isNaN(targetLevel)) { this._log('请输入目标等级', 'warning'); return; }
            if (targetLevel <= curLevel0) { this._log(`目标等级(${targetLevel})必须大于当前(${curLevel0})`, 'warning'); return; }
            if (targetLevel > 6000) { this._log('目标等级不能超过 6000', 'warning'); return; }

            this.state.running = true;
            this.state.shouldStop = false;
            this.updateRunningUI(true);
            try {
                let curLv = curLevel0;
                let curOrd = hero0.order || 0;
                const STD_LEVELS = [1, 5, 10, 50];
                let totalUp = 0;
                while (curLv < targetLevel && !this.state.shouldStop) {
                    if (this.canOrderUpgrade(curLv, curOrd)) {
                        const r = await this.sendCmd('hero_heroupgradeorder', { heroId });
                        if (!this.isOk(r)) throw new Error(`进阶失败: ${this.getErrMsg(r)}`);
                        const h = this.getOwnedHero(heroId);
                        if (h) {
                            const prevLv = curLv, prevOrd = curOrd;
                            curLv = (h.level > 0 && h.level >= prevLv) ? h.level : prevLv;
                            if ((h.order || 0) > prevOrd) curOrd = h.order;
                            else throw new Error('进阶未生效，可能资源不足');
                            this.updateDisplay(heroId, h);
                        }
                        await new Promise(r => setTimeout(r, 0));
                        continue;
                    }
                    const remaining = targetLevel - curLv;
                    let useLevel = 1;
                    for (const s of STD_LEVELS.slice().reverse()) {
                        if (s <= remaining && this.judgeLevelUpgrade(curLv, s, curOrd) === false) {
                            useLevel = s; break;
                        }
                    }
                    const r = await this.sendCmd('hero_heroupgradelevel', { heroId, upgradeNum: useLevel });
                    if (!this.isOk(r)) throw new Error(`升级失败: ${this.getErrMsg(r)}`);
                    const h = this.getOwnedHero(heroId);
                    if (h) {
                        const prevLv = curLv;
                        curLv = (h.level > 0 && h.level >= prevLv) ? h.level : prevLv;
                        if ((h.order || 0) > 0) curOrd = h.order;
                        totalUp += (curLv - prevLv);
                        this.updateDisplay(heroId, h);
                        if (curLv === prevLv) throw new Error('升级未生效，可能金币不足');
                    }
                    await new Promise(r => setTimeout(r, 0));
                }
                this._log(this.state.shouldStop ? '升级已停止' : `升级完成！共升 ${totalUp} 级`, this.state.shouldStop ? 'info' : 'success');
            } catch (e) {
                this._log(`升级失败: ${e.message}`, 'error');
            } finally {
                this.state.running = false;
                this.state.shouldStop = false;
                this.updateRunningUI(false);
            }
        },

        async autoUpgradeToSpeed() {
            const heroId = this.state.selectedId;
            const targetEl = document.getElementById('heroSpeedTarget');
            const targetSpeed = parseInt(targetEl?.value, 10);
            if (!heroId) { this._log('请先选择武将', 'warning'); return; }
            const hero0 = this.getOwnedHero(heroId);
            if (!hero0) { this._log('未找到武将数据', 'warning'); return; }
            const curSpeed0 = hero0.speed || 0;
            if (!targetSpeed || targetSpeed <= curSpeed0) { this._log('目标速度必须大于当前速度', 'warning'); return; }
            if ((hero0.level || 0) >= 6000) { this._log('武将已满级', 'warning'); return; }

            this.state.running = true;
            this.state.shouldStop = false;
            this.updateRunningUI(true);
            const SAFETY = 1.3, STEPS = [50, 10, 5, 1], MAX_HIST = 20;
            let history = [], avgPerLv = 0, firstUp = true;
            try {
                let curSpd = curSpeed0;
                let curLv = hero0.level || 0;
                let curOrd = hero0.order || 0;
                while (curSpd < targetSpeed && curLv < 6000 && !this.state.shouldStop) {
                    if (this.canOrderUpgrade(curLv, curOrd)) {
                        const r = await this.sendCmd('hero_heroupgradeorder', { heroId });
                        if (!this.isOk(r)) throw new Error(`进阶失败: ${this.getErrMsg(r)}`);
                        const h = this.getOwnedHero(heroId);
                        if (h) {
                            const prevSpd = curSpd, prevLv = curLv, prevOrd = curOrd;
                            if ((h.level || 0) > 0 && h.level >= prevLv) curLv = h.level;
                            if ((h.speed || 0) > 0 && h.speed >= prevSpd) {
                                curSpd = h.speed;
                                if (curSpd > prevSpd) {
                                    history.push({ levels: 0, gain: curSpd - prevSpd, isOrder: true });
                                    if (history.length > MAX_HIST) history = history.slice(-MAX_HIST);
                                }
                            }
                            if ((h.order || 0) > prevOrd) curOrd = h.order;
                            else throw new Error('进阶未生效');
                            this.updateDisplay(heroId, h);
                        }
                        await new Promise(r => setTimeout(r, 0));
                        continue;
                    }
                    const remain = targetSpeed - curSpd;
                    let step = 1;
                    if (firstUp) {
                        step = 1;
                    } else if (avgPerLv > 0) {
                        for (const s of STEPS) {
                            const est = s * avgPerLv * SAFETY;
                            const cross = this.judgeLevelUpgrade(curLv, s, curOrd) !== false;
                            if (est <= remain && !cross) { step = s; break; }
                        }
                    } else {
                        for (const s of [10, 5, 1]) {
                            const cross = this.judgeLevelUpgrade(curLv, s, curOrd) !== false;
                            if (!cross) {
                                if (s === 10 && remain > 500) { step = 10; break; }
                                if (s === 5 && remain > 100) { step = 5; break; }
                                if (s === 1) { step = 1; break; }
                            }
                        }
                    }
                    const prevSpd = curSpd;
                    const r = await this.sendCmd('hero_heroupgradelevel', { heroId, upgradeNum: step });
                    if (!this.isOk(r)) throw new Error(`升级失败: ${this.getErrMsg(r)}`);
                    const h = this.getOwnedHero(heroId);
                    if (h) {
                        const prevLv = curLv;
                        if ((h.level || 0) > 0 && h.level >= prevLv) curLv = h.level;
                        if ((h.order || 0) > 0) curOrd = h.order;
                        firstUp = false;
                        if ((h.speed || 0) > 0 && h.speed >= prevSpd) {
                            const gain = h.speed - prevSpd;
                            curSpd = h.speed;
                            if (gain > 0 && step > 0) {
                                history.push({ levels: step, gain });
                                if (history.length > MAX_HIST) history = history.slice(-MAX_HIST);
                                const lvRecs = history.filter(x => !x.isOrder && x.levels > 0);
                                if (lvRecs.length > 0) {
                                    avgPerLv = lvRecs.reduce((sum, x) => sum + x.gain / x.levels, 0) / lvRecs.length;
                                }
                            }
                        }
                        this.updateDisplay(heroId, h);
                    }
                    await new Promise(r => setTimeout(r, 0));
                }
                const finalMsg = curSpd >= targetSpeed
                    ? `达到目标速度 ${curSpd}，等级 ${curLv}`
                    : `已满级 ${curLv}，速度 ${curSpd}`;
                this._log(this.state.shouldStop ? '升级已停止' : finalMsg, this.state.shouldStop ? 'info' : 'success');
            } catch (e) {
                this._log(`升级失败: ${e.message}`, 'error');
            } finally {
                this.state.running = false;
                this.state.shouldStop = false;
                this.updateRunningUI(false);
            }
        },

        async doRebirth() {
            const heroId = this.state.selectedId;
            if (!heroId) { this._log('请先选择武将', 'warning'); return; }
            const hero = this.getOwnedHero(heroId);
            if (!hero) { this._log('未找到武将数据', 'warning'); return; }
            if ((hero.level || 0) <= 1) { this._log('武将已是 1 级，无需重生', 'info'); return; }
            try {
                const r = await this.sendCmd('hero_rebirth', { heroId });
                if (!this.isOk(r)) { this._log(`重生失败: ${this.getErrMsg(r)}`, 'error'); return; }
                await new Promise(r => setTimeout(r, 1000));
                const h = this.getOwnedHero(heroId);
                if (h) this.updateDisplay(heroId, h);
                this.refreshHeroList();
                await new Promise(r => setTimeout(r, 100));
                // 刷新后重新选中该武将（同步下拉框显示）
                const optionsEl = document.getElementById('heroSpeedOptions');
                const selectedTextEl = document.getElementById('heroSpeedSelectedText');
                if (optionsEl && selectedTextEl) {
                    const targetValue = String(heroId);
                    const target = optionsEl.querySelector(`.hero-speed-dropdown-option[data-value="${targetValue}"]`);
                    if (target) {
                        selectedTextEl.textContent = target.textContent;
                        selectedTextEl.style.color = target.style.color || 'inherit';
                        optionsEl.querySelectorAll('.hero-speed-dropdown-option').forEach(o => o.classList.remove('selected'));
                        target.classList.add('selected');
                    }
                }
                this._log(`${this.getHeroName(heroId)} 已重生到 1 级`, 'success');
            } catch (e) {
                this._log(`重生失败: ${e.message}`, 'error');
            }
        }
    };

    window.HeroSpeedModule = HeroSpeedModule;
    if (typeof unsafeWindow !== 'undefined') {
        unsafeWindow.HeroSpeedModule = HeroSpeedModule;
    }

