        // 获取怪异爬塔信息
        async function getWeirdTowerInfo() {
            try {
                const response = await executeGameCommand('evotower_getinfo', {}, '获取怪异爬塔信息');
                if (!response || !response._rawData || !response._rawData.evoTower) {
                    logWeirdTowerMessage('获取爬塔信息失败', 'error');
                    return null;
                }

                const evoTower = response._rawData.evoTower;
                const energy = evoTower.energy;
                const rawTowerId = evoTower.towerId;
                const displayFloor = formatTowerFloor(rawTowerId);

                const towerInfo = {
                    energy: energy,
                    rawTowerId: rawTowerId,
                    displayFloor: displayFloor
                };

                weirdTowerTaskState.towerInfo = towerInfo;
                updateWeirdTowerUI();

                logWeirdTowerMessage(`小鱼干=${energy}, 当前层数=${displayFloor}`, 'info');
                return towerInfo;
            } catch (error) {
                logWeirdTowerMessage(`获取爬塔信息异常: ${error.message}`, 'error');
                return null;
            }
        }

        // 切换怪异爬塔阵容 - 调用全局阵容切换函数
        async function switchWeirdTowerTeam(teamId) {
            logWeirdTowerMessage(`切换到阵容${teamId}...`, 'info');
            const result = await switchToFormationIfNeeded(teamId, '怪异爬塔阵容');
            if (result) {
                logWeirdTowerMessage(`成功切换到阵容${teamId}`, 'success');
            } else {
                logWeirdTowerMessage(`切换阵容${teamId}失败`, 'error');
            }
            return result;
        }

        // 购买怪异爬塔小鱼干
        async function buyWeirdTowerEnergyAction() {
            try {
                const amountInput = document.getElementById('weirdTowerBuyAmount');
                const amount = parseInt(amountInput?.value) || 1;

                if (amount <= 0) {
                    showTip('请输入有效的购买数量', 'warning');
                    return;
                }

                logWeirdTowerMessage(`正在购买 ${amount} 个小鱼干...`, 'info');

                const response = await executeGameCommand('evotower_buyenergy', { energy: amount }, '购买小鱼干');

                if (response && response._rawData && response._rawData.evoTower) {
                    const newEnergy = response._rawData.evoTower.energy;
                    weirdTowerTaskState.towerInfo.energy = newEnergy;
                    updateWeirdTowerUI();
                    logWeirdTowerMessage(`成功购买 ${amount} 个小鱼干，当前小鱼干: ${newEnergy}`, 'success');
                    showTip(`成功购买 ${amount} 个小鱼干`, 'success');
                } else {
                    logWeirdTowerMessage('购买小鱼干失败', 'error');
                    showTip('购买小鱼干失败', 'error');
                }
            } catch (error) {
                logWeirdTowerMessage(`购买小鱼干异常: ${error.message}`, 'error');
                showTip('购买小鱼干失败', 'error');
            }
        }

        // ===== 合成助手功能 =====
        // 合成盒子状态
        let mergeboxState = {
            freeEnergy: 0,
            gridMap: null,
            mergeableItems: [],
            openableBoxes: [],  // 可开箱的位置
            keyCount: 0,        // 当前钥匙数量
            costTotalCnt: 0,    // 总消耗次数
            costClaimCnt: 0,    // 已领取的消耗奖励次数
            taskMap: {},        // 合成任务进度 {taskId: progress}
            taskClaimMap: {},   // 已领取的任务 {taskId: timestamp}
            actType: 1,
            isRunning: false,
            claimSynthRunning: false  // 一键领取合成运行标记
        };

        // 同步钥匙剩余数（lotteryLeftCnt 来自 evotower_getinfo）
        async function syncMergeboxKeyCount() {
            try {
                const resp = await executeGameCommand('evotower_getinfo', {}, '同步钥匙数');
                const evo = resp?._rawData?.evoTower;
                if (evo && evo.lotteryLeftCnt != null) {
                    mergeboxState.keyCount = Number(evo.lotteryLeftCnt) || 0;
                    const el = document.getElementById('mergeboxKeyCount');
                    if (el) {
                        el.textContent = `${mergeboxState.keyCount}个`;
                        el.className = `mergebox-status-value ${mergeboxState.keyCount > 0 ? 'available' : 'unavailable'}`;
                    }
                }
                return mergeboxState.keyCount;
            } catch (_) {
                return mergeboxState.keyCount;
            }
        }

        // 获取合成盒子信息
        async function getMergeboxInfo() {
            try {
                const response = await executeGameCommand('mergebox_getinfo', { actType: 1 }, '获取合成盒子信息');
                if (!response || !response._rawData || !response._rawData.mergeBox) {
                    logWeirdTowerMessage('获取合成盒子信息失败', 'error');
                    return null;
                }

                const mergeBox = response._rawData.mergeBox;
                mergeboxState.freeEnergy = mergeBox.freeEnergy || 0;
                mergeboxState.gridMap = mergeBox.gridMap || {};
                mergeboxState.costTotalCnt = mergeBox.costTotalCnt || 0;
                mergeboxState.costClaimCnt = mergeBox.costClaimCnt || 0;
                mergeboxState.taskMap = mergeBox.taskMap || {};
                mergeboxState.taskClaimMap = mergeBox.taskClaimMap || {};


                // 分析可合成物品和可开箱位置
                const analysis = analyzeGridMap(mergeBox.gridMap);
                mergeboxState.mergeableItems = analysis.mergeable;
                mergeboxState.openableBoxes = analysis.openable;

                // 更新UI
                updateMergeboxUI();

                // 同步钥匙剩余数
                await syncMergeboxKeyCount();

                const pendingCostReward = mergeboxState.costTotalCnt - mergeboxState.costClaimCnt;
                logWeirdTowerMessage(`合成盒子: 免费钥匙=${mergeboxState.freeEnergy}, 剩余钥匙=${mergeboxState.keyCount}, 可开箱=${mergeboxState.openableBoxes.length}, 可合成=${mergeboxState.mergeableItems.length}对, 待领消耗奖励=${pendingCostReward}`, 'info');
                return mergeBox;
            } catch (error) {
                logWeirdTowerMessage(`获取合成盒子信息异常: ${error.message}`, 'error');
                return null;
            }
        }

        // 分析格子地图（合并分析可合成物品和可开箱位置）
        function analyzeGridMap(gridMap) {
            const itemPositions = {}; // { 物品类型Key: [{x, y, data}, ...] }
            const openable = [];      // 可开箱的位置

            if (!gridMap) {
                logWeirdTowerMessage('格子地图为空', 'warning');
                return { mergeable: [], openable: [] };
            }

            // 遍历所有格子（只处理数字键）
            for (const rowKey of Object.keys(gridMap)) {
                if (!/^\d+$/.test(rowKey)) continue;

                const row = gridMap[rowKey];
                if (typeof row !== 'object' || row === null) continue;

                for (const colKey of Object.keys(row)) {
                    if (!/^\d+$/.test(colKey)) continue;

                    const cell = row[colKey];
                    if (!cell || typeof cell !== 'object') continue;

                    const x = parseInt(rowKey);
                    const y = parseInt(colKey);

                    // 提取格子属性
                    const gridType = parseInt(cell.gridType) || 0;
                    const gridItemId = parseInt(cell.gridItemId) || 0;
                    const isLock = cell.isLock;

                    // 可开箱判断：只要openCnt > 0就是可开箱
                    // openCnt可能是数字、字符串或undefined
                    const openCnt = cell.openCnt !== undefined ? parseInt(cell.openCnt) : 0;
                    if (openCnt > 0) {
                        openable.push({ x, y, openCnt: openCnt });
                        logWeirdTowerMessage(`可开箱位置: (${x},${y})`, 'info');
                    }

                    // 检查是否是有效的可合成物品
                    const itemLevel = gridItemId;
                    const itemType = gridType;
                    const isUnlocked = isLock === false;

                    // 只有未锁定的物品才能合成，且排除特殊物品（等级 >= 100）
                    if (itemLevel > 0 && itemLevel < 100 && isUnlocked && itemType > 0) {
                        const itemKey = `${itemType}_${itemLevel}`;
                        if (!itemPositions[itemKey]) {
                            itemPositions[itemKey] = [];
                        }
                        itemPositions[itemKey].push({ x, y, itemType, itemLevel, data: cell });
                    }
                }
            }

            // 找出可合成的物品对
            const mergeable = [];
            for (const itemKey of Object.keys(itemPositions)) {
                const positions = itemPositions[itemKey];
                if (positions.length >= 2) {
                    for (let i = 0; i + 1 < positions.length; i += 2) {
                        mergeable.push({
                            source: positions[i],
                            target: positions[i + 1],
                            itemKey: itemKey,
                            level: positions[i].itemLevel
                        });
                    }
                }
            }
            return { mergeable, openable };
        }

        // 更新合成助手 UI
        function updateMergeboxUI() {
            const freeEnergyEl = document.getElementById('mergeboxFreeEnergy');
            const openableCountEl = document.getElementById('mergeboxOpenableCount');
            const mergeableCountEl = document.getElementById('mergeboxMergeableCount');

            if (freeEnergyEl) {
                freeEnergyEl.textContent = mergeboxState.freeEnergy > 0 ? `${mergeboxState.freeEnergy}个` : '无';
                freeEnergyEl.className = `mergebox-status-value ${mergeboxState.freeEnergy > 0 ? 'available' : 'unavailable'}`;
            }

            if (openableCountEl) {
                const openCount = mergeboxState.openableBoxes.length;
                openableCountEl.textContent = openCount > 0 ? `${openCount}个` : '无';
                openableCountEl.className = `mergebox-status-value ${openCount > 0 ? 'available' : 'unavailable'}`;
            }

            if (mergeableCountEl) {
                const count = mergeboxState.mergeableItems.length;
                mergeableCountEl.textContent = count > 0 ? `${count}对` : '无';
                mergeableCountEl.className = `mergebox-status-value ${count > 0 ? 'available' : 'unavailable'}`;
            }
        }

        // 领取免费钥匙
        async function claimFreeKey() {
            try {
                if (mergeboxState.freeEnergy <= 0) {
                    showTip('没有免费钥匙可领取', 'warning');
                    return false;
                }

                logWeirdTowerMessage('正在领取免费钥匙...', 'info');

                const response = await executeGameCommand('mergebox_claimfreeenergy', { actType: 1 }, '领取免费钥匙');

                if (response && response._rawData) {
                    const reward = response._rawData.reward;
                    if (reward && reward.length > 0) {
                        const rewardInfo = reward.map(r => `${r.value}个`).join(', ');
                        logWeirdTowerMessage(`成功领取免费钥匙: ${rewardInfo}`, 'success');
                        showTip('成功领取免费钥匙', 'success');
                    } else {
                        logWeirdTowerMessage('成功领取免费钥匙', 'success');
                        showTip('成功领取免费钥匙', 'success');
                    }

                    // 更新状态
                    mergeboxState.freeEnergy = 0;
                    updateMergeboxUI();
                    return true;
                } else {
                    logWeirdTowerMessage('领取免费钥匙失败', 'error');
                    showTip('领取失败', 'error');
                    return false;
                }
            } catch (error) {
                logWeirdTowerMessage(`领取免费钥匙异常: ${error.message}`, 'error');
                showTip('领取失败', 'error');
                return false;
            }
        }

        // 开箱子
        async function openMergeBox(x, y) {
            try {
                const response = await executeGameCommand('mergebox_openbox', {
                    pos: { gridX: x, gridY: y },
                    actType: 1
                }, '开箱子');

                if (response && response._rawData) {
                    logWeirdTowerMessage(`开箱成功 (${x},${y})`, 'success');
                    return true;
                } else {
                    logWeirdTowerMessage(`开箱失败 (${x},${y})`, 'warning');
                    return false;
                }
            } catch (error) {
                logWeirdTowerMessage(`开箱异常: ${error.message}`, 'error');
                return false;
            }
        }

        // 领取消耗钥匙奖励
        async function claimCostReward() {
            try {
                const pendingReward = mergeboxState.costTotalCnt - mergeboxState.costClaimCnt;
                if (pendingReward <= 0) {
                    return 0;
                }

                logWeirdTowerMessage(`检测到${pendingReward}个待领取的消耗奖励，开始领取...`, 'info');

                let claimedCount = 0;

                // 循环领取所有待领奖励
                while (claimedCount < pendingReward) {
                    try {
                        const response = await executeGameCommand('mergebox_claimcostprogress', {
                            actType: 1
                        }, '领取消耗奖励');

                        if (response && response._rawData) {
                            const reward = response._rawData.reward;
                            const newClaimCnt = response._rawData.mergeBox?.costClaimCnt;

                            if (reward && reward.length > 0) {
                                const rewardValue = reward[0].value || 1;
                                claimedCount += rewardValue;
                                logWeirdTowerMessage(`领取消耗奖励成功: +${rewardValue}个钥匙`, 'success');
                            } else {
                                claimedCount++;
                                logWeirdTowerMessage(`领取消耗奖励成功`, 'success');
                            }

                            // 更新本地状态
                            if (newClaimCnt !== undefined) {
                                mergeboxState.costClaimCnt = newClaimCnt;
                            }
                        } else {
                            logWeirdTowerMessage(`领取消耗奖励失败，停止领取`, 'warning');
                            break;
                        }

                        await new Promise(resolve => setTimeout(resolve, 200));

                        // 检查是否还有待领取
                        if (mergeboxState.costClaimCnt >= mergeboxState.costTotalCnt) {
                            break;
                        }
                    } catch (err) {
                        logWeirdTowerMessage(`领取消耗奖励异常: ${err.message}`, 'error');
                        break;
                    }
                }

                if (claimedCount > 0) {
                    showTip(`成功领取${claimedCount}个消耗奖励`, 'success');
                }

                return claimedCount;
            } catch (error) {
                logWeirdTowerMessage(`领取消耗奖励异常: ${error.message}`, 'error');
                return 0;
            }
        }

        // 领取合成进度奖励（合成物品达到对应等级的奖励）
        async function claimMergeProgressReward() {
            try {
                const taskMap = mergeboxState.taskMap;
                const taskClaimMap = mergeboxState.taskClaimMap;

                if (!taskMap || Object.keys(taskMap).length === 0) {
                    return 0;
                }

                // 找出可领取的任务（进度>0且未领取）
                const claimableTasks = [];
                for (const taskId of Object.keys(taskMap)) {
                    // 跳过非数字键
                    if (!/^\d+$/.test(taskId)) continue;

                    const progress = taskMap[taskId];
                    const claimed = taskClaimMap[taskId];

                    // 进度>0且未领取
                    if (progress > 0 && !claimed) {
                        claimableTasks.push(taskId);
                    }
                }

                if (claimableTasks.length === 0) {
                    return 0;
                }

                logWeirdTowerMessage(`检测到${claimableTasks.length}个合成进度奖励可领取...`, 'info');

                let claimedCount = 0;

                for (const taskId of claimableTasks) {
                    try {
                        const response = await executeGameCommand('mergebox_claimmergeprogress', {
                            actType: 1,
                            taskId: taskId
                        }, '领取合成进度奖励');

                        if (response && response._rawData) {
                            claimedCount++;
                            const reward = response._rawData.reward;
                            if (reward && reward.length > 0) {
                                const rewardInfo = reward.map(r => `${r.value}个`).join(', ');
                                logWeirdTowerMessage(`领取合成进度奖励成功: ${rewardInfo}`, 'success');
                            } else {
                                logWeirdTowerMessage(`领取合成进度奖励成功`, 'success');
                            }
                        } else {
                            logWeirdTowerMessage(`领取合成进度奖励失败: taskId=${taskId}`, 'warning');
                        }

                        await new Promise(resolve => setTimeout(resolve, 200));
                    } catch (err) {
                        logWeirdTowerMessage(`领取合成进度奖励异常: ${err.message}`, 'error');
                    }
                }

                if (claimedCount > 0) {
                    showTip(`成功领取${claimedCount}个合成进度奖励`, 'success');
                }

                return claimedCount;
            } catch (error) {
                logWeirdTowerMessage(`领取合成进度奖励异常: ${error.message}`, 'error');
                return 0;
            }
        }

        // ====== 一键领取合成 ======
        // 基于钥匙数循环：领取免费钥匙 → 同色合成 → 开未锁宝箱 → 再合成 → 领消耗奖励 → 领进度奖励
        function stopClaimSynthesizeFlow() {
            mergeboxState.claimSynthRunning = false;
            const btn = document.getElementById('claimSynthesizeBtn');
            if (btn) {
                btn.classList.remove('stop');
                btn.textContent = '一键合成';
            }
        }

        // 从 mergeBoxData 增量更新本地 gridMap
        function applyMergeBoxDelta(gridMap, mergeBoxData) {
            if (!mergeBoxData) return;
            if (Array.isArray(mergeBoxData.delPosList)) {
                for (const p of mergeBoxData.delPosList) {
                    if (gridMap[p.gridX]) gridMap[p.gridX][p.gridY] = null;
                }
            }
            if (mergeBoxData.gridMap) {
                for (const colStr of Object.keys(mergeBoxData.gridMap)) {
                    const col = parseInt(colStr);
                    if (!/^\d+$/.test(colStr)) continue;
                    const rowMap = mergeBoxData.gridMap[colStr];
                    if (!rowMap || typeof rowMap !== 'object') continue;
                    if (!gridMap[col]) gridMap[col] = {};
                    for (const rowStr of Object.keys(rowMap)) {
                        if (!/^\d+$/.test(rowStr)) continue;
                        const row = parseInt(rowStr);
                        const it = rowMap[rowStr];
                        if (!it) { gridMap[col][row] = null; continue; }
                        if (it.gridConfId && it.gridConfId !== 0) {
                            gridMap[col][row] = { gridConfId: it.gridConfId, isLock: it.isLock };
                        } else if (it.gridItemId) {
                            gridMap[col][row] = { gridItemId: it.gridItemId };
                        } else {
                            gridMap[col][row] = null;
                        }
                    }
                }
            }
        }

        // 在本地 gridMap 中贪心合并相同 gridItemId
        async function mergeAllSameItems(gridMap) {
            let merged = 0;
            let again = true;
            while (again && mergeboxState.claimSynthRunning) {
                again = false;
                const seen = new Map();
                outer:
                for (let col = 1; col <= 7; col++) {
                    for (let row = 1; row <= 7; row++) {
                        const it = gridMap[col]?.[row];
                        if (it && it.gridItemId) {
                            const id = it.gridItemId;
                            if (seen.has(id)) {
                                const fp = seen.get(id);
                                try {
                                    const r = await executeGameCommand('mergebox_mergeitem', {
                                        actType: 1,
                                        sourcePos: { gridX: fp.col, gridY: fp.row },
                                        targetPos: { gridX: col, gridY: row }
                                    }, '合成物品');
                                    if (r?._rawData?.mergeBox) {
                                        applyMergeBoxDelta(gridMap, r._rawData.mergeBox);
                                        merged++;
                                        again = true;
                                    }
                                } catch (e) {
                                    logWeirdTowerMessage(`合成异常: ${e.message}`, 'warning');
                                }
                                break outer;
                            } else {
                                seen.set(id, { col, row });
                            }
                        }
                    }
                }
            }
            return merged;
        }

        async function claimSynthesizeFlow() {
            if (mergeboxState.claimSynthRunning) {
                stopClaimSynthesizeFlow();
                logWeirdTowerMessage('已请求停止一键合成', 'info');
                return;
            }
            mergeboxState.claimSynthRunning = true;
            const btn = document.getElementById('claimSynthesizeBtn');
            if (btn) {
                btn.classList.add('stop');
                btn.textContent = '运行中…点击停止';
            }
            logWeirdTowerMessage('一键合成开始', 'info');

            let totalMerge = 0, totalOpen = 0, totalCost = 0, totalProgress = 0;

            try {
                // 1. 同步钥匙数
                let keyCount = await syncMergeboxKeyCount();

                // 2. 领取免费钥匙（如有）
                const initInfo = await executeGameCommand('mergebox_getinfo', { actType: 1 }, '获取合成盒子信息');
                const initBox = initInfo?._rawData?.mergeBox;
                if (initBox && (initBox.freeEnergy || 0) > 0) {
                    logWeirdTowerMessage(`领取${initBox.freeEnergy}个免费钥匙...`, 'info');
                    await executeGameCommand('mergebox_claimfreeenergy', { actType: 1 }, '领取免费钥匙');
                    keyCount = await syncMergeboxKeyCount();
                }

                // 3. 主循环：钥匙耗尽前持续合成+开箱
                let safety = 0;
                while (keyCount > 0 && mergeboxState.claimSynthRunning && safety < 200) {
                    safety++;
                    // 取最新格子
                    const info = await executeGameCommand('mergebox_getinfo', { actType: 1 }, '获取合成盒子信息');
                    const box = info?._rawData?.mergeBox;
                    if (!box) { logWeirdTowerMessage('获取合成盒子失败，终止', 'error'); break; }

                    // 顺手再领免费钥匙
                    if ((box.freeEnergy || 0) > 0) {
                        await executeGameCommand('mergebox_claimfreeenergy', { actType: 1 }, '领取免费钥匙');
                        keyCount = await syncMergeboxKeyCount();
                    }

                    // 构建本地 gridMap
                    const gridMap = {};
                    for (let c = 1; c <= 7; c++) { gridMap[c] = {}; for (let r = 1; r <= 7; r++) gridMap[c][r] = null; }
                    if (box.gridMap) applyMergeBoxDelta(gridMap, { gridMap: box.gridMap });

                    // 先合并所有同色
                    totalMerge += await mergeAllSameItems(gridMap);
                    if (!mergeboxState.claimSynthRunning) break;

                    // 找一个可开的未锁宝箱
                    let opened = false;
                    for (let c = 1; c <= 7 && !opened; c++) {
                        for (let r = 1; r <= 7 && !opened; r++) {
                            const it = gridMap[c]?.[r];
                            if (it && it.gridConfId && !it.isLock) {
                                try {
                                    const or = await executeGameCommand('mergebox_openbox', {
                                        actType: 1,
                                        pos: { gridX: c, gridY: r }
                                    }, '开宝箱');
                                    if (or?._rawData?.mergeBox) {
                                        applyMergeBoxDelta(gridMap, or._rawData.mergeBox);
                                    }
                                    opened = true;
                                    totalOpen++;
                                    keyCount--;
                                    // 开后继续合并
                                    totalMerge += await mergeAllSameItems(gridMap);
                                } catch (e) {
                                    logWeirdTowerMessage(`开宝箱异常: ${e.message}`, 'warning');
                                    opened = true; // 跳出避免死循环
                                }
                            }
                        }
                    }

                    if (!opened) {
                        logWeirdTowerMessage('无可开宝箱，结束循环', 'info');
                        break;
                    }

                    // 领取消耗钥匙档位奖励
                    const info2 = await executeGameCommand('mergebox_getinfo', { actType: 1 }, '获取合成盒子信息');
                    const box2 = info2?._rawData?.mergeBox;
                    if (box2) {
                        const cc = box2.costClaimCnt || 0, ct = box2.costTotalCnt || 0;
                        if (ct > cc) {
                            try {
                                await executeGameCommand('mergebox_claimcostprogress', { actType: 1 }, '领取消耗奖励');
                                totalCost += (ct - cc);
                            } catch (e) { logWeirdTowerMessage(`领取消耗奖励异常: ${e.message}`, 'warning'); }
                        }
                        // 领取合成进度奖励
                        const tm = box2.taskMap || {}, tcm = box2.taskClaimMap || {};
                        for (const tid of Object.keys(tm)) {
                            if (!/^\d+$/.test(tid)) continue;
                            if ((tm[tid] || 0) > 0 && !Object.prototype.hasOwnProperty.call(tcm, tid)) {
                                try {
                                    await executeGameCommand('mergebox_claimmergeprogress', { actType: 1, taskId: parseInt(tid) }, '领取合成进度奖励');
                                    totalProgress++;
                                } catch (e) { logWeirdTowerMessage(`领取进度奖励异常 taskId=${tid}: ${e.message}`, 'warning'); }
                            }
                        }
                    }

                    // 同步钥匙
                    keyCount = await syncMergeboxKeyCount();
                    await new Promise(r => setTimeout(r, 100));
                }

                const summary = `一键合成完成: 合成${totalMerge}次, 开箱${totalOpen}次, 消耗奖励${totalCost}, 进度奖励${totalProgress}`;
                logWeirdTowerMessage(summary, 'success');
                showTip(summary, 'success');
            } catch (e) {
                logWeirdTowerMessage(`一键合成异常: ${e.message}`, 'error');
                showTip('一键合成出错', 'error');
            } finally {
                stopClaimSynthesizeFlow();
                await getMergeboxInfo();
            }
        }

        // ====== 查询俱乐部成员层数 ======
        function escapeHtml(s) {
            return String(s == null ? '' : s).replace(/[<>&"']/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": '&#39;' }[c]));
        }

        async function queryLegionTowerProgress() {
            const btn = document.getElementById('queryLegionTowerBtn');
            if (btn) { btn.disabled = true; btn.textContent = '查询中...'; }
            try {
                const legionResp = await executeGameCommand('legion_getinfo', {}, '获取俱乐部信息');
                const members = legionResp?._rawData?.info?.members;
                if (!members) {
                    showTip('无法获取俱乐部信息（未加入俱乐部？）', 'warning');
                    return;
                }
                const memberList = [];
                for (const mid of Object.keys(members)) {
                    const m = members[mid] || {};
                    memberList.push({
                        roleId: parseInt(mid),
                        headImg: m.headImg || '',
                        name: m.name || '--'
                    });
                }
                if (memberList.length === 0) {
                    showTip('俱乐部内没有成员', 'warning');
                    return;
                }
                const towerResp = await executeGameCommand('evotower_getlegionjoinmembers', {}, '获取俱乐部爬塔进度');
                const memberScores = towerResp?._rawData?.memberScores || {};

                showLegionTowerDialog(memberList, memberScores);
            } catch (e) {
                logWeirdTowerMessage(`查询俱乐部成员层数异常: ${e.message}`, 'error');
                showTip('查询失败，请重试', 'error');
            } finally {
                if (btn) { btn.disabled = false; btn.textContent = '查询俱乐部成员层数'; }
            }
        }

        function showLegionTowerDialog(memberList, memberScores) {
            // 排序：层数从高到低，未参加置末
            memberList.sort((a, b) => {
                const sa = memberScores[String(a.roleId)];
                const sb = memberScores[String(b.roleId)];
                const va = (sa !== undefined && sa !== null) ? sa : -1;
                const vb = (sb !== undefined && sb !== null) ? sb : -1;
                return vb - va;
            });

            const overlay = document.createElement('div');
            overlay.style.cssText = 'position:fixed;inset:0;display:flex;align-items:center;justify-content:center;z-index:99999;background:rgba(0,0,0,0.5);padding:14px;';
            overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });

            const dialog = document.createElement('div');
            dialog.style.cssText = 'position:relative;width:420px;max-width:94vw;border-radius:12px;background:#ffffff;color:#333;box-shadow:0 16px 48px rgba(0,0,0,0.25);overflow:hidden;';

            let rowsHtml = '';
            memberList.forEach(m => {
                const idStr = String(m.roleId);
                const raw = memberScores[idStr];
                let floor = '未参加', floorStyle = 'color:#a0aec0;';
                if (raw !== undefined && raw !== null) {
                    if (raw === 0) {
                        floor = '1-1';
                    } else {
                        const chapter = Math.floor(raw / 10) + 1;
                        const f = (raw % 10) + 1;
                        floor = `${chapter}-${f}`;
                    }
                    floorStyle = 'color:#2563eb;font-weight:600;';
                }
                const initial = escapeHtml(((m.name || '?').trim().charAt(0)) || '?');
                const fallback = `<div style="width:36px;height:36px;border-radius:50%;margin-right:10px;background:#dbeafe;color:#1e3a8a;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:14px;flex-shrink:0;">${initial}</div>`;
                const head = m.headImg
                    ? `<img src="${escapeHtml(m.headImg)}" referrerpolicy="no-referrer" style="width:36px;height:36px;border-radius:50%;margin-right:10px;border:1px solid #e5e7eb;object-fit:cover;background:#eee;flex-shrink:0;" onerror="this.outerHTML=this.dataset.fb" data-fb='${fallback.replace(/'/g, "&#39;")}'>`
                    : fallback;
                rowsHtml += `
                    <div style="display:flex;align-items:center;padding:8px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;margin-bottom:6px;">
                        ${head}
                        <div style="flex:1;min-width:0;">
                            <div style="font-size:12px;font-weight:600;color:#333;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(m.name)}</div>
                            <div style="font-size:10px;color:#6b7280;">ID: ${m.roleId}</div>
                        </div>
                        <div style="font-size:14px;${floorStyle}">${floor}</div>
                    </div>
                `;
            });

            dialog.innerHTML = `
                <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px 14px;border-bottom:1px solid #e5e7eb;">
                    <div style="font-weight:700;font-size:14px;">俱乐部成员层数</div>
                    <div style="display:flex;gap:6px;">
                        <button data-act="export" style="padding:4px 12px;border-radius:6px;border:none;background:#2563eb;color:#fff;cursor:pointer;font-size:12px;">导出图片</button>
                        <button data-act="close" style="padding:4px 12px;border-radius:6px;border:none;background:#e5e7eb;color:#333;cursor:pointer;font-size:12px;">关闭</button>
                    </div>
                </div>
                <div style="max-height:60vh;overflow-y:auto;padding:12px;">
                    ${rowsHtml}
                </div>
                <div style="padding:8px;text-align:center;font-size:11px;color:#6b7280;border-top:1px solid #e5e7eb;">共 ${memberList.length} 位成员</div>
            `;

            dialog.querySelector('[data-act="close"]').addEventListener('click', () => overlay.remove());
            dialog.querySelector('[data-act="export"]').addEventListener('click', () => {
                exportLegionTowerImage(memberList, memberScores);
            });
            overlay.appendChild(dialog);
            document.body.appendChild(overlay);
        }

        // 计算楼层文本（与对话框一致）
        function computeFloorText(raw) {
            if (raw === undefined || raw === null) return { text: '未参加', joined: false };
            if (raw === 0) return { text: '1-1', joined: true };
            const chapter = Math.floor(raw / 10) + 1;
            const f = (raw % 10) + 1;
            return { text: `${chapter}-${f}`, joined: true };
        }

        // 尝试加载头像（带 crossOrigin），失败返回 null
        function loadAvatarSafe(url, timeoutMs = 4000) {
            return new Promise(resolve => {
                if (!url) { resolve(null); return; }
                const img = new Image();
                let done = false;
                const finish = (val) => { if (done) return; done = true; resolve(val); };
                const timer = setTimeout(() => finish(null), timeoutMs);
                img.crossOrigin = 'anonymous';
                img.referrerPolicy = 'no-referrer';
                img.onload = () => { clearTimeout(timer); finish(img); };
                img.onerror = () => { clearTimeout(timer); finish(null); };
                try { img.src = url; } catch (e) { clearTimeout(timer); finish(null); }
            });
        }

        // 将俱乐部成员层数列表导出为 PNG 图片（纯 Canvas 绘制，尝试加载真实头像）
        async function exportLegionTowerImage(memberList, memberScores) {
            const btn = document.querySelector('[data-act="export"]');
            const oldText = btn ? btn.textContent : '';
            try {
                if (btn) { btn.disabled = true; btn.textContent = '生成中…'; }

                // 1. 预加载所有头像
                const avatars = await Promise.all(memberList.map(m => loadAvatarSafe(m.headImg)));

                const dpr = Math.max(1, Math.min(window.devicePixelRatio || 1, 2));
                const width = 480;
                const headerH = 56;
                const rowH = 52;
                const footerH = 36;
                const padX = 16;
                const height = headerH + rowH * memberList.length + footerH;

                // 渲染函数：useImages=false 时强制使用首字母占位（用于跨域污染回退）
                const render = (useImages) => {
                    const canvas = document.createElement('canvas');
                    canvas.width = Math.round(width * dpr);
                    canvas.height = Math.round(height * dpr);
                    canvas.style.width = width + 'px';
                    canvas.style.height = height + 'px';
                    const ctx = canvas.getContext('2d');
                    ctx.scale(dpr, dpr);

                    ctx.fillStyle = '#ffffff';
                    ctx.fillRect(0, 0, width, height);

                    ctx.fillStyle = '#111827';
                    ctx.font = 'bold 18px "Microsoft YaHei", sans-serif';
                    ctx.textBaseline = 'middle';
                    ctx.fillText('俱乐部成员层数', padX, headerH / 2);

                    ctx.fillStyle = '#6b7280';
                    ctx.font = '12px "Microsoft YaHei", sans-serif';
                    ctx.textAlign = 'right';
                    ctx.fillText(tsStr, width - padX, headerH / 2);
                    ctx.textAlign = 'left';

                    ctx.strokeStyle = '#e5e7eb';
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    ctx.moveTo(0, headerH);
                    ctx.lineTo(width, headerH);
                    ctx.stroke();

                    memberList.forEach((m, idx) => {
                        const y = headerH + idx * rowH;
                        ctx.strokeStyle = '#f3f4f6';
                        ctx.beginPath();
                        ctx.moveTo(padX, y + rowH);
                        ctx.lineTo(width - padX, y + rowH);
                        ctx.stroke();

                        const cx = padX + 18, cy = y + rowH / 2;
                        const r = 16;
                        const img = useImages ? avatars[idx] : null;
                        if (img) {
                            ctx.save();
                            ctx.beginPath();
                            ctx.arc(cx, cy, r, 0, Math.PI * 2);
                            ctx.closePath();
                            ctx.clip();
                            // 等比裁剪 cover
                            const iw = img.naturalWidth || img.width;
                            const ih = img.naturalHeight || img.height;
                            if (iw > 0 && ih > 0) {
                                const scale = Math.max((r * 2) / iw, (r * 2) / ih);
                                const dw = iw * scale, dh = ih * scale;
                                ctx.drawImage(img, cx - dw / 2, cy - dh / 2, dw, dh);
                            }
                            ctx.restore();
                            ctx.beginPath();
                            ctx.arc(cx, cy, r, 0, Math.PI * 2);
                            ctx.strokeStyle = '#e5e7eb';
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            ctx.beginPath();
                            ctx.arc(cx, cy, r, 0, Math.PI * 2);
                            ctx.fillStyle = '#dbeafe';
                            ctx.fill();
                            ctx.fillStyle = '#1e3a8a';
                            ctx.font = 'bold 14px "Microsoft YaHei", sans-serif';
                            ctx.textAlign = 'center';
                            ctx.textBaseline = 'middle';
                            const initial = (m.name || '?').trim().charAt(0) || '?';
                            ctx.fillText(initial, cx, cy);
                            ctx.textAlign = 'left';
                        }

                        ctx.fillStyle = '#111827';
                        ctx.font = '600 13px "Microsoft YaHei", sans-serif';
                        let name = m.name || '';
                        const maxNameW = 240;
                        while (ctx.measureText(name).width > maxNameW && name.length > 0) name = name.slice(0, -1);
                        if ((m.name || '').length > name.length) name += '…';
                        ctx.fillText(name, padX + 44, cy - 8);

                        ctx.fillStyle = '#6b7280';
                        ctx.font = '11px "Microsoft YaHei", sans-serif';
                        ctx.fillText(`ID: ${m.roleId}`, padX + 44, cy + 9);

                        const raw = memberScores[String(m.roleId)];
                        const floor = computeFloorText(raw);
                        ctx.fillStyle = floor.joined ? '#2563eb' : '#a0aec0';
                        ctx.font = floor.joined ? 'bold 16px "Microsoft YaHei", sans-serif' : '14px "Microsoft YaHei", sans-serif';
                        ctx.textAlign = 'right';
                        ctx.fillText(floor.text, width - padX, cy);
                        ctx.textAlign = 'left';
                    });

                    ctx.fillStyle = '#6b7280';
                    ctx.font = '12px "Microsoft YaHei", sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText(`共 ${memberList.length} 位成员`, width / 2, height - footerH / 2);
                    ctx.textAlign = 'left';
                    return canvas;
                };

                const ts = new Date();
                const tsStr = `${ts.getFullYear()}-${String(ts.getMonth() + 1).padStart(2, '0')}-${String(ts.getDate()).padStart(2, '0')} ${String(ts.getHours()).padStart(2, '0')}:${String(ts.getMinutes()).padStart(2, '0')}`;

                // 2. 优先使用真实头像渲染；toBlob 检测到污染则回退
                const tryExport = (canvas) => new Promise((resolve, reject) => {
                    try {
                        canvas.toBlob(blob => {
                            if (!blob) reject(new Error('toBlob 返回空'));
                            else resolve(blob);
                        }, 'image/png');
                    } catch (err) {
                        reject(err);
                    }
                });

                let blob;
                let usedFallback = false;
                try {
                    blob = await tryExport(render(true));
                } catch (e) {
                    logWeirdTowerMessage(`头像污染 canvas，回退首字母占位: ${e.message}`, 'warning');
                    usedFallback = true;
                    blob = await tryExport(render(false));
                }

                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `俱乐部成员层数_${tsStr.replace(/[: ]/g, '_')}.png`;
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                setTimeout(() => URL.revokeObjectURL(url), 1000);
                showTip(usedFallback ? '已导出（头像不可跨域，使用首字母）' : '图片已导出', 'success');
            } catch (e) {
                logWeirdTowerMessage(`导出图片异常: ${e.message}`, 'error');
                showTip('导出失败', 'error');
            } finally {
                if (btn) { btn.disabled = false; btn.textContent = oldText || '导出图片'; }
            }
        }

        // 执行怪异爬塔任务
        async function executeWeirdTowerTask() {
            try {
                weirdTowerTaskState.running = true;
                weirdTowerTaskState.stopRequested = false;

                logWeirdTowerMessage('🗼 怪异爬塔任务开始', 'info');

                // 获取选中的阵容
                const formationSelect = document.getElementById('weirdTowerFormationSelect');
                weirdTowerTaskState.selectedTeam = parseInt(formationSelect?.value) || 1;

                // 切换阵容
                if (!weirdTowerTaskState.hasSwitchedTeam) {
                    const switchSuccess = await switchWeirdTowerTeam(weirdTowerTaskState.selectedTeam);
                    if (!switchSuccess) {
                        logWeirdTowerMessage('切换阵容失败，停止任务', 'error');
                        weirdTowerTaskState.running = false;
                        return;
                    }
                    weirdTowerTaskState.hasSwitchedTeam = true;
                }

                // 获取爬塔信息
                let towerInfo = await getWeirdTowerInfo();
                if (!towerInfo) {
                    logWeirdTowerMessage('无法获取爬塔信息', 'error');
                    weirdTowerTaskState.running = false;
                    return;
                }

                if (towerInfo.energy <= 0) {
                    logWeirdTowerMessage('小鱼干不足，无法挑战', 'warning');
                    showTip('小鱼干不足', 'warning');
                    weirdTowerTaskState.running = false;
                    return;
                }

                // 循环挑战
                while (towerInfo.energy > 0 && !weirdTowerTaskState.stopRequested) {
                    logWeirdTowerMessage(`准备挑战第 ${towerInfo.displayFloor} 层...`, 'info');

                    // 第一步：准备战斗
                    const readyResponse = await executeGameCommand('evotower_readyfight', {}, '准备战斗');
                    if (!readyResponse) {
                        logWeirdTowerMessage('准备战斗失败', 'error');
                        weirdTowerTaskState.loseCount++;
                        updateWeirdTowerUI();
                        break;
                    }

                    // 第二步：执行战斗
                    const fightResponse = await executeGameCommand('evotower_fight', { battleNum: 1, winNum: 1 }, '执行战斗');
                    if (!fightResponse || !fightResponse._rawData || !fightResponse._rawData.evoTower) {
                        logWeirdTowerMessage('战斗响应格式错误', 'error');
                        weirdTowerTaskState.loseCount++;
                        updateWeirdTowerUI();
                        break;
                    }

                    const newEnergy = fightResponse._rawData.evoTower.energy;
                    const winList = fightResponse._rawData.winList || [];
                    const isWin = winList.length > 0 && winList[0] === true;

                    if (isWin) {
                        weirdTowerTaskState.winCount++;
                        logWeirdTowerMessage(`✅ 第 ${towerInfo.displayFloor} 层通关！剩余小鱼干: ${newEnergy}`, 'success');
                    } else {
                        weirdTowerTaskState.loseCount++;
                        logWeirdTowerMessage(`❌ 第 ${towerInfo.displayFloor} 层失败，剩余小鱼干: ${newEnergy}`, 'warning');
                    }

                    // 更新胜负显示
                    updateWeirdTowerUI();

                    // 第三步：获取最新爬塔信息
                    towerInfo = await getWeirdTowerInfo();
                    if (!towerInfo) {
                        logWeirdTowerMessage('获取爬塔信息失败', 'error');
                        break;
                    }

                    // 检查是否刚通关第10层及其倍数层（即当前层是新章节第1层）
                    if (isWin && (towerInfo.rawTowerId % 10 === 0) && towerInfo.rawTowerId > 0) {
                        const chapter = Math.floor(towerInfo.rawTowerId / 10);
                        logWeirdTowerMessage(`🎁 恭喜通关第${chapter}章！准备领取奖励...`, 'info');

                        try {
                            await executeGameCommand('evotower_claimreward', {}, '领取通关奖励');
                            logWeirdTowerMessage(`✅ 成功领取第${chapter}章通关奖励！`, 'success');
                        } catch (rewardErr) {
                            logWeirdTowerMessage(`领取奖励失败: ${rewardErr.message}`, 'warning');
                        }
                    }

                    if (newEnergy <= 0) {
                        logWeirdTowerMessage('小鱼干已耗尽', 'warning');
                        break;
                    }

                    // 延迟400ms继续下一次战斗
                    await new Promise(resolve => setTimeout(resolve, 400));
                }

                const totalBattles = weirdTowerTaskState.winCount + weirdTowerTaskState.loseCount;
                logWeirdTowerMessage(`怪异爬塔完成，共进行 ${totalBattles} 次挑战，胜利 ${weirdTowerTaskState.winCount} 次，失败 ${weirdTowerTaskState.loseCount} 次`, 'success');
                showTip(`怪异爬塔完成 (胜${weirdTowerTaskState.winCount}/负${weirdTowerTaskState.loseCount})`, 'success');

            } catch (err) {
                logWeirdTowerMessage(`怪异爬塔异常: ${err.message}`, 'error');
                showTip('怪异爬塔异常', 'error');
            } finally {
                weirdTowerTaskState.running = false;
            }
        }

        // 怪异爬塔控制按钮事件
        const startWeirdTowerTaskBtn = document.getElementById('startWeirdTowerTask');
        const stopWeirdTowerTaskBtn = document.getElementById('stopWeirdTowerTask');
